-- Ophthalmology: Ocular Trauma
-- US MD/MBBS (4th Year) clinical case blocks
-- Target platform: Supabase (Postgres)
-- Topic Slug: optho-trauma

BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
    v_case_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'optho-trauma' LIMIT 1;
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic slug % not found.', 'optho-trauma';
    END IF;

    ---------------------------------------------------------------------------
    -- CASE 01: The Lime Splattered Eye (V1)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Lime Splattered Eye (V1)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Lime Splattered Eye (V1)', 'A 31-year-old construction worker presents to the emergency department immediately after a bag of wet concrete mix (calcium hydroxide/alkali) burst and splashed into his left eye 30 minutes ago. He reports intense, burning pain, severe tearing, and an inability to open the eye. He rinsed the eye for about 2 minutes at the site before coming in.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 95 bpm | BP: 135/85 mmHg
*   **Visual Acuity:** OS: 20/200; contralateral eye: 20/20
*   **Ocular Examination (OS):** Severe blepharospasm. After instilling topical anesthetic, slit-lamp exam reveals a moderately hazy cornea with a large epithelial defect. There is a prominent area of **limbal blanching and ischemia** (porcelain sclera) involving 180 degrees of the limbus. The conjunctiva is pale and necrotic in the blanched areas. The initial paper pH test of the conjunctival sac shows a pH of 11.0.', 1) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 31-year-old construction worker presents to the emergency department immediately after a bag of wet concrete mix (calcium hydroxide/alkali) burst and splashed into his left eye 30 minutes ago. He reports intense, burning pain, severe tearing, and an inability to open the eye. He rinsed the eye for about 2 minutes at the site before coming in.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 95 bpm | BP: 135/85 mmHg
*   **Visual Acuity:** OS: 20/200; contralateral eye: 20/20
*   **Ocular Examination (OS):** Severe blepharospasm. After instilling topical anesthetic, slit-lamp exam reveals a moderately hazy cornea with a large epithelial defect. There is a prominent area of **limbal blanching and ischemia** (porcelain sclera) involving 180 degrees of the limbus. The conjunctiva is pale and necrotic in the blanched areas. The initial paper pH test of the conjunctival sac shows a pH of 11.0.', "order" = 1 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the most immediate, critical next step in the management of this patient?', '["Prepare the patient for urgent surgical corneal transplant (penetrating keratoplasty)", "Instill topical broad-spectrum antibiotic drops and apply a tight pressure patch", "Administer systemic high-dose intravenous corticosteroids immediately", "Perform copious irrigation with sterile saline or water using a Morgan lens until the ocular surface pH is neutralized to 7.0 - 7.2", "Order an urgent CT scan of the brain and orbits to rule out foreign bodies"]'::jsonb, 3, 'An ocular chemical burn is a true emergency. The **most critical immediate step is copious irrigation** with sterile saline, balanced salt solution, or tap water (often using a Morgan lens) to flush the chemical. Irrigation must be continued continuously until the ocular surface pH is **fully neutralized (pH 7.0 - 7.2)**, measured 5-10 minutes after stopping irrigation. No other diagnostic test or treatment should delay this.'),
    (v_case_id, 'Why are alkali burns generally considered far more destructive and dangerous to the eye than acid burns?', '["Alkalies cause saponification of cell membrane lipids and rapidly penetrate deep into the cornea and anterior chamber", "Alkalies trigger immediate, severe bacterial keratitis within minutes of contact", "Alkalies selectively crystallize within the lens, causing immediate explosive cataract", "Alkalies induce a rapid, autoimmune destruction of the contralateral eye", "Alkalies directly coagulate corneal proteins, forming a barrier that limits deep tissue penetration"]'::jsonb, 0, '**Alkali substances** (like ammonia, lye, and lime/wet concrete) are highly lipophilic and cause **saponification of cell membrane lipids**. This allows them to **rapidly penetrate** through the corneal epithelium, stroma, and into the anterior chamber within minutes, causing extensive internal damage. In contrast, **acids** cause **coagulation of corneal proteins**, which forms a physical barrier that limits further deep penetration of the acid.'),
    (v_case_id, 'What is the clinical significance of ''limbal blanching and ischemia'' in a chemical burn?', '["It is a benign finding that represents temporary vasospasm and resolves spontaneously within 24 hours", "It signifies that a metallic foreign body is embedded in the sclera", "It indicates that the intraocular pressure has dropped to 0 mmHg", "It represents a localized type I hypersensitivity reaction to concrete proteins", "It indicates destruction of the limbal stem cells, which are essential for regenerating the corneal epithelium, signifying a poor prognosis"]'::jsonb, 4, '**Limbal blanching and ischemia** (appearing as a white, bloodless ''porcelain'' ring at the cornea-sclera junction) is a severe prognostic sign. The limbus houses the **limbal epithelial stem cells**, which are responsible for the continuous regeneration and maintenance of the corneal epithelium. Destruction of these stem cells leads to chronic epithelial defects, corneal scarring, visual degradation, and conjunctivalization.');

    ---------------------------------------------------------------------------
    -- CASE 02: The Fingernail Scratch (V1)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Fingernail Scratch (V1)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Fingernail Scratch (V1)', 'A 39-year-old female presents to the clinic with intense pain, a severe foreign body sensation, constant tearing, and photophobia in her left eye. She reports that her 8-month-old infant accidentally scratched her eye with a fingernail while playing this morning.

**Physical Examination:**
*   **Vitals:** Temp: 98.4°F | HR: 73 bpm | BP: 123/87 mmHg
*   **Visual Acuity:** OS: 20/30 (improved with pinhole); contralateral eye: 20/20
*   **Ocular Examination (OS):** Marked conjunctival injection. Instillation of fluorescein dye and examination under cobalt blue light reveals a sharply demarcated, linear, bright green glowing area of epithelial loss measuring 3 mm x 2 mm in the central cornea. There is no white corneal infiltrate, no corneal thinning, and the anterior chamber is quiet. Pupil is reactive and normal.', 2) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 39-year-old female presents to the clinic with intense pain, a severe foreign body sensation, constant tearing, and photophobia in her left eye. She reports that her 8-month-old infant accidentally scratched her eye with a fingernail while playing this morning.

**Physical Examination:**
*   **Vitals:** Temp: 98.4°F | HR: 73 bpm | BP: 123/87 mmHg
*   **Visual Acuity:** OS: 20/30 (improved with pinhole); contralateral eye: 20/20
*   **Ocular Examination (OS):** Marked conjunctival injection. Instillation of fluorescein dye and examination under cobalt blue light reveals a sharply demarcated, linear, bright green glowing area of epithelial loss measuring 3 mm x 2 mm in the central cornea. There is no white corneal infiltrate, no corneal thinning, and the anterior chamber is quiet. Pupil is reactive and normal.', "order" = 2 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the most likely diagnosis, and what is the first-line pharmacotherapy?', '["Herpes simplex dendritic keratitis; topical acyclovir gel and oral valacyclovir", "Infectious bacterial keratitis; topical fortified vancomycin and tobramycin every 30 minutes", "Corneal abrasion; topical broad-spectrum antibiotic drops or ointment (e.g. erythromycin or polymyxin/trimethoprim)", "Dry eye syndrome; lifetime preservative-free artificial tears only", "Corneal ulcer; immediate outpatient surgical superficial keratectomy"]'::jsonb, 2, 'This is a simple **corneal abrasion** (epithelial defect without underlying stromal infection). First-line therapy consists of **topical broad-spectrum antibiotic drops or ointment** to prevent secondary bacterial infection while the epithelium heals, along with oral analgesics for pain control. Ointment (e.g., erythromycin) provides lubrication and comfort.'),
    (v_case_id, 'Why is the prescription of topical anesthetic drops (e.g. proparacaine) for home pain control strictly CONTRAINDICATED in patients with corneal abrasions?', '["Topical anesthetics are directly toxic to the corneal epithelium, inhibit healing, and block the protective blink reflex, leading to severe corneal melting", "Topical anesthetics cause permanent pupillary dilation and acute angle closure", "Topical anesthetics promote the rapid growth of fungal spores in the stroma", "Topical anesthetics neutralize the efficacy of topical antibiotics", "Topical anesthetics cause systemic cardiovascular toxicity and bradycardia through lacrimal absorption"]'::jsonb, 0, 'Prescribing **topical anesthetics (like proparacaine or tetracaine) for home use is strictly contraindicated**. These drugs are **highly toxic to the corneal epithelium** (epitheliotoxic), severely retard epithelial migration and wound healing, and **abolish the protective corneal blink reflex**. Abuse of these drops leads to progressive, painless **corneal stromal melting, ulceration, and permanent scarring**.'),
    (v_case_id, 'What is the most common long-term complication of a corneal abrasion caused by organic trauma (e.g., a fingernail or tree branch)?', '["Sympathetic ophthalmia in the contralateral eye", "Late-onset ectopia lentis and lens subluxation", "Autoimmune uveitis associated with HLA-B27", "Secondary open-angle pigmentary glaucoma", "Recurrent corneal erosion syndrome, due to poor basement membrane adhesion"]'::jsonb, 4, 'A classic complication of organic abrasions (fingernails, paper cuts, tree branches) is **Recurrent Corneal Erosion (RCE) syndrome**. The regenerated corneal epithelial cells fail to form proper hemidesmosomes and adhere securely to the underlying **Bowman''s membrane and basement membrane**. Weeks or months later, typically upon opening the eyes in the morning, the dry eyelid adheres to the loose epithelium and rips it off, causing a recurrence of severe pain and abrasion.');

    ---------------------------------------------------------------------------
    -- CASE 03: The Machinist's Rust (V1)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Machinist''s Rust (V1)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Machinist''s Rust (V1)', 'A 34-year-old machinist presents with a 24-hour history of redness, gritty pain, and tearing in her left eye.  She reports that she was grinding steel yesterday afternoon without safety goggles and felt something fly into  her eye.

**Physical Examination:**
*   **Vitals:** Temp: 98.4°F | HR: 74 bpm | BP: 122/76 mmHg
*   **Visual Acuity:** OS: 20/30; contralateral eye: 20/20
*   **Ocular Examination (OS):** Slit-lamp biomicroscopy reveals a tiny, dark, metallic foreign body embedded in the superficial corneal stroma at the 4 o''clock position, outside of the visual axis. The foreign body is surrounded by a distinct, circular, orange-brown halo of **rust ring** diffusing into the stroma. The anterior chamber is deep and quiet (0 cells). No Seidel sign is present.', 3) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 34-year-old machinist presents with a 24-hour history of redness, gritty pain, and tearing in her left eye.  She reports that she was grinding steel yesterday afternoon without safety goggles and felt something fly into  her eye.

**Physical Examination:**
*   **Vitals:** Temp: 98.4°F | HR: 74 bpm | BP: 122/76 mmHg
*   **Visual Acuity:** OS: 20/30; contralateral eye: 20/20
*   **Ocular Examination (OS):** Slit-lamp biomicroscopy reveals a tiny, dark, metallic foreign body embedded in the superficial corneal stroma at the 4 o''clock position, outside of the visual axis. The foreign body is surrounded by a distinct, circular, orange-brown halo of **rust ring** diffusing into the stroma. The anterior chamber is deep and quiet (0 cells). No Seidel sign is present.', "order" = 3 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the correct management of this patient''s corneal foreign body and associated rust ring?', '["Remove the metallic foreign body immediately, and remove the rust ring either today or within 24-48 hours using a sterile needle, spud, or rotating ophthalmic burr under slit-lamp visualization", "Apply a pressure patch for 1 week and wait for the rust ring to dissolve systemically", "Initiate topical corticosteroid drops hourly to dissolve the iron deposits", "Flush the eye with systemic chelating agents (EDTA) for 12 hours", "Refer the patient for urgent surgical lamellar keratoplasty in the operating room"]'::jsonb, 0, 'Management requires **removal of both the foreign body and the rust ring**. The metallic foreign body is removed immediately using a sterile needle or spud under slit-lamp magnification. The **rust ring** (oxidized iron that diffuses into the stroma) is toxic and retards healing; it must be removed either at the same time or within 24-48 hours (when it softens) using a **rotating ophthalmic burr (Algerbrush)** or needle.'),
    (v_case_id, 'Within what timeframe does a metallic iron-containing corneal foreign body begin to form a visible rust ring in the stroma?', '["Only after 1 to 2 weeks of neglect", "Immediately upon impact (within seconds)", "Exactly 30 days post-injury", "Within 8 to 24 hours of injury", "Iron foreign bodies never form rust rings in the eye"]'::jsonb, 3, 'A metallic, iron-containing foreign body oxidizes rapidly when exposed to the moist environment of the tear film and corneal stroma. A **visible orange-brown rust ring** of iron deposition begins to form in the surrounding stroma **within 8 to 24 hours** of the injury. Early removal of the foreign body prevents extensive rust ring formation.'),
    (v_case_id, 'Following the removal of a corneal foreign body, which of the following is essential to prevent secondary complications?', '["Topical broad-spectrum antibiotics, checking tetanus vaccination status, and avoiding patching if the wound is dirty", "Implantation of a soft contact lens directly over the rust ring", "Topical corticosteroid drops every hour for 2 weeks to prevent scarring", "Dilating the pupil with atropine for 6 months to maintain muscle rest", "Oral acyclovir to prevent viral activation"]'::jsonb, 0, 'Following foreign body and rust removal, the patient has a corneal epithelial defect (abrasion). Essential care includes **topical broad-spectrum antibiotics** (drops/ointment) to prevent bacterial keratitis, and **updating their tetanus vaccination status** (as corneal wounds can rarely harbor tetanus). The eye is typically **not patched** if there is any suspicion of organic contamination or Pseudomonas risk (e.g. contact lens wearers).');

    ---------------------------------------------------------------------------
    -- CASE 04: The Squash Ball Collision (V1)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Squash Ball Collision (V1)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Squash Ball Collision (V1)', 'A 22-year-old African American male presents to the emergency department after being struck directly in the right eye by a squash ball during a game. He reports sudden, severe pain and a dramatic decrease in vision. He denies any prior eye problems but notes he has sickle cell trait.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 88 bpm | BP: 122/78 mmHg
*   **Visual Acuity:** OD: 20/100; contralateral eye: 20/20
*   **Ocular Examination (OD):** Periorbital ecchymosis. Slit-lamp biomicroscopy reveals a prominent, layered column of red blood cells filling the inferior 30% of the anterior chamber (Grade II hyphema). The pupil is sluggish. The ciliary body is intact, and there is no open globe injury. The intraocular pressure is 34 mmHg (significantly elevated).', 4) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 22-year-old African American male presents to the emergency department after being struck directly in the right eye by a squash ball during a game. He reports sudden, severe pain and a dramatic decrease in vision. He denies any prior eye problems but notes he has sickle cell trait.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 88 bpm | BP: 122/78 mmHg
*   **Visual Acuity:** OD: 20/100; contralateral eye: 20/20
*   **Ocular Examination (OD):** Periorbital ecchymosis. Slit-lamp biomicroscopy reveals a prominent, layered column of red blood cells filling the inferior 30% of the anterior chamber (Grade II hyphema). The pupil is sluggish. The ciliary body is intact, and there is no open globe injury. The intraocular pressure is 34 mmHg (significantly elevated).', "order" = 4 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the primary underlying anatomical source of blood in a traumatic hyphema?', '["Exudative hemorrhage from damaged corneal endothelial cells", "Bleeding from the retinal arterioles that dissects forward through the vitreous", "Rupture of Schlemm''s canal with retrograde venous flow into the chamber", "Rupture of the blood vessels of the ciliary body face or iris root due to blunt contusion forces", "Rupture of ciliary body processes due to systemic hypertension"]'::jsonb, 3, 'A traumatic hyphema (blood in the anterior chamber) is caused by blunt contusion forces that compress the globe along its axial diameter and expand it equatorially. This sudden stretching force tears the anterior segment tissues, resulting in the **rupture of blood vessels of the ciliary body face, iris root, or major arterial circle of the iris**.'),
    (v_case_id, 'Why is a traumatic hyphema particularly dangerous in patients with sickle cell trait or disease, and what is the target IOP management?', '["Sickled erythrocytes are rigid and clog the trabecular meshwork, causing rapid, severe IOP elevation; even mild IOP elevation (>24 mmHg) can cause optic nerve ischemia, requiring aggressive control and avoiding systemic acetazolamide", "The blood in the anterior chamber reacts with sickle hemoglobin to cause irreversible iris necrosis within 2 hours", "Sickle cell patients are completely immune to elevated IOP, so no treatment is required", "Sickle cell trait prevents the blood from clotting, causing continuous, unstoppable bleeding that fills the entire eye", "Sickle cell patients have fragile corneas that melt rapidly when exposed to red blood cells in the anterior chamber"]'::jsonb, 0, 'Hyphema in a **sickle cell** patient is a high-risk situation. In the hypoxic, hyperosmolar anterior chamber, red blood cells sickling occurs. The rigid **sickled erythrocytes clog the trabecular meshwork**, causing rapid, severe IOP spikes. Furthermore, the compromised microcirculation of the optic nerve head in sickle cell patients makes them highly vulnerable to ischemic damage, so **even mild IOP elevations (>24 mmHg for >24 hours) can cause permanent optic nerve atrophy or central retinal artery occlusion**. Systemic **acetazolamide is strictly contraindicated** as it promotes sickling.'),
    (v_case_id, 'What represents the core conservative management recommendations for a patient with an uncomplicated traumatic hyphema?', '["Initiation of systemic anticoagulation (warfarin) and vigorous physical exercise to clear the blood", "Applying a tight pressure patch and scheduling follow-up in 1 month", "Bed rest with head of bed elevated 30-45 degrees, a rigid eye shield, topical cycloplegic drops, and avoiding aspirin/NSAIDs", "Strict flat bed rest, a pressure patch, daily aspirin to prevent clotting, and hourly topical corticosteroids", "Immediate outpatient surgical anterior chamber washout and trabeculectomy"]'::jsonb, 2, 'Conservative management for hyphema includes: (1) **bed rest with the head of the bed elevated 30 to 45 degrees** (allows blood to settle inferiorly, clearing the visual axis and preventing trabecular clogging), (2) a **rigid metal or plastic eye shield** to prevent accidental touch, (3) **topical cycloplegic drops** (e.g. atropine/cyclopentolate) for pupillary rest and pain control, and (4) **avoiding aspirin/NSAIDs** (which increase the risk of re-bleeding, typically occurring on days 3-5).');

    ---------------------------------------------------------------------------
    -- CASE 05: The Fist and Floor (V1)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Fist and Floor (V1)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Fist and Floor (V1)', 'A 19-year-old female presents to the emergency department after being punched in the right eye during a street fight. She complains of pain, severe swelling, bruising, and double vision (diplopia), especially when looking up.  She also notes that her right cheek and upper lip feel numb.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 82 bpm | BP: 120/80 mmHg
*   **Ocular Examination (OD):** Marked periorbital ecchymosis and edema. Subconjunctival hemorrhage is present. There is **vertical diplopia on upgaze**, and testing of extraocular motility reveals a severe **restriction of elevation** in the affected eye. Sensation to light touch is significantly decreased over the ipsilateral cheek, side of the nose, and upper lip. CT scan of the orbits reveals a fracture of the **orbital floor** with herniation of orbital fat and entrapment of the **inferior rectus muscle**.', 5) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 19-year-old female presents to the emergency department after being punched in the right eye during a street fight. She complains of pain, severe swelling, bruising, and double vision (diplopia), especially when looking up.  She also notes that her right cheek and upper lip feel numb.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 82 bpm | BP: 120/80 mmHg
*   **Ocular Examination (OD):** Marked periorbital ecchymosis and edema. Subconjunctival hemorrhage is present. There is **vertical diplopia on upgaze**, and testing of extraocular motility reveals a severe **restriction of elevation** in the affected eye. Sensation to light touch is significantly decreased over the ipsilateral cheek, side of the nose, and upper lip. CT scan of the orbits reveals a fracture of the **orbital floor** with herniation of orbital fat and entrapment of the **inferior rectus muscle**.', "order" = 5 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the diagnosis, and which extraocular muscle is classically entrapped in this condition?', '["Orbital floor blowout fracture; entrapment of the inferior rectus muscle", "Superior orbital fissure syndrome; entrapment of all extraocular muscles", "Medial orbital wall blowout fracture; entrapment of the medial rectus muscle", "Orbital roof blowout fracture; entrapment of the superior rectus muscle", "Lateral orbital wall fracture; entrapment of the lateral rectus muscle"]'::jsonb, 0, 'This patient has an **orbital floor blowout fracture** (the most common type). The classic presentation is **vertical diplopia on upgaze** and **restriction of eye elevation** due to the mechanical **entrapment of the inferior rectus muscle** (and/or surrounding orbital fat/fascia) within the fractured bony fragments of the maxillary bone.'),
    (v_case_id, 'Which cranial nerve is injured, resulting in the numbness of the cheek, side of the nose, and upper lip?', '["Oculomotor nerve (CN III), inferior division", "Abducens nerve (CN VI)", "Infraorbital nerve, a branch of the maxillary division of the trigeminal nerve (CN V2)", "Supraorbital nerve, a branch of the ophthalmic division of the trigeminal nerve (CN V1)", "Facial nerve (CN VII), buccal branch"]'::jsonb, 2, 'The **infraorbital nerve** (a terminal branch of the **maxillary division of the trigeminal nerve, CN V2**) travels along the infraorbital groove and canal in the orbital floor. Fractures of the orbital floor frequently bruise, compress, or lacerate this nerve, resulting in **hypoesthesia/numbness of the ipsilateral cheek, lateral nose, upper lip, and anterior maxillary gingiva**.'),
    (v_case_id, 'Which of the following is a critical instruction that must be given to patients diagnosed with an acute orbital blowout fracture?', '["Avoid sleeping with their head elevated", "Apply a high-pressure patch over the eye for 72 hours", "Vigorously blow their nose to clear any blood or fluid from the maxillary sinus", "Perform heavy weightlifting to reduce intraorbital venous pressure", "Strictly avoid blowing their nose to prevent orbital emphysema and potential optic nerve compression"]'::jsonb, 4, 'Patients with acute orbital fractures must be **strictly instructed not to blow their nose**. Blowing the nose creates high pressure in the paranasal sinuses (maxillary/ethmoid). This pressure forces air and sinus bacteria through the fracture line into the orbit, causing **orbital emphysema** (which can compress the optic nerve and cause blindness) and increasing the risk of **orbital cellulitis**.');

    ---------------------------------------------------------------------------
    -- CASE 06: The Flying Metal Shard (V1)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Flying Metal Shard (V1)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Flying Metal Shard (V1)', 'A 36-year-old construction worker is brought to the emergency department after a metal shard flew off a hammering tool and struck her left eye. He was not wearing safety goggles. He complains of sudden, severe pain and instant, profound loss of vision in that eye. He reports a watery discharge flowing from the eye immediately after the impact.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 90 bpm | BP: 130/80 mmHg
*   **Visual Acuity:** OS: Hand Motion (light projection intact); contralateral eye: 20/20
*   **Ocular Examination (OS):** Diffuse subconjunctival hemorrhage. The anterior chamber is shallow and filled with RBCs (microhyphema). The pupil is peaked and **teardrop-shaped**, pointing towards a 3-mm laceration at the limbus. A small amount of dark, uveal tissue (iris) is prolapsing through the wound. Examination of the wound under cobalt blue light reveals a **positive Seidel sign** (a clear stream of aqueous humor diluting and washing away fluorescein dye).', 6) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 36-year-old construction worker is brought to the emergency department after a metal shard flew off a hammering tool and struck her left eye. He was not wearing safety goggles. He complains of sudden, severe pain and instant, profound loss of vision in that eye. He reports a watery discharge flowing from the eye immediately after the impact.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 90 bpm | BP: 130/80 mmHg
*   **Visual Acuity:** OS: Hand Motion (light projection intact); contralateral eye: 20/20
*   **Ocular Examination (OS):** Diffuse subconjunctival hemorrhage. The anterior chamber is shallow and filled with RBCs (microhyphema). The pupil is peaked and **teardrop-shaped**, pointing towards a 3-mm laceration at the limbus. A small amount of dark, uveal tissue (iris) is prolapsing through the wound. Examination of the wound under cobalt blue light reveals a **positive Seidel sign** (a clear stream of aqueous humor diluting and washing away fluorescein dye).', "order" = 6 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the diagnosis, and what is the significance of the teardrop pupil and positive Seidel test?', '["Severe corneal abrasion; teardrop pupil is a normal physiological variant, Seidel test is positive in any tear film excess", "Orbital compartment syndrome; teardrop pupil indicates optic nerve compression, Seidel test is negative", "Ruptured globe / open globe injury; teardrop pupil points to the site of wound, positive Seidel test indicates active aqueous leakage from a full-thickness laceration", "Traumatic uveitis; teardrop pupil represents severe ciliary spasm, Seidel test is positive due to high protein exudation", "Traumatic hyphema; teardrop pupil is due to iris sphincter rupture, Seidel test indicates red blood cells clogging the cornea"]'::jsonb, 2, 'This is a **ruptured globe (open globe injury)**, a surgical emergency. The **teardrop pupil** is highly characteristic, as intraocular pressure forces the iris to prolapse towards the escape wound, pointing like an arrow to the laceration. The **positive Seidel test** (aqueous fluid stream washing away fluorescein dye under cobalt blue light) confirms a **full-thickness wound** with active external leakage of aqueous humor.'),
    (v_case_id, 'Which of the following is strictly CONTRAINDICATED during the emergency department evaluation of a suspected ruptured globe?', '["Ordering a high-resolution CT scan of the orbits without contrast", "Administering systemic intravenous antibiotics and antiemetics", "Placing a rigid, non-contact eye shield resting on the orbital bones", "Keeping the patient strictly NPO (nothing by mouth) for surgery", "Performing applanation tonometry (IOP measurement) or applying any pressure to the globe"]'::jsonb, 4, 'In a suspected ruptured globe, **any manipulation or pressure on the eye is strictly contraindicated**. This includes performing **tonometry (IOP measurement)**, opening the eyelids forcibly, or performing a dilated fundus exam. Any external pressure can cause **extrusion of the intraocular contents** (iris, lens, vitreous, retina) through the wound, resulting in irreversible blindness.'),
    (v_case_id, 'What are the immediate, first-line management steps for a patient with a confirmed ruptured globe in the emergency department?', '["Perform immediate bedside surgical suturing of the cornea under topical anesthesia", "Perform immediate anterior chamber paracentesis to lower the intraocular pressure", "Apply a tight pressure patch, prescribe oral pain medications, and schedule outpatient ophthalmology follow-up in 1 week", "Place a rigid metal/plastic eye shield, keep NPO, initiate IV broad-spectrum antibiotics, administer IV antiemetics, update tetanus, and schedule urgent surgical repair within 24 hours", "Instill topical corticosteroid and anesthetic drops hourly, and discharge the patient home"]'::jsonb, 3, 'Immediate management of a ruptured globe includes: (1) placing a **rigid eye shield** (e.g. Fox shield) resting on the brow and cheek bones (never place a patch or pad that contacts the eyelids), (2) keeping the patient **strictly NPO** in preparation for urgent surgery, (3) administering **IV broad-spectrum antibiotics** (e.g., cefazolin + levofloxacin) to prevent endophthalmitis, (4) administering **IV antiemetics** (e.g., ondansetron) to prevent vomiting (which raises intraocular pressure), (5) updating **tetanus status**, and (6) securing **urgent surgical closure** in the OR within 24 hours.');

    ---------------------------------------------------------------------------
    -- CASE 07: The Rock-Hard Orbit (V1)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Rock-Hard Orbit (V1)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Rock-Hard Orbit (V1)', 'A 22-year-old female presents to the emergency department immediately after sustaining severe blunt facial trauma from a baseball bat. She reports excruciating pain and rapidly progressive vision loss in the left eye.  She has a history of mild hypertension.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 105 bpm | BP: 142/90 mmHg
*   **Visual Acuity:** OS: 20/400 (no improvement with pinhole); contralateral eye: 20/20
*   **Ocular Examination (OS):** Extreme, tense **proptosis** and massive subconjunctival hemorrhage. The eyelids are extremely swollen, tense, and **rock-hard to palpation**, making it highly difficult to separate them. There is a prominent **relative afferent pupillary defect (RAPD)** in the affected eye. Extraocular movements are completely restricted in all directions (ophthalmoplegia). The intraocular pressure is 51 mmHg.', 7) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 22-year-old female presents to the emergency department immediately after sustaining severe blunt facial trauma from a baseball bat. She reports excruciating pain and rapidly progressive vision loss in the left eye.  She has a history of mild hypertension.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 105 bpm | BP: 142/90 mmHg
*   **Visual Acuity:** OS: 20/400 (no improvement with pinhole); contralateral eye: 20/20
*   **Ocular Examination (OS):** Extreme, tense **proptosis** and massive subconjunctival hemorrhage. The eyelids are extremely swollen, tense, and **rock-hard to palpation**, making it highly difficult to separate them. There is a prominent **relative afferent pupillary defect (RAPD)** in the affected eye. Extraocular movements are completely restricted in all directions (ophthalmoplegia). The intraocular pressure is 51 mmHg.', "order" = 7 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the diagnosis, and what is the most urgent, vision-saving intervention for this patient?', '["Orbital Compartment Syndrome (OCS) due to retrobulbar hemorrhage; immediate bedside lateral canthotomy and cantholysis", "Ruptured globe; immediate surgical exploration in the operating room", "Optic neuritis; initiate high-dose intravenous methylprednisolone within 1 hour", "Blowout fracture; order an urgent facial CT scan and administer oral prednisone", "Carotid-cavernous fistula; urgent carotid artery angiography and embolization"]'::jsonb, 0, 'This patient has **Orbital Compartment Syndrome (OCS)** secondary to a **retrobulbar hemorrhage** (bleeding behind the eye). This is a vision-threatening emergency. The most urgent intervention is **immediate bedside lateral canthotomy and cantholysis (LCC)**. LCC must be performed **immediately at the bedside without waiting for CT scans or ophthalmology arrival**, as irreversible ischemic blindness occurs within 90-120 minutes.'),
    (v_case_id, 'What is the primary pathophysiological mechanism by which OCS leads to rapid, irreversible blindness?', '["The retrobulbar blood directly dissects into the optic nerve sheath and destroys axons", "Chronic bacterial infection spreads from the retrobulbar space to the brain", "The blood in the orbit triggers a rapid, autoimmune destruction of the contralateral retina", "High intraorbital pressure compromises perfusion to the optic nerve and retina, causing central retinal artery occlusion or ischemic optic neuropathy", "The compression forces the crystalline lens backward, crushing the vitreous"]'::jsonb, 3, 'Because the orbit is a closed, rigid bony compartment bounded anteriorly by the stiff orbital septum and eyelids, a **retrobulbar hemorrhage** causes a rapid rise in intraorbital pressure. When the orbital pressure exceeds the perfusion pressure of the microvasculature, it **compromises blood flow to the optic nerve and retina**, resulting in **central retinal artery occlusion (CRAO)** or **anterior/posterior ischemic optic neuropathy**.'),
    (v_case_id, 'How does performing a lateral canthotomy and cantholysis relieve the elevated intraorbital pressure?', '["It paralyzes the extraocular muscles, reducing metabolic demand", "It allows the retrobulbar blood to drain completely out of the lateral wound", "It releases the lateral palpebral ligament, allowing the eyelids and orbital contents to expand forward, rapidly reducing intraorbital pressure", "It allows the surgeon to physically push the globe back into the orbit", "It directly decompresses the maxillary sinus to relieve pressure"]'::jsonb, 2, 'Performing a **lateral canthotomy** (cutting the lateral canthal tendon) and **cantholysis** (specifically cutting the superior and inferior crus of the lateral palpebral ligament) **releases the attachment of the eyelids to the lateral orbital rim**. This allows the **eyelids and globe to expand forward (increasing proptosis)**, which rapidly decompresses the closed orbital compartment, lowering the pressure from dangerous levels (>40-50 mmHg) to safe levels almost instantly.');

    ---------------------------------------------------------------------------
    -- CASE 08: The Numb RAPD (V1)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Numb RAPD (V1)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Numb RAPD (V1)', 'A 38-year-old male is brought to the emergency department after falling off a bicycle and striking the right side of his forehead against the concrete curb. He did not lose consciousness but complains of profound, painless vision loss in his right eye. He has no other injuries.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 76 bpm | BP: 120/80 mmHg
*   **Visual Acuity:** OD: 20/400; contralateral eye: 20/20
*   **Ocular Examination (OD):** Mild bruising over the forehead and brow. The globe is completely intact, eyelids are soft, and anterior chamber is quiet. IOP is 14 mmHg OU. However, there is a **prominent relative afferent pupillary defect (RAPD)** in the affected eye. Dilated fundus examination reveals a **completely normal optic nerve head** with healthy color and sharp margins. Contralateral eye is normal.', 8) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 38-year-old male is brought to the emergency department after falling off a bicycle and striking the right side of his forehead against the concrete curb. He did not lose consciousness but complains of profound, painless vision loss in his right eye. He has no other injuries.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 76 bpm | BP: 120/80 mmHg
*   **Visual Acuity:** OD: 20/400; contralateral eye: 20/20
*   **Ocular Examination (OD):** Mild bruising over the forehead and brow. The globe is completely intact, eyelids are soft, and anterior chamber is quiet. IOP is 14 mmHg OU. However, there is a **prominent relative afferent pupillary defect (RAPD)** in the affected eye. Dilated fundus examination reveals a **completely normal optic nerve head** with healthy color and sharp margins. Contralateral eye is normal.', "order" = 8 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the most likely diagnosis?', '["Malingering or functional vision loss", "Retinal detachment", "Central retinal artery occlusion (CRAO)", "Traumatic Optic Neuropathy (TON)", "Acute optic neuritis"]'::jsonb, 3, 'This patient has **Traumatic Optic Neuropathy (TON)**, which classically presents as **profound vision loss** following blunt head or orbital trauma, accompanied by a **relative afferent pupillary defect (RAPD)**, in the setting of a **completely normal-appearing optic nerve head** acutely. The nerve is damaged retrobulbar (often inside the optic canal).'),
    (v_case_id, 'Why does the optic nerve head appear completely normal during the acute phase of Traumatic Optic Neuropathy?', '["The nerve is temporarily stunned (neuropraxia) and does not undergo physical changes", "The visual loss is purely psychological and there is no real nerve damage", "The injury is retrobulbar (within the optic canal), and retrograde degeneration of the axons takes 4 to 6 weeks to manifest as disc pallor", "The swollen optic nerve is hidden by the vitreous gel", "The contralateral eye is compensating by sending blood flow to the damaged disc"]'::jsonb, 2, 'Acutely, the optic disc appears **completely normal** because the site of injury in TON is typically **retrobulbar** (most commonly within the bony **optic canal**, where the nerve is sheared or compressed by bone fragments or microvascular ischemia). It takes **4 to 6 weeks for retrograde axoplasmic degeneration** to travel from the site of injury back to the optic nerve head, at which point the disc will develop permanent **optic atrophy and pallor**.'),
    (v_case_id, 'Which of the following is the diagnostic test of choice to evaluate a patient with suspected Traumatic Optic Neuropathy?', '["Fluorescein angiography of the retina", "Lumbar puncture to measure cerebrospinal fluid opening pressure", "High-resolution CT scan of the brain and orbits with thin cuts through the optic canal", "Electroretinography (ERG)", "Ocular B-scan ultrasound of the posterior segment"]'::jsonb, 2, 'The diagnostic test of choice is a **high-resolution CT scan of the brain and orbits with thin cuts (1 mm) through the optic canal**. This is essential to evaluate for **optic canal fractures**, bony spicules compressing the nerve, or hematomas within the canal that might warrant surgical decompression.');

    ---------------------------------------------------------------------------
    -- CASE 09: The Torn Tear Duct (V1)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Torn Tear Duct (V1)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Torn Tear Duct (V1)', 'An 5-year-old child is brought to the emergency department by his parents after being scratched in the face by a dog. The child is crying but has no systemic symptoms. The parents note a deep cut in the child''s left lower eyelid.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 85 bpm | BP: 110/70 mmHg
*   **Visual Acuity:** Bilateral 20/20 (corrected)
*   **Ocular Examination:** The left globe is completely intact, with no conjunctival injection, clear cornea, and quiet anterior chamber. However, there is a deep, full-thickness **laceration of the left lower eyelid medial to the punctum**, completely transecting the medial canthal angle and the **lower lacrimal canaliculus**. The laceration extends down to the orbicularis oculi muscle.', 9) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'An 5-year-old child is brought to the emergency department by his parents after being scratched in the face by a dog. The child is crying but has no systemic symptoms. The parents note a deep cut in the child''s left lower eyelid.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 85 bpm | BP: 110/70 mmHg
*   **Visual Acuity:** Bilateral 20/20 (corrected)
*   **Ocular Examination:** The left globe is completely intact, with no conjunctival injection, clear cornea, and quiet anterior chamber. However, there is a deep, full-thickness **laceration of the left lower eyelid medial to the punctum**, completely transecting the medial canthal angle and the **lower lacrimal canaliculus**. The laceration extends down to the orbicularis oculi muscle.', "order" = 9 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the management, and where should this repair ideally be performed?', '["Simple bedside closure of the skin laceration using steri-strips or skin glue", "Applying a tight pressure patch for 2 weeks and letting the tear duct heal spontaneously", "Performing immediate surgical excision of the entire lacrimal gland", "Surgical repair in the operating room under microscopic visualization, involving canalicular stenting (e.g. Crawford or monocanalicular stent) and meticulous suturing", "Prescribing oral antibiotics and sending the child home without closure"]'::jsonb, 3, 'A lid laceration medial to the punctum that **transects the lacrimal canaliculus** requires specialized **surgical repair in the operating room**. Under microscopic magnification, the cut ends of the canaliculus must be identified, **stented with a silicone tube** (e.g., Crawford stent or Monoka) to maintain the patency of the lumen during healing, and the surrounding tissues repaired meticulously. Simple skin suturing is a failure of care.'),
    (v_case_id, 'What is the primary long-term complication if a canalicular laceration is not repaired or is repaired poorly?', '["Severe, progressive orbital blowout fracture and diplopia", "Autoimmune sympathetic ophthalmia in the contralateral eye", "Chronic, intractable dry eye syndrome due to lacrimal hypersecretion", "Permanent loss of central visual acuity and macular edema", "Chronic, debilitating epiphora (overflow of tears) due to disruption of the tear drainage system"]'::jsonb, 4, 'The lower canaliculus carries approximately 70% of the tear drainage from the ocular surface to the lacrimal sac. If the canaliculus is not repaired or heals with scarring/occlusion, the patient will develop **chronic, debilitating epiphora (persistent tearing and overflow of tears)**. This causes significant visual blurring and skin irritation.'),
    (v_case_id, 'Which critical muscle and tendon structures are located in the medial canthus and must be carefully reanchored during repair to prevent eyelid deformity?', '["Corrugator supercilii and frontalis muscle", "Inferior rectus muscle and lockwood''s ligament", "Lateral palpebral ligament and levator palpebrae superioris", "Medial canthal tendon and orbicularis oculi muscle", "Superior oblique muscle and Tenon''s capsule"]'::jsonb, 3, 'The **medial canthal tendon** and the **pars lacrimalis of the orbicularis oculi muscle (Horner''s muscle)** are located medially and are responsible for anchoring the eyelid to the lacrimal bone and driving the ''lacrimal pump'' that sucks tears into the drainage system. Failure to carefully reanchor these structures leads to **ectropion** (eyelid turning outward), medial canthal rounding, and permanent tearing dysfunction.');

    ---------------------------------------------------------------------------
    -- CASE 10: The Hammer and Siderosis (V1)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Hammer and Siderosis (V1)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Hammer and Siderosis (V1)', 'A 46-year-old carpenter presents with mild discomfort and slightly blurry vision in her right eye.  She reports that she was hammering steel-on-steel 2 days ago without safety goggles when she felt a tiny ''tweak'' or splash of water in her eye, but did not think much of it until the vision became slightly fuzzy today.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 72 bpm | BP: 120/80 mmHg
*   **Visual Acuity:** OD: 20/40; contralateral eye: 20/20
*   **Ocular Examination (OD):** A tiny, self-sealing 1-mm corneal wound is visible at the 9 o''clock position. Directly behind it, there is a small **iris transillumination defect (hole)**. The lens reveals a tiny, localized **focal cataract** in the path of the injury. Dilated fundus examination reveals a small, shiny, metallic **foreign body** lodged in the vitreous cavity inferiorly, surrounded by a localized vitreous hemorrhage. No retinal detachment is seen. IOP is 12 mmHg.', 10) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 46-year-old carpenter presents with mild discomfort and slightly blurry vision in her right eye.  She reports that she was hammering steel-on-steel 2 days ago without safety goggles when she felt a tiny ''tweak'' or splash of water in her eye, but did not think much of it until the vision became slightly fuzzy today.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 72 bpm | BP: 120/80 mmHg
*   **Visual Acuity:** OD: 20/40; contralateral eye: 20/20
*   **Ocular Examination (OD):** A tiny, self-sealing 1-mm corneal wound is visible at the 9 o''clock position. Directly behind it, there is a small **iris transillumination defect (hole)**. The lens reveals a tiny, localized **focal cataract** in the path of the injury. Dilated fundus examination reveals a small, shiny, metallic **foreign body** lodged in the vitreous cavity inferiorly, surrounded by a localized vitreous hemorrhage. No retinal detachment is seen. IOP is 12 mmHg.', "order" = 10 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the diagnosis, and what is the definitive management for this patient?', '["Ruptured globe; apply a tight pressure patch and perform daily outpatient visual acuity checks", "Dry AMD; prescribe high-dose AREDS2 vitamins and reassure", "Traumatic uveitis; initiate topical corticosteroid drops and monitor closely as an outpatient", "Penetrating Intraocular Foreign Body (IOFB); urgent surgical pars plana vitrectomy with removal of the foreign body", "Corneal foreign body; perform bedside removal using a sterile needle under topical anesthesia"]'::jsonb, 3, 'This is a **Penetrating Intraocular Foreign Body (IOFB)**. Even if the entry wound is self-sealing and the eye is quiet, a foreign body lodged inside the vitreous cavity is a high risk for endophthalmitis and chronic toxicity. Definitive management is **urgent surgical pars plana vitrectomy (PPV)** to remove the foreign body, repair any retinal tears, and administer intravitreal antibiotics.'),
    (v_case_id, 'Which diagnostic imaging modality is strictly CONTRAINDICATED if a metallic intraocular foreign body is suspected?', '["Fluorescein angiography of the retina", "High-resolution CT scan of the orbits without contrast", "Standard orbital X-ray (Caldwell and Waters views)", "Magnetic Resonance Imaging (MRI) of the brain and orbits", "B-scan ultrasound of the globe"]'::jsonb, 3, 'If a metallic (ferrous) intraocular foreign body is suspected, **MRI is strictly contraindicated**. The powerful magnetic field of the MRI will cause the metallic foreign body to **move, rotate, or migrate** within the eye, leading to catastrophic shearing of the retina, vitreous hemorrhage, or lens rupture. **High-resolution CT scan** is the gold standard imaging modality of choice.'),
    (v_case_id, 'What is the chronic, blinding toxicity condition that occurs if a ferrous (iron-containing) intraocular foreign body is left inside the eye for months or years?', '["Sympathetic ophthalmia, a granulomatous uveitis in the contralateral eye", "Neovascular glaucoma, driven by chronic iris ischemia", "Siderosis bulbi, caused by iron toxicity leading to degeneration of the retina and trabecular meshwork", "Phacolytic glaucoma, caused by lens protein leaking through the capsule", "Chalcosis bulbi, caused by copper deposition in Descemet''s membrane"]'::jsonb, 2, 'If a ferrous (iron) IOFB is left in the eye, the iron slowly oxidizes and dissolves, releasing toxic iron ions that deposit in and destroy intracellular structures. This is known as **Siderosis bulbi**. It leads to **degeneration of the retina** (manifesting as profound night blindness and pigmentary changes), **damage to the trabecular meshwork** (causing secondary open-angle glaucoma), and **cataract formation with iris heterochromia (turning the iris rusty brown)**.');

    ---------------------------------------------------------------------------
    -- CASE 11: The Lime Splattered Eye - Clinical Presentation (V2)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Lime Splattered Eye - Clinical Presentation (V2)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Lime Splattered Eye - Clinical Presentation (V2)', 'A 34-year-old construction worker presents to the emergency department immediately after a bag of wet concrete mix (calcium hydroxide/alkali) burst and splashed into her right eye 30 minutes ago. She reports intense, burning pain, severe tearing, and an inability to open the eye. She rinsed the eye for about 2 minutes at the site before coming in.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 95 bpm | BP: 135/85 mmHg
*   **Visual Acuity:** OD: 20/200; contralateral eye: 20/20
*   **Ocular Examination (OD):** Severe blepharospasm. After instilling topical anesthetic, slit-lamp exam reveals a moderately hazy cornea with a large epithelial defect. There is a prominent area of **limbal blanching and ischemia** (porcelain sclera) involving 180 degrees of the limbus. The conjunctiva is pale and necrotic in the blanched areas. The initial paper pH test of the conjunctival sac shows a pH of 11.0.', 11) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 34-year-old construction worker presents to the emergency department immediately after a bag of wet concrete mix (calcium hydroxide/alkali) burst and splashed into her right eye 30 minutes ago. She reports intense, burning pain, severe tearing, and an inability to open the eye. She rinsed the eye for about 2 minutes at the site before coming in.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 95 bpm | BP: 135/85 mmHg
*   **Visual Acuity:** OD: 20/200; contralateral eye: 20/20
*   **Ocular Examination (OD):** Severe blepharospasm. After instilling topical anesthetic, slit-lamp exam reveals a moderately hazy cornea with a large epithelial defect. There is a prominent area of **limbal blanching and ischemia** (porcelain sclera) involving 180 degrees of the limbus. The conjunctiva is pale and necrotic in the blanched areas. The initial paper pH test of the conjunctival sac shows a pH of 11.0.', "order" = 11 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the most immediate, critical next step in the management of this patient?', '["Perform copious irrigation with sterile saline or water using a Morgan lens until the ocular surface pH is neutralized to 7.0 - 7.2", "Order an urgent CT scan of the brain and orbits to rule out foreign bodies", "Administer systemic high-dose intravenous corticosteroids immediately", "Prepare the patient for urgent surgical corneal transplant (penetrating keratoplasty)", "Instill topical broad-spectrum antibiotic drops and apply a tight pressure patch"]'::jsonb, 0, 'An ocular chemical burn is a true emergency. The **most critical immediate step is copious irrigation** with sterile saline, balanced salt solution, or tap water (often using a Morgan lens) to flush the chemical. Irrigation must be continued continuously until the ocular surface pH is **fully neutralized (pH 7.0 - 7.2)**, measured 5-10 minutes after stopping irrigation. No other diagnostic test or treatment should delay this.'),
    (v_case_id, 'Why are alkali burns generally considered far more destructive and dangerous to the eye than acid burns?', '["Alkalies induce a rapid, autoimmune destruction of the contralateral eye", "Alkalies trigger immediate, severe bacterial keratitis within minutes of contact", "Alkalies cause saponification of cell membrane lipids and rapidly penetrate deep into the cornea and anterior chamber", "Alkalies selectively crystallize within the lens, causing immediate explosive cataract", "Alkalies directly coagulate corneal proteins, forming a barrier that limits deep tissue penetration"]'::jsonb, 2, '**Alkali substances** (like ammonia, lye, and lime/wet concrete) are highly lipophilic and cause **saponification of cell membrane lipids**. This allows them to **rapidly penetrate** through the corneal epithelium, stroma, and into the anterior chamber within minutes, causing extensive internal damage. In contrast, **acids** cause **coagulation of corneal proteins**, which forms a physical barrier that limits further deep penetration of the acid.'),
    (v_case_id, 'What is the clinical significance of ''limbal blanching and ischemia'' in a chemical burn?', '["It indicates that the intraocular pressure has dropped to 0 mmHg", "It indicates destruction of the limbal stem cells, which are essential for regenerating the corneal epithelium, signifying a poor prognosis", "It is a benign finding that represents temporary vasospasm and resolves spontaneously within 24 hours", "It signifies that a metallic foreign body is embedded in the sclera", "It represents a localized type I hypersensitivity reaction to concrete proteins"]'::jsonb, 1, '**Limbal blanching and ischemia** (appearing as a white, bloodless ''porcelain'' ring at the cornea-sclera junction) is a severe prognostic sign. The limbus houses the **limbal epithelial stem cells**, which are responsible for the continuous regeneration and maintenance of the corneal epithelium. Destruction of these stem cells leads to chronic epithelial defects, corneal scarring, visual degradation, and conjunctivalization.');

    ---------------------------------------------------------------------------
    -- CASE 12: The Fingernail Scratch - Clinical Presentation (V2)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Fingernail Scratch - Clinical Presentation (V2)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Fingernail Scratch - Clinical Presentation (V2)', 'A 37-year-old female presents to the clinic with intense pain, a severe foreign body sensation, constant tearing, and photophobia in her right eye. She reports that her 8-month-old infant accidentally scratched her eye with a fingernail while playing this morning.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 83 bpm | BP: 134/76 mmHg
*   **Visual Acuity:** OD: 20/30 (improved with pinhole); contralateral eye: 20/20
*   **Ocular Examination (OD):** Marked conjunctival injection. Instillation of fluorescein dye and examination under cobalt blue light reveals a sharply demarcated, linear, bright green glowing area of epithelial loss measuring 3 mm x 2 mm in the central cornea. There is no white corneal infiltrate, no corneal thinning, and the anterior chamber is quiet. Pupil is reactive and normal.', 12) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 37-year-old female presents to the clinic with intense pain, a severe foreign body sensation, constant tearing, and photophobia in her right eye. She reports that her 8-month-old infant accidentally scratched her eye with a fingernail while playing this morning.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 83 bpm | BP: 134/76 mmHg
*   **Visual Acuity:** OD: 20/30 (improved with pinhole); contralateral eye: 20/20
*   **Ocular Examination (OD):** Marked conjunctival injection. Instillation of fluorescein dye and examination under cobalt blue light reveals a sharply demarcated, linear, bright green glowing area of epithelial loss measuring 3 mm x 2 mm in the central cornea. There is no white corneal infiltrate, no corneal thinning, and the anterior chamber is quiet. Pupil is reactive and normal.', "order" = 12 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the most likely diagnosis, and what is the first-line pharmacotherapy?', '["Herpes simplex dendritic keratitis; topical acyclovir gel and oral valacyclovir", "Corneal abrasion; topical broad-spectrum antibiotic drops or ointment (e.g. erythromycin or polymyxin/trimethoprim)", "Corneal ulcer; immediate outpatient surgical superficial keratectomy", "Infectious bacterial keratitis; topical fortified vancomycin and tobramycin every 30 minutes", "Dry eye syndrome; lifetime preservative-free artificial tears only"]'::jsonb, 1, 'This is a simple **corneal abrasion** (epithelial defect without underlying stromal infection). First-line therapy consists of **topical broad-spectrum antibiotic drops or ointment** to prevent secondary bacterial infection while the epithelium heals, along with oral analgesics for pain control. Ointment (e.g., erythromycin) provides lubrication and comfort.'),
    (v_case_id, 'Why is the prescription of topical anesthetic drops (e.g. proparacaine) for home pain control strictly CONTRAINDICATED in patients with corneal abrasions?', '["Topical anesthetics cause systemic cardiovascular toxicity and bradycardia through lacrimal absorption", "Topical anesthetics neutralize the efficacy of topical antibiotics", "Topical anesthetics cause permanent pupillary dilation and acute angle closure", "Topical anesthetics are directly toxic to the corneal epithelium, inhibit healing, and block the protective blink reflex, leading to severe corneal melting", "Topical anesthetics promote the rapid growth of fungal spores in the stroma"]'::jsonb, 3, 'Prescribing **topical anesthetics (like proparacaine or tetracaine) for home use is strictly contraindicated**. These drugs are **highly toxic to the corneal epithelium** (epitheliotoxic), severely retard epithelial migration and wound healing, and **abolish the protective corneal blink reflex**. Abuse of these drops leads to progressive, painless **corneal stromal melting, ulceration, and permanent scarring**.'),
    (v_case_id, 'What is the most common long-term complication of a corneal abrasion caused by organic trauma (e.g., a fingernail or tree branch)?', '["Secondary open-angle pigmentary glaucoma", "Recurrent corneal erosion syndrome, due to poor basement membrane adhesion", "Autoimmune uveitis associated with HLA-B27", "Late-onset ectopia lentis and lens subluxation", "Sympathetic ophthalmia in the contralateral eye"]'::jsonb, 1, 'A classic complication of organic abrasions (fingernails, paper cuts, tree branches) is **Recurrent Corneal Erosion (RCE) syndrome**. The regenerated corneal epithelial cells fail to form proper hemidesmosomes and adhere securely to the underlying **Bowman''s membrane and basement membrane**. Weeks or months later, typically upon opening the eyes in the morning, the dry eyelid adheres to the loose epithelium and rips it off, causing a recurrence of severe pain and abrasion.');

    ---------------------------------------------------------------------------
    -- CASE 13: The Machinist's Rust - Clinical Presentation (V2)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Machinist''s Rust - Clinical Presentation (V2)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Machinist''s Rust - Clinical Presentation (V2)', 'A 41-year-old machinist presents with a 24-hour history of redness, gritty pain, and tearing in her right eye.  She reports that she was grinding steel yesterday afternoon without safety goggles and felt something fly into  her eye.

**Physical Examination:**
*   **Vitals:** Temp: 98.4°F | HR: 74 bpm | BP: 122/76 mmHg
*   **Visual Acuity:** OD: 20/30; contralateral eye: 20/20
*   **Ocular Examination (OD):** Slit-lamp biomicroscopy reveals a tiny, dark, metallic foreign body embedded in the superficial corneal stroma at the 4 o''clock position, outside of the visual axis. The foreign body is surrounded by a distinct, circular, orange-brown halo of **rust ring** diffusing into the stroma. The anterior chamber is deep and quiet (0 cells). No Seidel sign is present.', 13) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 41-year-old machinist presents with a 24-hour history of redness, gritty pain, and tearing in her right eye.  She reports that she was grinding steel yesterday afternoon without safety goggles and felt something fly into  her eye.

**Physical Examination:**
*   **Vitals:** Temp: 98.4°F | HR: 74 bpm | BP: 122/76 mmHg
*   **Visual Acuity:** OD: 20/30; contralateral eye: 20/20
*   **Ocular Examination (OD):** Slit-lamp biomicroscopy reveals a tiny, dark, metallic foreign body embedded in the superficial corneal stroma at the 4 o''clock position, outside of the visual axis. The foreign body is surrounded by a distinct, circular, orange-brown halo of **rust ring** diffusing into the stroma. The anterior chamber is deep and quiet (0 cells). No Seidel sign is present.', "order" = 13 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the correct management of this patient''s corneal foreign body and associated rust ring?', '["Apply a pressure patch for 1 week and wait for the rust ring to dissolve systemically", "Initiate topical corticosteroid drops hourly to dissolve the iron deposits", "Flush the eye with systemic chelating agents (EDTA) for 12 hours", "Remove the metallic foreign body immediately, and remove the rust ring either today or within 24-48 hours using a sterile needle, spud, or rotating ophthalmic burr under slit-lamp visualization", "Refer the patient for urgent surgical lamellar keratoplasty in the operating room"]'::jsonb, 3, 'Management requires **removal of both the foreign body and the rust ring**. The metallic foreign body is removed immediately using a sterile needle or spud under slit-lamp magnification. The **rust ring** (oxidized iron that diffuses into the stroma) is toxic and retards healing; it must be removed either at the same time or within 24-48 hours (when it softens) using a **rotating ophthalmic burr (Algerbrush)** or needle.'),
    (v_case_id, 'Within what timeframe does a metallic iron-containing corneal foreign body begin to form a visible rust ring in the stroma?', '["Iron foreign bodies never form rust rings in the eye", "Within 8 to 24 hours of injury", "Immediately upon impact (within seconds)", "Only after 1 to 2 weeks of neglect", "Exactly 30 days post-injury"]'::jsonb, 1, 'A metallic, iron-containing foreign body oxidizes rapidly when exposed to the moist environment of the tear film and corneal stroma. A **visible orange-brown rust ring** of iron deposition begins to form in the surrounding stroma **within 8 to 24 hours** of the injury. Early removal of the foreign body prevents extensive rust ring formation.'),
    (v_case_id, 'Following the removal of a corneal foreign body, which of the following is essential to prevent secondary complications?', '["Implantation of a soft contact lens directly over the rust ring", "Oral acyclovir to prevent viral activation", "Topical broad-spectrum antibiotics, checking tetanus vaccination status, and avoiding patching if the wound is dirty", "Topical corticosteroid drops every hour for 2 weeks to prevent scarring", "Dilating the pupil with atropine for 6 months to maintain muscle rest"]'::jsonb, 2, 'Following foreign body and rust removal, the patient has a corneal epithelial defect (abrasion). Essential care includes **topical broad-spectrum antibiotics** (drops/ointment) to prevent bacterial keratitis, and **updating their tetanus vaccination status** (as corneal wounds can rarely harbor tetanus). The eye is typically **not patched** if there is any suspicion of organic contamination or Pseudomonas risk (e.g. contact lens wearers).');

    ---------------------------------------------------------------------------
    -- CASE 14: The Squash Ball Collision - Clinical Presentation (V2)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Squash Ball Collision - Clinical Presentation (V2)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Squash Ball Collision - Clinical Presentation (V2)', 'A 11-year-old African American female presents to the emergency department after being struck directly in the right eye by a squash ball during a game. She reports sudden, severe pain and a dramatic decrease in vision. She denies any prior eye problems but notes she has sickle cell trait.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 88 bpm | BP: 122/78 mmHg
*   **Visual Acuity:** OD: 20/100; contralateral eye: 20/20
*   **Ocular Examination (OD):** Periorbital ecchymosis. Slit-lamp biomicroscopy reveals a prominent, layered column of red blood cells filling the inferior 30% of the anterior chamber (Grade II hyphema). The pupil is sluggish. The ciliary body is intact, and there is no open globe injury. The intraocular pressure is 24 mmHg (significantly elevated).', 14) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 11-year-old African American female presents to the emergency department after being struck directly in the right eye by a squash ball during a game. She reports sudden, severe pain and a dramatic decrease in vision. She denies any prior eye problems but notes she has sickle cell trait.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 88 bpm | BP: 122/78 mmHg
*   **Visual Acuity:** OD: 20/100; contralateral eye: 20/20
*   **Ocular Examination (OD):** Periorbital ecchymosis. Slit-lamp biomicroscopy reveals a prominent, layered column of red blood cells filling the inferior 30% of the anterior chamber (Grade II hyphema). The pupil is sluggish. The ciliary body is intact, and there is no open globe injury. The intraocular pressure is 24 mmHg (significantly elevated).', "order" = 14 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the primary underlying anatomical source of blood in a traumatic hyphema?', '["Rupture of the blood vessels of the ciliary body face or iris root due to blunt contusion forces", "Rupture of ciliary body processes due to systemic hypertension", "Rupture of Schlemm''s canal with retrograde venous flow into the chamber", "Bleeding from the retinal arterioles that dissects forward through the vitreous", "Exudative hemorrhage from damaged corneal endothelial cells"]'::jsonb, 0, 'A traumatic hyphema (blood in the anterior chamber) is caused by blunt contusion forces that compress the globe along its axial diameter and expand it equatorially. This sudden stretching force tears the anterior segment tissues, resulting in the **rupture of blood vessels of the ciliary body face, iris root, or major arterial circle of the iris**.'),
    (v_case_id, 'Why is a traumatic hyphema particularly dangerous in patients with sickle cell trait or disease, and what is the target IOP management?', '["Sickle cell patients are completely immune to elevated IOP, so no treatment is required", "Sickled erythrocytes are rigid and clog the trabecular meshwork, causing rapid, severe IOP elevation; even mild IOP elevation (>24 mmHg) can cause optic nerve ischemia, requiring aggressive control and avoiding systemic acetazolamide", "The blood in the anterior chamber reacts with sickle hemoglobin to cause irreversible iris necrosis within 2 hours", "Sickle cell trait prevents the blood from clotting, causing continuous, unstoppable bleeding that fills the entire eye", "Sickle cell patients have fragile corneas that melt rapidly when exposed to red blood cells in the anterior chamber"]'::jsonb, 1, 'Hyphema in a **sickle cell** patient is a high-risk situation. In the hypoxic, hyperosmolar anterior chamber, red blood cells sickling occurs. The rigid **sickled erythrocytes clog the trabecular meshwork**, causing rapid, severe IOP spikes. Furthermore, the compromised microcirculation of the optic nerve head in sickle cell patients makes them highly vulnerable to ischemic damage, so **even mild IOP elevations (>24 mmHg for >24 hours) can cause permanent optic nerve atrophy or central retinal artery occlusion**. Systemic **acetazolamide is strictly contraindicated** as it promotes sickling.'),
    (v_case_id, 'What represents the core conservative management recommendations for a patient with an uncomplicated traumatic hyphema?', '["Immediate outpatient surgical anterior chamber washout and trabeculectomy", "Initiation of systemic anticoagulation (warfarin) and vigorous physical exercise to clear the blood", "Strict flat bed rest, a pressure patch, daily aspirin to prevent clotting, and hourly topical corticosteroids", "Applying a tight pressure patch and scheduling follow-up in 1 month", "Bed rest with head of bed elevated 30-45 degrees, a rigid eye shield, topical cycloplegic drops, and avoiding aspirin/NSAIDs"]'::jsonb, 4, 'Conservative management for hyphema includes: (1) **bed rest with the head of the bed elevated 30 to 45 degrees** (allows blood to settle inferiorly, clearing the visual axis and preventing trabecular clogging), (2) a **rigid metal or plastic eye shield** to prevent accidental touch, (3) **topical cycloplegic drops** (e.g. atropine/cyclopentolate) for pupillary rest and pain control, and (4) **avoiding aspirin/NSAIDs** (which increase the risk of re-bleeding, typically occurring on days 3-5).');

    ---------------------------------------------------------------------------
    -- CASE 15: The Fist and Floor - Clinical Presentation (V2)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Fist and Floor - Clinical Presentation (V2)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Fist and Floor - Clinical Presentation (V2)', 'A 32-year-old female presents to the emergency department after being punched in the left eye during a street fight. She complains of pain, severe swelling, bruising, and double vision (diplopia), especially when looking up.  She also notes that her left cheek and upper lip feel numb.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 82 bpm | BP: 120/80 mmHg
*   **Ocular Examination (OS):** Marked periorbital ecchymosis and edema. Subconjunctival hemorrhage is present. There is **vertical diplopia on upgaze**, and testing of extraocular motility reveals a severe **restriction of elevation** in the affected eye. Sensation to light touch is significantly decreased over the ipsilateral cheek, side of the nose, and upper lip. CT scan of the orbits reveals a fracture of the **orbital floor** with herniation of orbital fat and entrapment of the **inferior rectus muscle**.', 15) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 32-year-old female presents to the emergency department after being punched in the left eye during a street fight. She complains of pain, severe swelling, bruising, and double vision (diplopia), especially when looking up.  She also notes that her left cheek and upper lip feel numb.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 82 bpm | BP: 120/80 mmHg
*   **Ocular Examination (OS):** Marked periorbital ecchymosis and edema. Subconjunctival hemorrhage is present. There is **vertical diplopia on upgaze**, and testing of extraocular motility reveals a severe **restriction of elevation** in the affected eye. Sensation to light touch is significantly decreased over the ipsilateral cheek, side of the nose, and upper lip. CT scan of the orbits reveals a fracture of the **orbital floor** with herniation of orbital fat and entrapment of the **inferior rectus muscle**.', "order" = 15 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the diagnosis, and which extraocular muscle is classically entrapped in this condition?', '["Superior orbital fissure syndrome; entrapment of all extraocular muscles", "Medial orbital wall blowout fracture; entrapment of the medial rectus muscle", "Orbital floor blowout fracture; entrapment of the inferior rectus muscle", "Orbital roof blowout fracture; entrapment of the superior rectus muscle", "Lateral orbital wall fracture; entrapment of the lateral rectus muscle"]'::jsonb, 2, 'This patient has an **orbital floor blowout fracture** (the most common type). The classic presentation is **vertical diplopia on upgaze** and **restriction of eye elevation** due to the mechanical **entrapment of the inferior rectus muscle** (and/or surrounding orbital fat/fascia) within the fractured bony fragments of the maxillary bone.'),
    (v_case_id, 'Which cranial nerve is injured, resulting in the numbness of the cheek, side of the nose, and upper lip?', '["Infraorbital nerve, a branch of the maxillary division of the trigeminal nerve (CN V2)", "Facial nerve (CN VII), buccal branch", "Abducens nerve (CN VI)", "Oculomotor nerve (CN III), inferior division", "Supraorbital nerve, a branch of the ophthalmic division of the trigeminal nerve (CN V1)"]'::jsonb, 0, 'The **infraorbital nerve** (a terminal branch of the **maxillary division of the trigeminal nerve, CN V2**) travels along the infraorbital groove and canal in the orbital floor. Fractures of the orbital floor frequently bruise, compress, or lacerate this nerve, resulting in **hypoesthesia/numbness of the ipsilateral cheek, lateral nose, upper lip, and anterior maxillary gingiva**.'),
    (v_case_id, 'Which of the following is a critical instruction that must be given to patients diagnosed with an acute orbital blowout fracture?', '["Perform heavy weightlifting to reduce intraorbital venous pressure", "Strictly avoid blowing their nose to prevent orbital emphysema and potential optic nerve compression", "Apply a high-pressure patch over the eye for 72 hours", "Vigorously blow their nose to clear any blood or fluid from the maxillary sinus", "Avoid sleeping with their head elevated"]'::jsonb, 1, 'Patients with acute orbital fractures must be **strictly instructed not to blow their nose**. Blowing the nose creates high pressure in the paranasal sinuses (maxillary/ethmoid). This pressure forces air and sinus bacteria through the fracture line into the orbit, causing **orbital emphysema** (which can compress the optic nerve and cause blindness) and increasing the risk of **orbital cellulitis**.');

    ---------------------------------------------------------------------------
    -- CASE 16: The Flying Metal Shard - Clinical Presentation (V2)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Flying Metal Shard - Clinical Presentation (V2)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Flying Metal Shard - Clinical Presentation (V2)', 'A 46-year-old construction worker is brought to the emergency department after a metal shard flew off a hammering tool and struck her right eye. He was not wearing safety goggles. He complains of sudden, severe pain and instant, profound loss of vision in that eye. He reports a watery discharge flowing from the eye immediately after the impact.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 90 bpm | BP: 130/80 mmHg
*   **Visual Acuity:** OD: Hand Motion (light projection intact); contralateral eye: 20/20
*   **Ocular Examination (OD):** Diffuse subconjunctival hemorrhage. The anterior chamber is shallow and filled with RBCs (microhyphema). The pupil is peaked and **teardrop-shaped**, pointing towards a 3-mm laceration at the limbus. A small amount of dark, uveal tissue (iris) is prolapsing through the wound. Examination of the wound under cobalt blue light reveals a **positive Seidel sign** (a clear stream of aqueous humor diluting and washing away fluorescein dye).', 16) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 46-year-old construction worker is brought to the emergency department after a metal shard flew off a hammering tool and struck her right eye. He was not wearing safety goggles. He complains of sudden, severe pain and instant, profound loss of vision in that eye. He reports a watery discharge flowing from the eye immediately after the impact.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 90 bpm | BP: 130/80 mmHg
*   **Visual Acuity:** OD: Hand Motion (light projection intact); contralateral eye: 20/20
*   **Ocular Examination (OD):** Diffuse subconjunctival hemorrhage. The anterior chamber is shallow and filled with RBCs (microhyphema). The pupil is peaked and **teardrop-shaped**, pointing towards a 3-mm laceration at the limbus. A small amount of dark, uveal tissue (iris) is prolapsing through the wound. Examination of the wound under cobalt blue light reveals a **positive Seidel sign** (a clear stream of aqueous humor diluting and washing away fluorescein dye).', "order" = 16 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the diagnosis, and what is the significance of the teardrop pupil and positive Seidel test?', '["Traumatic uveitis; teardrop pupil represents severe ciliary spasm, Seidel test is positive due to high protein exudation", "Orbital compartment syndrome; teardrop pupil indicates optic nerve compression, Seidel test is negative", "Ruptured globe / open globe injury; teardrop pupil points to the site of wound, positive Seidel test indicates active aqueous leakage from a full-thickness laceration", "Severe corneal abrasion; teardrop pupil is a normal physiological variant, Seidel test is positive in any tear film excess", "Traumatic hyphema; teardrop pupil is due to iris sphincter rupture, Seidel test indicates red blood cells clogging the cornea"]'::jsonb, 2, 'This is a **ruptured globe (open globe injury)**, a surgical emergency. The **teardrop pupil** is highly characteristic, as intraocular pressure forces the iris to prolapse towards the escape wound, pointing like an arrow to the laceration. The **positive Seidel test** (aqueous fluid stream washing away fluorescein dye under cobalt blue light) confirms a **full-thickness wound** with active external leakage of aqueous humor.'),
    (v_case_id, 'Which of the following is strictly CONTRAINDICATED during the emergency department evaluation of a suspected ruptured globe?', '["Ordering a high-resolution CT scan of the orbits without contrast", "Performing applanation tonometry (IOP measurement) or applying any pressure to the globe", "Keeping the patient strictly NPO (nothing by mouth) for surgery", "Administering systemic intravenous antibiotics and antiemetics", "Placing a rigid, non-contact eye shield resting on the orbital bones"]'::jsonb, 1, 'In a suspected ruptured globe, **any manipulation or pressure on the eye is strictly contraindicated**. This includes performing **tonometry (IOP measurement)**, opening the eyelids forcibly, or performing a dilated fundus exam. Any external pressure can cause **extrusion of the intraocular contents** (iris, lens, vitreous, retina) through the wound, resulting in irreversible blindness.'),
    (v_case_id, 'What are the immediate, first-line management steps for a patient with a confirmed ruptured globe in the emergency department?', '["Perform immediate anterior chamber paracentesis to lower the intraocular pressure", "Apply a tight pressure patch, prescribe oral pain medications, and schedule outpatient ophthalmology follow-up in 1 week", "Perform immediate bedside surgical suturing of the cornea under topical anesthesia", "Instill topical corticosteroid and anesthetic drops hourly, and discharge the patient home", "Place a rigid metal/plastic eye shield, keep NPO, initiate IV broad-spectrum antibiotics, administer IV antiemetics, update tetanus, and schedule urgent surgical repair within 24 hours"]'::jsonb, 4, 'Immediate management of a ruptured globe includes: (1) placing a **rigid eye shield** (e.g. Fox shield) resting on the brow and cheek bones (never place a patch or pad that contacts the eyelids), (2) keeping the patient **strictly NPO** in preparation for urgent surgery, (3) administering **IV broad-spectrum antibiotics** (e.g., cefazolin + levofloxacin) to prevent endophthalmitis, (4) administering **IV antiemetics** (e.g., ondansetron) to prevent vomiting (which raises intraocular pressure), (5) updating **tetanus status**, and (6) securing **urgent surgical closure** in the OR within 24 hours.');

    ---------------------------------------------------------------------------
    -- CASE 17: The Rock-Hard Orbit - Clinical Presentation (V2)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Rock-Hard Orbit - Clinical Presentation (V2)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Rock-Hard Orbit - Clinical Presentation (V2)', 'A 49-year-old female presents to the emergency department immediately after sustaining severe blunt facial trauma from a baseball bat. She reports excruciating pain and rapidly progressive vision loss in the right eye.  She has a history of mild hypertension.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 105 bpm | BP: 142/90 mmHg
*   **Visual Acuity:** OD: 20/400 (no improvement with pinhole); contralateral eye: 20/20
*   **Ocular Examination (OD):** Extreme, tense **proptosis** and massive subconjunctival hemorrhage. The eyelids are extremely swollen, tense, and **rock-hard to palpation**, making it highly difficult to separate them. There is a prominent **relative afferent pupillary defect (RAPD)** in the affected eye. Extraocular movements are completely restricted in all directions (ophthalmoplegia). The intraocular pressure is 50 mmHg.', 17) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 49-year-old female presents to the emergency department immediately after sustaining severe blunt facial trauma from a baseball bat. She reports excruciating pain and rapidly progressive vision loss in the right eye.  She has a history of mild hypertension.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 105 bpm | BP: 142/90 mmHg
*   **Visual Acuity:** OD: 20/400 (no improvement with pinhole); contralateral eye: 20/20
*   **Ocular Examination (OD):** Extreme, tense **proptosis** and massive subconjunctival hemorrhage. The eyelids are extremely swollen, tense, and **rock-hard to palpation**, making it highly difficult to separate them. There is a prominent **relative afferent pupillary defect (RAPD)** in the affected eye. Extraocular movements are completely restricted in all directions (ophthalmoplegia). The intraocular pressure is 50 mmHg.', "order" = 17 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the diagnosis, and what is the most urgent, vision-saving intervention for this patient?', '["Blowout fracture; order an urgent facial CT scan and administer oral prednisone", "Orbital Compartment Syndrome (OCS) due to retrobulbar hemorrhage; immediate bedside lateral canthotomy and cantholysis", "Ruptured globe; immediate surgical exploration in the operating room", "Optic neuritis; initiate high-dose intravenous methylprednisolone within 1 hour", "Carotid-cavernous fistula; urgent carotid artery angiography and embolization"]'::jsonb, 1, 'This patient has **Orbital Compartment Syndrome (OCS)** secondary to a **retrobulbar hemorrhage** (bleeding behind the eye). This is a vision-threatening emergency. The most urgent intervention is **immediate bedside lateral canthotomy and cantholysis (LCC)**. LCC must be performed **immediately at the bedside without waiting for CT scans or ophthalmology arrival**, as irreversible ischemic blindness occurs within 90-120 minutes.'),
    (v_case_id, 'What is the primary pathophysiological mechanism by which OCS leads to rapid, irreversible blindness?', '["The retrobulbar blood directly dissects into the optic nerve sheath and destroys axons", "Chronic bacterial infection spreads from the retrobulbar space to the brain", "The compression forces the crystalline lens backward, crushing the vitreous", "The blood in the orbit triggers a rapid, autoimmune destruction of the contralateral retina", "High intraorbital pressure compromises perfusion to the optic nerve and retina, causing central retinal artery occlusion or ischemic optic neuropathy"]'::jsonb, 4, 'Because the orbit is a closed, rigid bony compartment bounded anteriorly by the stiff orbital septum and eyelids, a **retrobulbar hemorrhage** causes a rapid rise in intraorbital pressure. When the orbital pressure exceeds the perfusion pressure of the microvasculature, it **compromises blood flow to the optic nerve and retina**, resulting in **central retinal artery occlusion (CRAO)** or **anterior/posterior ischemic optic neuropathy**.'),
    (v_case_id, 'How does performing a lateral canthotomy and cantholysis relieve the elevated intraorbital pressure?', '["It allows the retrobulbar blood to drain completely out of the lateral wound", "It paralyzes the extraocular muscles, reducing metabolic demand", "It releases the lateral palpebral ligament, allowing the eyelids and orbital contents to expand forward, rapidly reducing intraorbital pressure", "It directly decompresses the maxillary sinus to relieve pressure", "It allows the surgeon to physically push the globe back into the orbit"]'::jsonb, 2, 'Performing a **lateral canthotomy** (cutting the lateral canthal tendon) and **cantholysis** (specifically cutting the superior and inferior crus of the lateral palpebral ligament) **releases the attachment of the eyelids to the lateral orbital rim**. This allows the **eyelids and globe to expand forward (increasing proptosis)**, which rapidly decompresses the closed orbital compartment, lowering the pressure from dangerous levels (>40-50 mmHg) to safe levels almost instantly.');

    ---------------------------------------------------------------------------
    -- CASE 18: The Numb RAPD - Clinical Presentation (V2)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Numb RAPD - Clinical Presentation (V2)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Numb RAPD - Clinical Presentation (V2)', 'A 29-year-old male is brought to the emergency department after falling off a bicycle and striking the left side of his forehead against the concrete curb. He did not lose consciousness but complains of profound, painless vision loss in his left eye. He has no other injuries.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 76 bpm | BP: 120/80 mmHg
*   **Visual Acuity:** OS: 20/400; contralateral eye: 20/20
*   **Ocular Examination (OS):** Mild bruising over the forehead and brow. The globe is completely intact, eyelids are soft, and anterior chamber is quiet. IOP is 14 mmHg OU. However, there is a **prominent relative afferent pupillary defect (RAPD)** in the affected eye. Dilated fundus examination reveals a **completely normal optic nerve head** with healthy color and sharp margins. Contralateral eye is normal.', 18) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 29-year-old male is brought to the emergency department after falling off a bicycle and striking the left side of his forehead against the concrete curb. He did not lose consciousness but complains of profound, painless vision loss in his left eye. He has no other injuries.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 76 bpm | BP: 120/80 mmHg
*   **Visual Acuity:** OS: 20/400; contralateral eye: 20/20
*   **Ocular Examination (OS):** Mild bruising over the forehead and brow. The globe is completely intact, eyelids are soft, and anterior chamber is quiet. IOP is 14 mmHg OU. However, there is a **prominent relative afferent pupillary defect (RAPD)** in the affected eye. Dilated fundus examination reveals a **completely normal optic nerve head** with healthy color and sharp margins. Contralateral eye is normal.', "order" = 18 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the most likely diagnosis?', '["Retinal detachment", "Traumatic Optic Neuropathy (TON)", "Central retinal artery occlusion (CRAO)", "Acute optic neuritis", "Malingering or functional vision loss"]'::jsonb, 1, 'This patient has **Traumatic Optic Neuropathy (TON)**, which classically presents as **profound vision loss** following blunt head or orbital trauma, accompanied by a **relative afferent pupillary defect (RAPD)**, in the setting of a **completely normal-appearing optic nerve head** acutely. The nerve is damaged retrobulbar (often inside the optic canal).'),
    (v_case_id, 'Why does the optic nerve head appear completely normal during the acute phase of Traumatic Optic Neuropathy?', '["The injury is retrobulbar (within the optic canal), and retrograde degeneration of the axons takes 4 to 6 weeks to manifest as disc pallor", "The contralateral eye is compensating by sending blood flow to the damaged disc", "The visual loss is purely psychological and there is no real nerve damage", "The swollen optic nerve is hidden by the vitreous gel", "The nerve is temporarily stunned (neuropraxia) and does not undergo physical changes"]'::jsonb, 0, 'Acutely, the optic disc appears **completely normal** because the site of injury in TON is typically **retrobulbar** (most commonly within the bony **optic canal**, where the nerve is sheared or compressed by bone fragments or microvascular ischemia). It takes **4 to 6 weeks for retrograde axoplasmic degeneration** to travel from the site of injury back to the optic nerve head, at which point the disc will develop permanent **optic atrophy and pallor**.'),
    (v_case_id, 'Which of the following is the diagnostic test of choice to evaluate a patient with suspected Traumatic Optic Neuropathy?', '["Electroretinography (ERG)", "Fluorescein angiography of the retina", "Ocular B-scan ultrasound of the posterior segment", "High-resolution CT scan of the brain and orbits with thin cuts through the optic canal", "Lumbar puncture to measure cerebrospinal fluid opening pressure"]'::jsonb, 3, 'The diagnostic test of choice is a **high-resolution CT scan of the brain and orbits with thin cuts (1 mm) through the optic canal**. This is essential to evaluate for **optic canal fractures**, bony spicules compressing the nerve, or hematomas within the canal that might warrant surgical decompression.');

    ---------------------------------------------------------------------------
    -- CASE 19: The Torn Tear Duct - Clinical Presentation (V2)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Torn Tear Duct - Clinical Presentation (V2)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Torn Tear Duct - Clinical Presentation (V2)', 'An 12-year-old child is brought to the emergency department by his parents after being scratched in the face by a dog. The child is crying but has no systemic symptoms. The parents note a deep cut in the child''s left lower eyelid.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 85 bpm | BP: 110/70 mmHg
*   **Visual Acuity:** Bilateral 20/20 (corrected)
*   **Ocular Examination:** The left globe is completely intact, with no conjunctival injection, clear cornea, and quiet anterior chamber. However, there is a deep, full-thickness **laceration of the left lower eyelid medial to the punctum**, completely transecting the medial canthal angle and the **lower lacrimal canaliculus**. The laceration extends down to the orbicularis oculi muscle.', 19) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'An 12-year-old child is brought to the emergency department by his parents after being scratched in the face by a dog. The child is crying but has no systemic symptoms. The parents note a deep cut in the child''s left lower eyelid.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 85 bpm | BP: 110/70 mmHg
*   **Visual Acuity:** Bilateral 20/20 (corrected)
*   **Ocular Examination:** The left globe is completely intact, with no conjunctival injection, clear cornea, and quiet anterior chamber. However, there is a deep, full-thickness **laceration of the left lower eyelid medial to the punctum**, completely transecting the medial canthal angle and the **lower lacrimal canaliculus**. The laceration extends down to the orbicularis oculi muscle.', "order" = 19 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the management, and where should this repair ideally be performed?', '["Simple bedside closure of the skin laceration using steri-strips or skin glue", "Prescribing oral antibiotics and sending the child home without closure", "Performing immediate surgical excision of the entire lacrimal gland", "Surgical repair in the operating room under microscopic visualization, involving canalicular stenting (e.g. Crawford or monocanalicular stent) and meticulous suturing", "Applying a tight pressure patch for 2 weeks and letting the tear duct heal spontaneously"]'::jsonb, 3, 'A lid laceration medial to the punctum that **transects the lacrimal canaliculus** requires specialized **surgical repair in the operating room**. Under microscopic magnification, the cut ends of the canaliculus must be identified, **stented with a silicone tube** (e.g., Crawford stent or Monoka) to maintain the patency of the lumen during healing, and the surrounding tissues repaired meticulously. Simple skin suturing is a failure of care.'),
    (v_case_id, 'What is the primary long-term complication if a canalicular laceration is not repaired or is repaired poorly?', '["Permanent loss of central visual acuity and macular edema", "Severe, progressive orbital blowout fracture and diplopia", "Autoimmune sympathetic ophthalmia in the contralateral eye", "Chronic, debilitating epiphora (overflow of tears) due to disruption of the tear drainage system", "Chronic, intractable dry eye syndrome due to lacrimal hypersecretion"]'::jsonb, 3, 'The lower canaliculus carries approximately 70% of the tear drainage from the ocular surface to the lacrimal sac. If the canaliculus is not repaired or heals with scarring/occlusion, the patient will develop **chronic, debilitating epiphora (persistent tearing and overflow of tears)**. This causes significant visual blurring and skin irritation.'),
    (v_case_id, 'Which critical muscle and tendon structures are located in the medial canthus and must be carefully reanchored during repair to prevent eyelid deformity?', '["Corrugator supercilii and frontalis muscle", "Superior oblique muscle and Tenon''s capsule", "Medial canthal tendon and orbicularis oculi muscle", "Lateral palpebral ligament and levator palpebrae superioris", "Inferior rectus muscle and lockwood''s ligament"]'::jsonb, 2, 'The **medial canthal tendon** and the **pars lacrimalis of the orbicularis oculi muscle (Horner''s muscle)** are located medially and are responsible for anchoring the eyelid to the lacrimal bone and driving the ''lacrimal pump'' that sucks tears into the drainage system. Failure to carefully reanchor these structures leads to **ectropion** (eyelid turning outward), medial canthal rounding, and permanent tearing dysfunction.');

    ---------------------------------------------------------------------------
    -- CASE 20: The Hammer and Siderosis - Clinical Presentation (V2)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Hammer and Siderosis - Clinical Presentation (V2)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Hammer and Siderosis - Clinical Presentation (V2)', 'A 33-year-old carpenter presents with mild discomfort and slightly blurry vision in his right eye.  He reports that he was hammering steel-on-steel 2 days ago without safety goggles when he felt a tiny ''tweak'' or splash of water in his eye, but did not think much of it until the vision became slightly fuzzy today.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 72 bpm | BP: 120/80 mmHg
*   **Visual Acuity:** OD: 20/40; contralateral eye: 20/20
*   **Ocular Examination (OD):** A tiny, self-sealing 1-mm corneal wound is visible at the 9 o''clock position. Directly behind it, there is a small **iris transillumination defect (hole)**. The lens reveals a tiny, localized **focal cataract** in the path of the injury. Dilated fundus examination reveals a small, shiny, metallic **foreign body** lodged in the vitreous cavity inferiorly, surrounded by a localized vitreous hemorrhage. No retinal detachment is seen. IOP is 12 mmHg.', 20) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 33-year-old carpenter presents with mild discomfort and slightly blurry vision in his right eye.  He reports that he was hammering steel-on-steel 2 days ago without safety goggles when he felt a tiny ''tweak'' or splash of water in his eye, but did not think much of it until the vision became slightly fuzzy today.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 72 bpm | BP: 120/80 mmHg
*   **Visual Acuity:** OD: 20/40; contralateral eye: 20/20
*   **Ocular Examination (OD):** A tiny, self-sealing 1-mm corneal wound is visible at the 9 o''clock position. Directly behind it, there is a small **iris transillumination defect (hole)**. The lens reveals a tiny, localized **focal cataract** in the path of the injury. Dilated fundus examination reveals a small, shiny, metallic **foreign body** lodged in the vitreous cavity inferiorly, surrounded by a localized vitreous hemorrhage. No retinal detachment is seen. IOP is 12 mmHg.', "order" = 20 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the diagnosis, and what is the definitive management for this patient?', '["Penetrating Intraocular Foreign Body (IOFB); urgent surgical pars plana vitrectomy with removal of the foreign body", "Traumatic uveitis; initiate topical corticosteroid drops and monitor closely as an outpatient", "Corneal foreign body; perform bedside removal using a sterile needle under topical anesthesia", "Dry AMD; prescribe high-dose AREDS2 vitamins and reassure", "Ruptured globe; apply a tight pressure patch and perform daily outpatient visual acuity checks"]'::jsonb, 0, 'This is a **Penetrating Intraocular Foreign Body (IOFB)**. Even if the entry wound is self-sealing and the eye is quiet, a foreign body lodged inside the vitreous cavity is a high risk for endophthalmitis and chronic toxicity. Definitive management is **urgent surgical pars plana vitrectomy (PPV)** to remove the foreign body, repair any retinal tears, and administer intravitreal antibiotics.'),
    (v_case_id, 'Which diagnostic imaging modality is strictly CONTRAINDICATED if a metallic intraocular foreign body is suspected?', '["B-scan ultrasound of the globe", "Magnetic Resonance Imaging (MRI) of the brain and orbits", "Standard orbital X-ray (Caldwell and Waters views)", "High-resolution CT scan of the orbits without contrast", "Fluorescein angiography of the retina"]'::jsonb, 1, 'If a metallic (ferrous) intraocular foreign body is suspected, **MRI is strictly contraindicated**. The powerful magnetic field of the MRI will cause the metallic foreign body to **move, rotate, or migrate** within the eye, leading to catastrophic shearing of the retina, vitreous hemorrhage, or lens rupture. **High-resolution CT scan** is the gold standard imaging modality of choice.'),
    (v_case_id, 'What is the chronic, blinding toxicity condition that occurs if a ferrous (iron-containing) intraocular foreign body is left inside the eye for months or years?', '["Siderosis bulbi, caused by iron toxicity leading to degeneration of the retina and trabecular meshwork", "Neovascular glaucoma, driven by chronic iris ischemia", "Phacolytic glaucoma, caused by lens protein leaking through the capsule", "Chalcosis bulbi, caused by copper deposition in Descemet''s membrane", "Sympathetic ophthalmia, a granulomatous uveitis in the contralateral eye"]'::jsonb, 0, 'If a ferrous (iron) IOFB is left in the eye, the iron slowly oxidizes and dissolves, releasing toxic iron ions that deposit in and destroy intracellular structures. This is known as **Siderosis bulbi**. It leads to **degeneration of the retina** (manifesting as profound night blindness and pigmentary changes), **damage to the trabecular meshwork** (causing secondary open-angle glaucoma), and **cataract formation with iris heterochromia (turning the iris rusty brown)**.');

    ---------------------------------------------------------------------------
    -- CASE 21: Case Study: The Lime Splattered Eye (V3)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Case Study: The Lime Splattered Eye (V3)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Case Study: The Lime Splattered Eye (V3)', 'A 44-year-old construction worker presents to the emergency department immediately after a bag of wet concrete mix (calcium hydroxide/alkali) burst and splashed into his right eye 30 minutes ago. He reports intense, burning pain, severe tearing, and an inability to open the eye. He rinsed the eye for about 2 minutes at the site before coming in.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 95 bpm | BP: 135/85 mmHg
*   **Visual Acuity:** OD: 20/200; contralateral eye: 20/20
*   **Ocular Examination (OD):** Severe blepharospasm. After instilling topical anesthetic, slit-lamp exam reveals a moderately hazy cornea with a large epithelial defect. There is a prominent area of **limbal blanching and ischemia** (porcelain sclera) involving 180 degrees of the limbus. The conjunctiva is pale and necrotic in the blanched areas. The initial paper pH test of the conjunctival sac shows a pH of 11.0.', 21) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 44-year-old construction worker presents to the emergency department immediately after a bag of wet concrete mix (calcium hydroxide/alkali) burst and splashed into his right eye 30 minutes ago. He reports intense, burning pain, severe tearing, and an inability to open the eye. He rinsed the eye for about 2 minutes at the site before coming in.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 95 bpm | BP: 135/85 mmHg
*   **Visual Acuity:** OD: 20/200; contralateral eye: 20/20
*   **Ocular Examination (OD):** Severe blepharospasm. After instilling topical anesthetic, slit-lamp exam reveals a moderately hazy cornea with a large epithelial defect. There is a prominent area of **limbal blanching and ischemia** (porcelain sclera) involving 180 degrees of the limbus. The conjunctiva is pale and necrotic in the blanched areas. The initial paper pH test of the conjunctival sac shows a pH of 11.0.', "order" = 21 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the most immediate, critical next step in the management of this patient?', '["Perform copious irrigation with sterile saline or water using a Morgan lens until the ocular surface pH is neutralized to 7.0 - 7.2", "Administer systemic high-dose intravenous corticosteroids immediately", "Prepare the patient for urgent surgical corneal transplant (penetrating keratoplasty)", "Order an urgent CT scan of the brain and orbits to rule out foreign bodies", "Instill topical broad-spectrum antibiotic drops and apply a tight pressure patch"]'::jsonb, 0, 'An ocular chemical burn is a true emergency. The **most critical immediate step is copious irrigation** with sterile saline, balanced salt solution, or tap water (often using a Morgan lens) to flush the chemical. Irrigation must be continued continuously until the ocular surface pH is **fully neutralized (pH 7.0 - 7.2)**, measured 5-10 minutes after stopping irrigation. No other diagnostic test or treatment should delay this.'),
    (v_case_id, 'Why are alkali burns generally considered far more destructive and dangerous to the eye than acid burns?', '["Alkalies trigger immediate, severe bacterial keratitis within minutes of contact", "Alkalies selectively crystallize within the lens, causing immediate explosive cataract", "Alkalies cause saponification of cell membrane lipids and rapidly penetrate deep into the cornea and anterior chamber", "Alkalies directly coagulate corneal proteins, forming a barrier that limits deep tissue penetration", "Alkalies induce a rapid, autoimmune destruction of the contralateral eye"]'::jsonb, 2, '**Alkali substances** (like ammonia, lye, and lime/wet concrete) are highly lipophilic and cause **saponification of cell membrane lipids**. This allows them to **rapidly penetrate** through the corneal epithelium, stroma, and into the anterior chamber within minutes, causing extensive internal damage. In contrast, **acids** cause **coagulation of corneal proteins**, which forms a physical barrier that limits further deep penetration of the acid.'),
    (v_case_id, 'What is the clinical significance of ''limbal blanching and ischemia'' in a chemical burn?', '["It signifies that a metallic foreign body is embedded in the sclera", "It is a benign finding that represents temporary vasospasm and resolves spontaneously within 24 hours", "It indicates destruction of the limbal stem cells, which are essential for regenerating the corneal epithelium, signifying a poor prognosis", "It represents a localized type I hypersensitivity reaction to concrete proteins", "It indicates that the intraocular pressure has dropped to 0 mmHg"]'::jsonb, 2, '**Limbal blanching and ischemia** (appearing as a white, bloodless ''porcelain'' ring at the cornea-sclera junction) is a severe prognostic sign. The limbus houses the **limbal epithelial stem cells**, which are responsible for the continuous regeneration and maintenance of the corneal epithelium. Destruction of these stem cells leads to chronic epithelial defects, corneal scarring, visual degradation, and conjunctivalization.');

    ---------------------------------------------------------------------------
    -- CASE 22: Case Study: The Fingernail Scratch (V3)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Case Study: The Fingernail Scratch (V3)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Case Study: The Fingernail Scratch (V3)', 'A 35-year-old male presents to the clinic with intense pain, a severe foreign body sensation, constant tearing, and photophobia in his right eye. He reports that his 8-month-old infant accidentally scratched his eye with a fingernail while playing this morning.

**Physical Examination:**
*   **Vitals:** Temp: 98.5°F | HR: 71 bpm | BP: 115/81 mmHg
*   **Visual Acuity:** OD: 20/30 (improved with pinhole); contralateral eye: 20/20
*   **Ocular Examination (OD):** Marked conjunctival injection. Instillation of fluorescein dye and examination under cobalt blue light reveals a sharply demarcated, linear, bright green glowing area of epithelial loss measuring 3 mm x 2 mm in the central cornea. There is no white corneal infiltrate, no corneal thinning, and the anterior chamber is quiet. Pupil is reactive and normal.', 22) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 35-year-old male presents to the clinic with intense pain, a severe foreign body sensation, constant tearing, and photophobia in his right eye. He reports that his 8-month-old infant accidentally scratched his eye with a fingernail while playing this morning.

**Physical Examination:**
*   **Vitals:** Temp: 98.5°F | HR: 71 bpm | BP: 115/81 mmHg
*   **Visual Acuity:** OD: 20/30 (improved with pinhole); contralateral eye: 20/20
*   **Ocular Examination (OD):** Marked conjunctival injection. Instillation of fluorescein dye and examination under cobalt blue light reveals a sharply demarcated, linear, bright green glowing area of epithelial loss measuring 3 mm x 2 mm in the central cornea. There is no white corneal infiltrate, no corneal thinning, and the anterior chamber is quiet. Pupil is reactive and normal.', "order" = 22 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the most likely diagnosis, and what is the first-line pharmacotherapy?', '["Infectious bacterial keratitis; topical fortified vancomycin and tobramycin every 30 minutes", "Corneal abrasion; topical broad-spectrum antibiotic drops or ointment (e.g. erythromycin or polymyxin/trimethoprim)", "Dry eye syndrome; lifetime preservative-free artificial tears only", "Herpes simplex dendritic keratitis; topical acyclovir gel and oral valacyclovir", "Corneal ulcer; immediate outpatient surgical superficial keratectomy"]'::jsonb, 1, 'This is a simple **corneal abrasion** (epithelial defect without underlying stromal infection). First-line therapy consists of **topical broad-spectrum antibiotic drops or ointment** to prevent secondary bacterial infection while the epithelium heals, along with oral analgesics for pain control. Ointment (e.g., erythromycin) provides lubrication and comfort.'),
    (v_case_id, 'Why is the prescription of topical anesthetic drops (e.g. proparacaine) for home pain control strictly CONTRAINDICATED in patients with corneal abrasions?', '["Topical anesthetics promote the rapid growth of fungal spores in the stroma", "Topical anesthetics are directly toxic to the corneal epithelium, inhibit healing, and block the protective blink reflex, leading to severe corneal melting", "Topical anesthetics cause systemic cardiovascular toxicity and bradycardia through lacrimal absorption", "Topical anesthetics cause permanent pupillary dilation and acute angle closure", "Topical anesthetics neutralize the efficacy of topical antibiotics"]'::jsonb, 1, 'Prescribing **topical anesthetics (like proparacaine or tetracaine) for home use is strictly contraindicated**. These drugs are **highly toxic to the corneal epithelium** (epitheliotoxic), severely retard epithelial migration and wound healing, and **abolish the protective corneal blink reflex**. Abuse of these drops leads to progressive, painless **corneal stromal melting, ulceration, and permanent scarring**.'),
    (v_case_id, 'What is the most common long-term complication of a corneal abrasion caused by organic trauma (e.g., a fingernail or tree branch)?', '["Sympathetic ophthalmia in the contralateral eye", "Secondary open-angle pigmentary glaucoma", "Autoimmune uveitis associated with HLA-B27", "Recurrent corneal erosion syndrome, due to poor basement membrane adhesion", "Late-onset ectopia lentis and lens subluxation"]'::jsonb, 3, 'A classic complication of organic abrasions (fingernails, paper cuts, tree branches) is **Recurrent Corneal Erosion (RCE) syndrome**. The regenerated corneal epithelial cells fail to form proper hemidesmosomes and adhere securely to the underlying **Bowman''s membrane and basement membrane**. Weeks or months later, typically upon opening the eyes in the morning, the dry eyelid adheres to the loose epithelium and rips it off, causing a recurrence of severe pain and abrasion.');

    ---------------------------------------------------------------------------
    -- CASE 23: Case Study: The Machinist's Rust (V3)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Case Study: The Machinist''s Rust (V3)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Case Study: The Machinist''s Rust (V3)', 'A 20-year-old machinist presents with a 24-hour history of redness, gritty pain, and tearing in his left eye.  He reports that he was grinding steel yesterday afternoon without safety goggles and felt something fly into  his eye.

**Physical Examination:**
*   **Vitals:** Temp: 98.4°F | HR: 74 bpm | BP: 122/76 mmHg
*   **Visual Acuity:** OS: 20/30; contralateral eye: 20/20
*   **Ocular Examination (OS):** Slit-lamp biomicroscopy reveals a tiny, dark, metallic foreign body embedded in the superficial corneal stroma at the 4 o''clock position, outside of the visual axis. The foreign body is surrounded by a distinct, circular, orange-brown halo of **rust ring** diffusing into the stroma. The anterior chamber is deep and quiet (0 cells). No Seidel sign is present.', 23) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 20-year-old machinist presents with a 24-hour history of redness, gritty pain, and tearing in his left eye.  He reports that he was grinding steel yesterday afternoon without safety goggles and felt something fly into  his eye.

**Physical Examination:**
*   **Vitals:** Temp: 98.4°F | HR: 74 bpm | BP: 122/76 mmHg
*   **Visual Acuity:** OS: 20/30; contralateral eye: 20/20
*   **Ocular Examination (OS):** Slit-lamp biomicroscopy reveals a tiny, dark, metallic foreign body embedded in the superficial corneal stroma at the 4 o''clock position, outside of the visual axis. The foreign body is surrounded by a distinct, circular, orange-brown halo of **rust ring** diffusing into the stroma. The anterior chamber is deep and quiet (0 cells). No Seidel sign is present.', "order" = 23 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the correct management of this patient''s corneal foreign body and associated rust ring?', '["Flush the eye with systemic chelating agents (EDTA) for 12 hours", "Apply a pressure patch for 1 week and wait for the rust ring to dissolve systemically", "Initiate topical corticosteroid drops hourly to dissolve the iron deposits", "Remove the metallic foreign body immediately, and remove the rust ring either today or within 24-48 hours using a sterile needle, spud, or rotating ophthalmic burr under slit-lamp visualization", "Refer the patient for urgent surgical lamellar keratoplasty in the operating room"]'::jsonb, 3, 'Management requires **removal of both the foreign body and the rust ring**. The metallic foreign body is removed immediately using a sterile needle or spud under slit-lamp magnification. The **rust ring** (oxidized iron that diffuses into the stroma) is toxic and retards healing; it must be removed either at the same time or within 24-48 hours (when it softens) using a **rotating ophthalmic burr (Algerbrush)** or needle.'),
    (v_case_id, 'Within what timeframe does a metallic iron-containing corneal foreign body begin to form a visible rust ring in the stroma?', '["Only after 1 to 2 weeks of neglect", "Within 8 to 24 hours of injury", "Iron foreign bodies never form rust rings in the eye", "Exactly 30 days post-injury", "Immediately upon impact (within seconds)"]'::jsonb, 1, 'A metallic, iron-containing foreign body oxidizes rapidly when exposed to the moist environment of the tear film and corneal stroma. A **visible orange-brown rust ring** of iron deposition begins to form in the surrounding stroma **within 8 to 24 hours** of the injury. Early removal of the foreign body prevents extensive rust ring formation.'),
    (v_case_id, 'Following the removal of a corneal foreign body, which of the following is essential to prevent secondary complications?', '["Implantation of a soft contact lens directly over the rust ring", "Topical corticosteroid drops every hour for 2 weeks to prevent scarring", "Topical broad-spectrum antibiotics, checking tetanus vaccination status, and avoiding patching if the wound is dirty", "Oral acyclovir to prevent viral activation", "Dilating the pupil with atropine for 6 months to maintain muscle rest"]'::jsonb, 2, 'Following foreign body and rust removal, the patient has a corneal epithelial defect (abrasion). Essential care includes **topical broad-spectrum antibiotics** (drops/ointment) to prevent bacterial keratitis, and **updating their tetanus vaccination status** (as corneal wounds can rarely harbor tetanus). The eye is typically **not patched** if there is any suspicion of organic contamination or Pseudomonas risk (e.g. contact lens wearers).');

    ---------------------------------------------------------------------------
    -- CASE 24: Case Study: The Squash Ball Collision (V3)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Case Study: The Squash Ball Collision (V3)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Case Study: The Squash Ball Collision (V3)', 'A 16-year-old African American male presents to the emergency department after being struck directly in the left eye by a squash ball during a game. He reports sudden, severe pain and a dramatic decrease in vision. He denies any prior eye problems but notes he has sickle cell trait.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 88 bpm | BP: 122/78 mmHg
*   **Visual Acuity:** OS: 20/100; contralateral eye: 20/20
*   **Ocular Examination (OS):** Periorbital ecchymosis. Slit-lamp biomicroscopy reveals a prominent, layered column of red blood cells filling the inferior 30% of the anterior chamber (Grade II hyphema). The pupil is sluggish. The ciliary body is intact, and there is no open globe injury. The intraocular pressure is 31 mmHg (significantly elevated).', 24) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 16-year-old African American male presents to the emergency department after being struck directly in the left eye by a squash ball during a game. He reports sudden, severe pain and a dramatic decrease in vision. He denies any prior eye problems but notes he has sickle cell trait.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 88 bpm | BP: 122/78 mmHg
*   **Visual Acuity:** OS: 20/100; contralateral eye: 20/20
*   **Ocular Examination (OS):** Periorbital ecchymosis. Slit-lamp biomicroscopy reveals a prominent, layered column of red blood cells filling the inferior 30% of the anterior chamber (Grade II hyphema). The pupil is sluggish. The ciliary body is intact, and there is no open globe injury. The intraocular pressure is 31 mmHg (significantly elevated).', "order" = 24 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the primary underlying anatomical source of blood in a traumatic hyphema?', '["Bleeding from the retinal arterioles that dissects forward through the vitreous", "Rupture of Schlemm''s canal with retrograde venous flow into the chamber", "Exudative hemorrhage from damaged corneal endothelial cells", "Rupture of the blood vessels of the ciliary body face or iris root due to blunt contusion forces", "Rupture of ciliary body processes due to systemic hypertension"]'::jsonb, 3, 'A traumatic hyphema (blood in the anterior chamber) is caused by blunt contusion forces that compress the globe along its axial diameter and expand it equatorially. This sudden stretching force tears the anterior segment tissues, resulting in the **rupture of blood vessels of the ciliary body face, iris root, or major arterial circle of the iris**.'),
    (v_case_id, 'Why is a traumatic hyphema particularly dangerous in patients with sickle cell trait or disease, and what is the target IOP management?', '["Sickled erythrocytes are rigid and clog the trabecular meshwork, causing rapid, severe IOP elevation; even mild IOP elevation (>24 mmHg) can cause optic nerve ischemia, requiring aggressive control and avoiding systemic acetazolamide", "Sickle cell trait prevents the blood from clotting, causing continuous, unstoppable bleeding that fills the entire eye", "Sickle cell patients are completely immune to elevated IOP, so no treatment is required", "The blood in the anterior chamber reacts with sickle hemoglobin to cause irreversible iris necrosis within 2 hours", "Sickle cell patients have fragile corneas that melt rapidly when exposed to red blood cells in the anterior chamber"]'::jsonb, 0, 'Hyphema in a **sickle cell** patient is a high-risk situation. In the hypoxic, hyperosmolar anterior chamber, red blood cells sickling occurs. The rigid **sickled erythrocytes clog the trabecular meshwork**, causing rapid, severe IOP spikes. Furthermore, the compromised microcirculation of the optic nerve head in sickle cell patients makes them highly vulnerable to ischemic damage, so **even mild IOP elevations (>24 mmHg for >24 hours) can cause permanent optic nerve atrophy or central retinal artery occlusion**. Systemic **acetazolamide is strictly contraindicated** as it promotes sickling.'),
    (v_case_id, 'What represents the core conservative management recommendations for a patient with an uncomplicated traumatic hyphema?', '["Strict flat bed rest, a pressure patch, daily aspirin to prevent clotting, and hourly topical corticosteroids", "Immediate outpatient surgical anterior chamber washout and trabeculectomy", "Applying a tight pressure patch and scheduling follow-up in 1 month", "Initiation of systemic anticoagulation (warfarin) and vigorous physical exercise to clear the blood", "Bed rest with head of bed elevated 30-45 degrees, a rigid eye shield, topical cycloplegic drops, and avoiding aspirin/NSAIDs"]'::jsonb, 4, 'Conservative management for hyphema includes: (1) **bed rest with the head of the bed elevated 30 to 45 degrees** (allows blood to settle inferiorly, clearing the visual axis and preventing trabecular clogging), (2) a **rigid metal or plastic eye shield** to prevent accidental touch, (3) **topical cycloplegic drops** (e.g. atropine/cyclopentolate) for pupillary rest and pain control, and (4) **avoiding aspirin/NSAIDs** (which increase the risk of re-bleeding, typically occurring on days 3-5).');

    ---------------------------------------------------------------------------
    -- CASE 25: Case Study: The Fist and Floor (V3)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Case Study: The Fist and Floor (V3)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Case Study: The Fist and Floor (V3)', 'A 26-year-old male presents to the emergency department after being punched in the left eye during a street fight. He complains of pain, severe swelling, bruising, and double vision (diplopia), especially when looking up.  He also notes that his left cheek and upper lip feel numb.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 82 bpm | BP: 120/80 mmHg
*   **Ocular Examination (OS):** Marked periorbital ecchymosis and edema. Subconjunctival hemorrhage is present. There is **vertical diplopia on upgaze**, and testing of extraocular motility reveals a severe **restriction of elevation** in the affected eye. Sensation to light touch is significantly decreased over the ipsilateral cheek, side of the nose, and upper lip. CT scan of the orbits reveals a fracture of the **orbital floor** with herniation of orbital fat and entrapment of the **inferior rectus muscle**.', 25) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 26-year-old male presents to the emergency department after being punched in the left eye during a street fight. He complains of pain, severe swelling, bruising, and double vision (diplopia), especially when looking up.  He also notes that his left cheek and upper lip feel numb.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 82 bpm | BP: 120/80 mmHg
*   **Ocular Examination (OS):** Marked periorbital ecchymosis and edema. Subconjunctival hemorrhage is present. There is **vertical diplopia on upgaze**, and testing of extraocular motility reveals a severe **restriction of elevation** in the affected eye. Sensation to light touch is significantly decreased over the ipsilateral cheek, side of the nose, and upper lip. CT scan of the orbits reveals a fracture of the **orbital floor** with herniation of orbital fat and entrapment of the **inferior rectus muscle**.', "order" = 25 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the diagnosis, and which extraocular muscle is classically entrapped in this condition?', '["Superior orbital fissure syndrome; entrapment of all extraocular muscles", "Orbital roof blowout fracture; entrapment of the superior rectus muscle", "Orbital floor blowout fracture; entrapment of the inferior rectus muscle", "Medial orbital wall blowout fracture; entrapment of the medial rectus muscle", "Lateral orbital wall fracture; entrapment of the lateral rectus muscle"]'::jsonb, 2, 'This patient has an **orbital floor blowout fracture** (the most common type). The classic presentation is **vertical diplopia on upgaze** and **restriction of eye elevation** due to the mechanical **entrapment of the inferior rectus muscle** (and/or surrounding orbital fat/fascia) within the fractured bony fragments of the maxillary bone.'),
    (v_case_id, 'Which cranial nerve is injured, resulting in the numbness of the cheek, side of the nose, and upper lip?', '["Infraorbital nerve, a branch of the maxillary division of the trigeminal nerve (CN V2)", "Abducens nerve (CN VI)", "Oculomotor nerve (CN III), inferior division", "Facial nerve (CN VII), buccal branch", "Supraorbital nerve, a branch of the ophthalmic division of the trigeminal nerve (CN V1)"]'::jsonb, 0, 'The **infraorbital nerve** (a terminal branch of the **maxillary division of the trigeminal nerve, CN V2**) travels along the infraorbital groove and canal in the orbital floor. Fractures of the orbital floor frequently bruise, compress, or lacerate this nerve, resulting in **hypoesthesia/numbness of the ipsilateral cheek, lateral nose, upper lip, and anterior maxillary gingiva**.'),
    (v_case_id, 'Which of the following is a critical instruction that must be given to patients diagnosed with an acute orbital blowout fracture?', '["Perform heavy weightlifting to reduce intraorbital venous pressure", "Avoid sleeping with their head elevated", "Vigorously blow their nose to clear any blood or fluid from the maxillary sinus", "Apply a high-pressure patch over the eye for 72 hours", "Strictly avoid blowing their nose to prevent orbital emphysema and potential optic nerve compression"]'::jsonb, 4, 'Patients with acute orbital fractures must be **strictly instructed not to blow their nose**. Blowing the nose creates high pressure in the paranasal sinuses (maxillary/ethmoid). This pressure forces air and sinus bacteria through the fracture line into the orbit, causing **orbital emphysema** (which can compress the optic nerve and cause blindness) and increasing the risk of **orbital cellulitis**.');

    ---------------------------------------------------------------------------
    -- CASE 26: Case Study: The Flying Metal Shard (V3)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Case Study: The Flying Metal Shard (V3)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Case Study: The Flying Metal Shard (V3)', 'A 35-year-old construction worker is brought to the emergency department after a metal shard flew off a hammering tool and struck his right eye. He was not wearing safety goggles. He complains of sudden, severe pain and instant, profound loss of vision in that eye. He reports a watery discharge flowing from the eye immediately after the impact.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 90 bpm | BP: 130/80 mmHg
*   **Visual Acuity:** OD: Hand Motion (light projection intact); contralateral eye: 20/20
*   **Ocular Examination (OD):** Diffuse subconjunctival hemorrhage. The anterior chamber is shallow and filled with RBCs (microhyphema). The pupil is peaked and **teardrop-shaped**, pointing towards a 3-mm laceration at the limbus. A small amount of dark, uveal tissue (iris) is prolapsing through the wound. Examination of the wound under cobalt blue light reveals a **positive Seidel sign** (a clear stream of aqueous humor diluting and washing away fluorescein dye).', 26) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 35-year-old construction worker is brought to the emergency department after a metal shard flew off a hammering tool and struck his right eye. He was not wearing safety goggles. He complains of sudden, severe pain and instant, profound loss of vision in that eye. He reports a watery discharge flowing from the eye immediately after the impact.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 90 bpm | BP: 130/80 mmHg
*   **Visual Acuity:** OD: Hand Motion (light projection intact); contralateral eye: 20/20
*   **Ocular Examination (OD):** Diffuse subconjunctival hemorrhage. The anterior chamber is shallow and filled with RBCs (microhyphema). The pupil is peaked and **teardrop-shaped**, pointing towards a 3-mm laceration at the limbus. A small amount of dark, uveal tissue (iris) is prolapsing through the wound. Examination of the wound under cobalt blue light reveals a **positive Seidel sign** (a clear stream of aqueous humor diluting and washing away fluorescein dye).', "order" = 26 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the diagnosis, and what is the significance of the teardrop pupil and positive Seidel test?', '["Severe corneal abrasion; teardrop pupil is a normal physiological variant, Seidel test is positive in any tear film excess", "Traumatic hyphema; teardrop pupil is due to iris sphincter rupture, Seidel test indicates red blood cells clogging the cornea", "Orbital compartment syndrome; teardrop pupil indicates optic nerve compression, Seidel test is negative", "Traumatic uveitis; teardrop pupil represents severe ciliary spasm, Seidel test is positive due to high protein exudation", "Ruptured globe / open globe injury; teardrop pupil points to the site of wound, positive Seidel test indicates active aqueous leakage from a full-thickness laceration"]'::jsonb, 4, 'This is a **ruptured globe (open globe injury)**, a surgical emergency. The **teardrop pupil** is highly characteristic, as intraocular pressure forces the iris to prolapse towards the escape wound, pointing like an arrow to the laceration. The **positive Seidel test** (aqueous fluid stream washing away fluorescein dye under cobalt blue light) confirms a **full-thickness wound** with active external leakage of aqueous humor.'),
    (v_case_id, 'Which of the following is strictly CONTRAINDICATED during the emergency department evaluation of a suspected ruptured globe?', '["Ordering a high-resolution CT scan of the orbits without contrast", "Performing applanation tonometry (IOP measurement) or applying any pressure to the globe", "Keeping the patient strictly NPO (nothing by mouth) for surgery", "Placing a rigid, non-contact eye shield resting on the orbital bones", "Administering systemic intravenous antibiotics and antiemetics"]'::jsonb, 1, 'In a suspected ruptured globe, **any manipulation or pressure on the eye is strictly contraindicated**. This includes performing **tonometry (IOP measurement)**, opening the eyelids forcibly, or performing a dilated fundus exam. Any external pressure can cause **extrusion of the intraocular contents** (iris, lens, vitreous, retina) through the wound, resulting in irreversible blindness.'),
    (v_case_id, 'What are the immediate, first-line management steps for a patient with a confirmed ruptured globe in the emergency department?', '["Perform immediate anterior chamber paracentesis to lower the intraocular pressure", "Instill topical corticosteroid and anesthetic drops hourly, and discharge the patient home", "Place a rigid metal/plastic eye shield, keep NPO, initiate IV broad-spectrum antibiotics, administer IV antiemetics, update tetanus, and schedule urgent surgical repair within 24 hours", "Apply a tight pressure patch, prescribe oral pain medications, and schedule outpatient ophthalmology follow-up in 1 week", "Perform immediate bedside surgical suturing of the cornea under topical anesthesia"]'::jsonb, 2, 'Immediate management of a ruptured globe includes: (1) placing a **rigid eye shield** (e.g. Fox shield) resting on the brow and cheek bones (never place a patch or pad that contacts the eyelids), (2) keeping the patient **strictly NPO** in preparation for urgent surgery, (3) administering **IV broad-spectrum antibiotics** (e.g., cefazolin + levofloxacin) to prevent endophthalmitis, (4) administering **IV antiemetics** (e.g., ondansetron) to prevent vomiting (which raises intraocular pressure), (5) updating **tetanus status**, and (6) securing **urgent surgical closure** in the OR within 24 hours.');

    ---------------------------------------------------------------------------
    -- CASE 27: Case Study: The Rock-Hard Orbit (V3)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Case Study: The Rock-Hard Orbit (V3)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Case Study: The Rock-Hard Orbit (V3)', 'A 46-year-old male presents to the emergency department immediately after sustaining severe blunt facial trauma from a baseball bat. He reports excruciating pain and rapidly progressive vision loss in the left eye.  He has a history of mild hypertension.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 105 bpm | BP: 142/90 mmHg
*   **Visual Acuity:** OS: 20/400 (no improvement with pinhole); contralateral eye: 20/20
*   **Ocular Examination (OS):** Extreme, tense **proptosis** and massive subconjunctival hemorrhage. The eyelids are extremely swollen, tense, and **rock-hard to palpation**, making it highly difficult to separate them. There is a prominent **relative afferent pupillary defect (RAPD)** in the affected eye. Extraocular movements are completely restricted in all directions (ophthalmoplegia). The intraocular pressure is 47 mmHg.', 27) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 46-year-old male presents to the emergency department immediately after sustaining severe blunt facial trauma from a baseball bat. He reports excruciating pain and rapidly progressive vision loss in the left eye.  He has a history of mild hypertension.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 105 bpm | BP: 142/90 mmHg
*   **Visual Acuity:** OS: 20/400 (no improvement with pinhole); contralateral eye: 20/20
*   **Ocular Examination (OS):** Extreme, tense **proptosis** and massive subconjunctival hemorrhage. The eyelids are extremely swollen, tense, and **rock-hard to palpation**, making it highly difficult to separate them. There is a prominent **relative afferent pupillary defect (RAPD)** in the affected eye. Extraocular movements are completely restricted in all directions (ophthalmoplegia). The intraocular pressure is 47 mmHg.', "order" = 27 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the diagnosis, and what is the most urgent, vision-saving intervention for this patient?', '["Optic neuritis; initiate high-dose intravenous methylprednisolone within 1 hour", "Ruptured globe; immediate surgical exploration in the operating room", "Blowout fracture; order an urgent facial CT scan and administer oral prednisone", "Orbital Compartment Syndrome (OCS) due to retrobulbar hemorrhage; immediate bedside lateral canthotomy and cantholysis", "Carotid-cavernous fistula; urgent carotid artery angiography and embolization"]'::jsonb, 3, 'This patient has **Orbital Compartment Syndrome (OCS)** secondary to a **retrobulbar hemorrhage** (bleeding behind the eye). This is a vision-threatening emergency. The most urgent intervention is **immediate bedside lateral canthotomy and cantholysis (LCC)**. LCC must be performed **immediately at the bedside without waiting for CT scans or ophthalmology arrival**, as irreversible ischemic blindness occurs within 90-120 minutes.'),
    (v_case_id, 'What is the primary pathophysiological mechanism by which OCS leads to rapid, irreversible blindness?', '["The blood in the orbit triggers a rapid, autoimmune destruction of the contralateral retina", "Chronic bacterial infection spreads from the retrobulbar space to the brain", "The compression forces the crystalline lens backward, crushing the vitreous", "High intraorbital pressure compromises perfusion to the optic nerve and retina, causing central retinal artery occlusion or ischemic optic neuropathy", "The retrobulbar blood directly dissects into the optic nerve sheath and destroys axons"]'::jsonb, 3, 'Because the orbit is a closed, rigid bony compartment bounded anteriorly by the stiff orbital septum and eyelids, a **retrobulbar hemorrhage** causes a rapid rise in intraorbital pressure. When the orbital pressure exceeds the perfusion pressure of the microvasculature, it **compromises blood flow to the optic nerve and retina**, resulting in **central retinal artery occlusion (CRAO)** or **anterior/posterior ischemic optic neuropathy**.'),
    (v_case_id, 'How does performing a lateral canthotomy and cantholysis relieve the elevated intraorbital pressure?', '["It releases the lateral palpebral ligament, allowing the eyelids and orbital contents to expand forward, rapidly reducing intraorbital pressure", "It allows the surgeon to physically push the globe back into the orbit", "It allows the retrobulbar blood to drain completely out of the lateral wound", "It paralyzes the extraocular muscles, reducing metabolic demand", "It directly decompresses the maxillary sinus to relieve pressure"]'::jsonb, 0, 'Performing a **lateral canthotomy** (cutting the lateral canthal tendon) and **cantholysis** (specifically cutting the superior and inferior crus of the lateral palpebral ligament) **releases the attachment of the eyelids to the lateral orbital rim**. This allows the **eyelids and globe to expand forward (increasing proptosis)**, which rapidly decompresses the closed orbital compartment, lowering the pressure from dangerous levels (>40-50 mmHg) to safe levels almost instantly.');

    ---------------------------------------------------------------------------
    -- CASE 28: Case Study: The Numb RAPD (V3)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Case Study: The Numb RAPD (V3)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Case Study: The Numb RAPD (V3)', 'A 21-year-old female is brought to the emergency department after falling off a bicycle and striking the right side of her forehead against the concrete curb. She did not lose consciousness but complains of profound, painless vision loss in her right eye. She has no other injuries.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 76 bpm | BP: 120/80 mmHg
*   **Visual Acuity:** OD: 20/400; contralateral eye: 20/20
*   **Ocular Examination (OD):** Mild bruising over the forehead and brow. The globe is completely intact, eyelids are soft, and anterior chamber is quiet. IOP is 14 mmHg OU. However, there is a **prominent relative afferent pupillary defect (RAPD)** in the affected eye. Dilated fundus examination reveals a **completely normal optic nerve head** with healthy color and sharp margins. Contralateral eye is normal.', 28) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 21-year-old female is brought to the emergency department after falling off a bicycle and striking the right side of her forehead against the concrete curb. She did not lose consciousness but complains of profound, painless vision loss in her right eye. She has no other injuries.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 76 bpm | BP: 120/80 mmHg
*   **Visual Acuity:** OD: 20/400; contralateral eye: 20/20
*   **Ocular Examination (OD):** Mild bruising over the forehead and brow. The globe is completely intact, eyelids are soft, and anterior chamber is quiet. IOP is 14 mmHg OU. However, there is a **prominent relative afferent pupillary defect (RAPD)** in the affected eye. Dilated fundus examination reveals a **completely normal optic nerve head** with healthy color and sharp margins. Contralateral eye is normal.', "order" = 28 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the most likely diagnosis?', '["Malingering or functional vision loss", "Acute optic neuritis", "Traumatic Optic Neuropathy (TON)", "Central retinal artery occlusion (CRAO)", "Retinal detachment"]'::jsonb, 2, 'This patient has **Traumatic Optic Neuropathy (TON)**, which classically presents as **profound vision loss** following blunt head or orbital trauma, accompanied by a **relative afferent pupillary defect (RAPD)**, in the setting of a **completely normal-appearing optic nerve head** acutely. The nerve is damaged retrobulbar (often inside the optic canal).'),
    (v_case_id, 'Why does the optic nerve head appear completely normal during the acute phase of Traumatic Optic Neuropathy?', '["The visual loss is purely psychological and there is no real nerve damage", "The nerve is temporarily stunned (neuropraxia) and does not undergo physical changes", "The contralateral eye is compensating by sending blood flow to the damaged disc", "The swollen optic nerve is hidden by the vitreous gel", "The injury is retrobulbar (within the optic canal), and retrograde degeneration of the axons takes 4 to 6 weeks to manifest as disc pallor"]'::jsonb, 4, 'Acutely, the optic disc appears **completely normal** because the site of injury in TON is typically **retrobulbar** (most commonly within the bony **optic canal**, where the nerve is sheared or compressed by bone fragments or microvascular ischemia). It takes **4 to 6 weeks for retrograde axoplasmic degeneration** to travel from the site of injury back to the optic nerve head, at which point the disc will develop permanent **optic atrophy and pallor**.'),
    (v_case_id, 'Which of the following is the diagnostic test of choice to evaluate a patient with suspected Traumatic Optic Neuropathy?', '["Lumbar puncture to measure cerebrospinal fluid opening pressure", "High-resolution CT scan of the brain and orbits with thin cuts through the optic canal", "Ocular B-scan ultrasound of the posterior segment", "Electroretinography (ERG)", "Fluorescein angiography of the retina"]'::jsonb, 1, 'The diagnostic test of choice is a **high-resolution CT scan of the brain and orbits with thin cuts (1 mm) through the optic canal**. This is essential to evaluate for **optic canal fractures**, bony spicules compressing the nerve, or hematomas within the canal that might warrant surgical decompression.');

    ---------------------------------------------------------------------------
    -- CASE 29: Case Study: The Torn Tear Duct (V3)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Case Study: The Torn Tear Duct (V3)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Case Study: The Torn Tear Duct (V3)', 'An 7-year-old child is brought to the emergency department by her parents after being scratched in the face by a dog. The child is crying but has no systemic symptoms. The parents note a deep cut in the child''s left lower eyelid.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 85 bpm | BP: 110/70 mmHg
*   **Visual Acuity:** Bilateral 20/20 (corrected)
*   **Ocular Examination:** The left globe is completely intact, with no conjunctival injection, clear cornea, and quiet anterior chamber. However, there is a deep, full-thickness **laceration of the left lower eyelid medial to the punctum**, completely transecting the medial canthal angle and the **lower lacrimal canaliculus**. The laceration extends down to the orbicularis oculi muscle.', 29) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'An 7-year-old child is brought to the emergency department by her parents after being scratched in the face by a dog. The child is crying but has no systemic symptoms. The parents note a deep cut in the child''s left lower eyelid.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 85 bpm | BP: 110/70 mmHg
*   **Visual Acuity:** Bilateral 20/20 (corrected)
*   **Ocular Examination:** The left globe is completely intact, with no conjunctival injection, clear cornea, and quiet anterior chamber. However, there is a deep, full-thickness **laceration of the left lower eyelid medial to the punctum**, completely transecting the medial canthal angle and the **lower lacrimal canaliculus**. The laceration extends down to the orbicularis oculi muscle.', "order" = 29 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the management, and where should this repair ideally be performed?', '["Simple bedside closure of the skin laceration using steri-strips or skin glue", "Applying a tight pressure patch for 2 weeks and letting the tear duct heal spontaneously", "Performing immediate surgical excision of the entire lacrimal gland", "Prescribing oral antibiotics and sending the child home without closure", "Surgical repair in the operating room under microscopic visualization, involving canalicular stenting (e.g. Crawford or monocanalicular stent) and meticulous suturing"]'::jsonb, 4, 'A lid laceration medial to the punctum that **transects the lacrimal canaliculus** requires specialized **surgical repair in the operating room**. Under microscopic magnification, the cut ends of the canaliculus must be identified, **stented with a silicone tube** (e.g., Crawford stent or Monoka) to maintain the patency of the lumen during healing, and the surrounding tissues repaired meticulously. Simple skin suturing is a failure of care.'),
    (v_case_id, 'What is the primary long-term complication if a canalicular laceration is not repaired or is repaired poorly?', '["Chronic, intractable dry eye syndrome due to lacrimal hypersecretion", "Severe, progressive orbital blowout fracture and diplopia", "Chronic, debilitating epiphora (overflow of tears) due to disruption of the tear drainage system", "Permanent loss of central visual acuity and macular edema", "Autoimmune sympathetic ophthalmia in the contralateral eye"]'::jsonb, 2, 'The lower canaliculus carries approximately 70% of the tear drainage from the ocular surface to the lacrimal sac. If the canaliculus is not repaired or heals with scarring/occlusion, the patient will develop **chronic, debilitating epiphora (persistent tearing and overflow of tears)**. This causes significant visual blurring and skin irritation.'),
    (v_case_id, 'Which critical muscle and tendon structures are located in the medial canthus and must be carefully reanchored during repair to prevent eyelid deformity?', '["Superior oblique muscle and Tenon''s capsule", "Lateral palpebral ligament and levator palpebrae superioris", "Inferior rectus muscle and lockwood''s ligament", "Corrugator supercilii and frontalis muscle", "Medial canthal tendon and orbicularis oculi muscle"]'::jsonb, 4, 'The **medial canthal tendon** and the **pars lacrimalis of the orbicularis oculi muscle (Horner''s muscle)** are located medially and are responsible for anchoring the eyelid to the lacrimal bone and driving the ''lacrimal pump'' that sucks tears into the drainage system. Failure to carefully reanchor these structures leads to **ectropion** (eyelid turning outward), medial canthal rounding, and permanent tearing dysfunction.');

    ---------------------------------------------------------------------------
    -- CASE 30: Case Study: The Hammer and Siderosis (V3)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Case Study: The Hammer and Siderosis (V3)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Case Study: The Hammer and Siderosis (V3)', 'A 31-year-old carpenter presents with mild discomfort and slightly blurry vision in his right eye.  He reports that he was hammering steel-on-steel 2 days ago without safety goggles when he felt a tiny ''tweak'' or splash of water in his eye, but did not think much of it until the vision became slightly fuzzy today.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 72 bpm | BP: 120/80 mmHg
*   **Visual Acuity:** OD: 20/40; contralateral eye: 20/20
*   **Ocular Examination (OD):** A tiny, self-sealing 1-mm corneal wound is visible at the 9 o''clock position. Directly behind it, there is a small **iris transillumination defect (hole)**. The lens reveals a tiny, localized **focal cataract** in the path of the injury. Dilated fundus examination reveals a small, shiny, metallic **foreign body** lodged in the vitreous cavity inferiorly, surrounded by a localized vitreous hemorrhage. No retinal detachment is seen. IOP is 12 mmHg.', 30) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 31-year-old carpenter presents with mild discomfort and slightly blurry vision in his right eye.  He reports that he was hammering steel-on-steel 2 days ago without safety goggles when he felt a tiny ''tweak'' or splash of water in his eye, but did not think much of it until the vision became slightly fuzzy today.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 72 bpm | BP: 120/80 mmHg
*   **Visual Acuity:** OD: 20/40; contralateral eye: 20/20
*   **Ocular Examination (OD):** A tiny, self-sealing 1-mm corneal wound is visible at the 9 o''clock position. Directly behind it, there is a small **iris transillumination defect (hole)**. The lens reveals a tiny, localized **focal cataract** in the path of the injury. Dilated fundus examination reveals a small, shiny, metallic **foreign body** lodged in the vitreous cavity inferiorly, surrounded by a localized vitreous hemorrhage. No retinal detachment is seen. IOP is 12 mmHg.', "order" = 30 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the diagnosis, and what is the definitive management for this patient?', '["Ruptured globe; apply a tight pressure patch and perform daily outpatient visual acuity checks", "Dry AMD; prescribe high-dose AREDS2 vitamins and reassure", "Traumatic uveitis; initiate topical corticosteroid drops and monitor closely as an outpatient", "Corneal foreign body; perform bedside removal using a sterile needle under topical anesthesia", "Penetrating Intraocular Foreign Body (IOFB); urgent surgical pars plana vitrectomy with removal of the foreign body"]'::jsonb, 4, 'This is a **Penetrating Intraocular Foreign Body (IOFB)**. Even if the entry wound is self-sealing and the eye is quiet, a foreign body lodged inside the vitreous cavity is a high risk for endophthalmitis and chronic toxicity. Definitive management is **urgent surgical pars plana vitrectomy (PPV)** to remove the foreign body, repair any retinal tears, and administer intravitreal antibiotics.'),
    (v_case_id, 'Which diagnostic imaging modality is strictly CONTRAINDICATED if a metallic intraocular foreign body is suspected?', '["Fluorescein angiography of the retina", "Magnetic Resonance Imaging (MRI) of the brain and orbits", "Standard orbital X-ray (Caldwell and Waters views)", "High-resolution CT scan of the orbits without contrast", "B-scan ultrasound of the globe"]'::jsonb, 1, 'If a metallic (ferrous) intraocular foreign body is suspected, **MRI is strictly contraindicated**. The powerful magnetic field of the MRI will cause the metallic foreign body to **move, rotate, or migrate** within the eye, leading to catastrophic shearing of the retina, vitreous hemorrhage, or lens rupture. **High-resolution CT scan** is the gold standard imaging modality of choice.'),
    (v_case_id, 'What is the chronic, blinding toxicity condition that occurs if a ferrous (iron-containing) intraocular foreign body is left inside the eye for months or years?', '["Siderosis bulbi, caused by iron toxicity leading to degeneration of the retina and trabecular meshwork", "Phacolytic glaucoma, caused by lens protein leaking through the capsule", "Neovascular glaucoma, driven by chronic iris ischemia", "Sympathetic ophthalmia, a granulomatous uveitis in the contralateral eye", "Chalcosis bulbi, caused by copper deposition in Descemet''s membrane"]'::jsonb, 0, 'If a ferrous (iron) IOFB is left in the eye, the iron slowly oxidizes and dissolves, releasing toxic iron ions that deposit in and destroy intracellular structures. This is known as **Siderosis bulbi**. It leads to **degeneration of the retina** (manifesting as profound night blindness and pigmentary changes), **damage to the trabecular meshwork** (causing secondary open-angle glaucoma), and **cataract formation with iris heterochromia (turning the iris rusty brown)**.');

    ---------------------------------------------------------------------------
    -- CASE 31: The Lime Splattered Eye - Case Analysis (V4)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Lime Splattered Eye - Case Analysis (V4)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Lime Splattered Eye - Case Analysis (V4)', 'A 36-year-old construction worker presents to the emergency department immediately after a bag of wet concrete mix (calcium hydroxide/alkali) burst and splashed into her right eye 30 minutes ago. She reports intense, burning pain, severe tearing, and an inability to open the eye. She rinsed the eye for about 2 minutes at the site before coming in.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 95 bpm | BP: 135/85 mmHg
*   **Visual Acuity:** OD: 20/200; contralateral eye: 20/20
*   **Ocular Examination (OD):** Severe blepharospasm. After instilling topical anesthetic, slit-lamp exam reveals a moderately hazy cornea with a large epithelial defect. There is a prominent area of **limbal blanching and ischemia** (porcelain sclera) involving 180 degrees of the limbus. The conjunctiva is pale and necrotic in the blanched areas. The initial paper pH test of the conjunctival sac shows a pH of 11.0.', 31) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 36-year-old construction worker presents to the emergency department immediately after a bag of wet concrete mix (calcium hydroxide/alkali) burst and splashed into her right eye 30 minutes ago. She reports intense, burning pain, severe tearing, and an inability to open the eye. She rinsed the eye for about 2 minutes at the site before coming in.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 95 bpm | BP: 135/85 mmHg
*   **Visual Acuity:** OD: 20/200; contralateral eye: 20/20
*   **Ocular Examination (OD):** Severe blepharospasm. After instilling topical anesthetic, slit-lamp exam reveals a moderately hazy cornea with a large epithelial defect. There is a prominent area of **limbal blanching and ischemia** (porcelain sclera) involving 180 degrees of the limbus. The conjunctiva is pale and necrotic in the blanched areas. The initial paper pH test of the conjunctival sac shows a pH of 11.0.', "order" = 31 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the most immediate, critical next step in the management of this patient?', '["Administer systemic high-dose intravenous corticosteroids immediately", "Order an urgent CT scan of the brain and orbits to rule out foreign bodies", "Perform copious irrigation with sterile saline or water using a Morgan lens until the ocular surface pH is neutralized to 7.0 - 7.2", "Prepare the patient for urgent surgical corneal transplant (penetrating keratoplasty)", "Instill topical broad-spectrum antibiotic drops and apply a tight pressure patch"]'::jsonb, 2, 'An ocular chemical burn is a true emergency. The **most critical immediate step is copious irrigation** with sterile saline, balanced salt solution, or tap water (often using a Morgan lens) to flush the chemical. Irrigation must be continued continuously until the ocular surface pH is **fully neutralized (pH 7.0 - 7.2)**, measured 5-10 minutes after stopping irrigation. No other diagnostic test or treatment should delay this.'),
    (v_case_id, 'Why are alkali burns generally considered far more destructive and dangerous to the eye than acid burns?', '["Alkalies directly coagulate corneal proteins, forming a barrier that limits deep tissue penetration", "Alkalies selectively crystallize within the lens, causing immediate explosive cataract", "Alkalies cause saponification of cell membrane lipids and rapidly penetrate deep into the cornea and anterior chamber", "Alkalies trigger immediate, severe bacterial keratitis within minutes of contact", "Alkalies induce a rapid, autoimmune destruction of the contralateral eye"]'::jsonb, 2, '**Alkali substances** (like ammonia, lye, and lime/wet concrete) are highly lipophilic and cause **saponification of cell membrane lipids**. This allows them to **rapidly penetrate** through the corneal epithelium, stroma, and into the anterior chamber within minutes, causing extensive internal damage. In contrast, **acids** cause **coagulation of corneal proteins**, which forms a physical barrier that limits further deep penetration of the acid.'),
    (v_case_id, 'What is the clinical significance of ''limbal blanching and ischemia'' in a chemical burn?', '["It is a benign finding that represents temporary vasospasm and resolves spontaneously within 24 hours", "It represents a localized type I hypersensitivity reaction to concrete proteins", "It indicates destruction of the limbal stem cells, which are essential for regenerating the corneal epithelium, signifying a poor prognosis", "It indicates that the intraocular pressure has dropped to 0 mmHg", "It signifies that a metallic foreign body is embedded in the sclera"]'::jsonb, 2, '**Limbal blanching and ischemia** (appearing as a white, bloodless ''porcelain'' ring at the cornea-sclera junction) is a severe prognostic sign. The limbus houses the **limbal epithelial stem cells**, which are responsible for the continuous regeneration and maintenance of the corneal epithelium. Destruction of these stem cells leads to chronic epithelial defects, corneal scarring, visual degradation, and conjunctivalization.');

    ---------------------------------------------------------------------------
    -- CASE 32: The Fingernail Scratch - Case Analysis (V4)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Fingernail Scratch - Case Analysis (V4)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Fingernail Scratch - Case Analysis (V4)', 'A 39-year-old male presents to the clinic with intense pain, a severe foreign body sensation, constant tearing, and photophobia in his right eye. He reports that his 8-month-old infant accidentally scratched his eye with a fingernail while playing this morning.

**Physical Examination:**
*   **Vitals:** Temp: 98.4°F | HR: 84 bpm | BP: 136/85 mmHg
*   **Visual Acuity:** OD: 20/30 (improved with pinhole); contralateral eye: 20/20
*   **Ocular Examination (OD):** Marked conjunctival injection. Instillation of fluorescein dye and examination under cobalt blue light reveals a sharply demarcated, linear, bright green glowing area of epithelial loss measuring 3 mm x 2 mm in the central cornea. There is no white corneal infiltrate, no corneal thinning, and the anterior chamber is quiet. Pupil is reactive and normal.', 32) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 39-year-old male presents to the clinic with intense pain, a severe foreign body sensation, constant tearing, and photophobia in his right eye. He reports that his 8-month-old infant accidentally scratched his eye with a fingernail while playing this morning.

**Physical Examination:**
*   **Vitals:** Temp: 98.4°F | HR: 84 bpm | BP: 136/85 mmHg
*   **Visual Acuity:** OD: 20/30 (improved with pinhole); contralateral eye: 20/20
*   **Ocular Examination (OD):** Marked conjunctival injection. Instillation of fluorescein dye and examination under cobalt blue light reveals a sharply demarcated, linear, bright green glowing area of epithelial loss measuring 3 mm x 2 mm in the central cornea. There is no white corneal infiltrate, no corneal thinning, and the anterior chamber is quiet. Pupil is reactive and normal.', "order" = 32 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the most likely diagnosis, and what is the first-line pharmacotherapy?', '["Herpes simplex dendritic keratitis; topical acyclovir gel and oral valacyclovir", "Infectious bacterial keratitis; topical fortified vancomycin and tobramycin every 30 minutes", "Dry eye syndrome; lifetime preservative-free artificial tears only", "Corneal abrasion; topical broad-spectrum antibiotic drops or ointment (e.g. erythromycin or polymyxin/trimethoprim)", "Corneal ulcer; immediate outpatient surgical superficial keratectomy"]'::jsonb, 3, 'This is a simple **corneal abrasion** (epithelial defect without underlying stromal infection). First-line therapy consists of **topical broad-spectrum antibiotic drops or ointment** to prevent secondary bacterial infection while the epithelium heals, along with oral analgesics for pain control. Ointment (e.g., erythromycin) provides lubrication and comfort.'),
    (v_case_id, 'Why is the prescription of topical anesthetic drops (e.g. proparacaine) for home pain control strictly CONTRAINDICATED in patients with corneal abrasions?', '["Topical anesthetics are directly toxic to the corneal epithelium, inhibit healing, and block the protective blink reflex, leading to severe corneal melting", "Topical anesthetics cause systemic cardiovascular toxicity and bradycardia through lacrimal absorption", "Topical anesthetics neutralize the efficacy of topical antibiotics", "Topical anesthetics promote the rapid growth of fungal spores in the stroma", "Topical anesthetics cause permanent pupillary dilation and acute angle closure"]'::jsonb, 0, 'Prescribing **topical anesthetics (like proparacaine or tetracaine) for home use is strictly contraindicated**. These drugs are **highly toxic to the corneal epithelium** (epitheliotoxic), severely retard epithelial migration and wound healing, and **abolish the protective corneal blink reflex**. Abuse of these drops leads to progressive, painless **corneal stromal melting, ulceration, and permanent scarring**.'),
    (v_case_id, 'What is the most common long-term complication of a corneal abrasion caused by organic trauma (e.g., a fingernail or tree branch)?', '["Recurrent corneal erosion syndrome, due to poor basement membrane adhesion", "Autoimmune uveitis associated with HLA-B27", "Sympathetic ophthalmia in the contralateral eye", "Secondary open-angle pigmentary glaucoma", "Late-onset ectopia lentis and lens subluxation"]'::jsonb, 0, 'A classic complication of organic abrasions (fingernails, paper cuts, tree branches) is **Recurrent Corneal Erosion (RCE) syndrome**. The regenerated corneal epithelial cells fail to form proper hemidesmosomes and adhere securely to the underlying **Bowman''s membrane and basement membrane**. Weeks or months later, typically upon opening the eyes in the morning, the dry eyelid adheres to the loose epithelium and rips it off, causing a recurrence of severe pain and abrasion.');

    ---------------------------------------------------------------------------
    -- CASE 33: The Machinist's Rust - Case Analysis (V4)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Machinist''s Rust - Case Analysis (V4)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Machinist''s Rust - Case Analysis (V4)', 'A 36-year-old machinist presents with a 24-hour history of redness, gritty pain, and tearing in his left eye.  He reports that he was grinding steel yesterday afternoon without safety goggles and felt something fly into  his eye.

**Physical Examination:**
*   **Vitals:** Temp: 98.4°F | HR: 74 bpm | BP: 122/76 mmHg
*   **Visual Acuity:** OS: 20/30; contralateral eye: 20/20
*   **Ocular Examination (OS):** Slit-lamp biomicroscopy reveals a tiny, dark, metallic foreign body embedded in the superficial corneal stroma at the 4 o''clock position, outside of the visual axis. The foreign body is surrounded by a distinct, circular, orange-brown halo of **rust ring** diffusing into the stroma. The anterior chamber is deep and quiet (0 cells). No Seidel sign is present.', 33) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 36-year-old machinist presents with a 24-hour history of redness, gritty pain, and tearing in his left eye.  He reports that he was grinding steel yesterday afternoon without safety goggles and felt something fly into  his eye.

**Physical Examination:**
*   **Vitals:** Temp: 98.4°F | HR: 74 bpm | BP: 122/76 mmHg
*   **Visual Acuity:** OS: 20/30; contralateral eye: 20/20
*   **Ocular Examination (OS):** Slit-lamp biomicroscopy reveals a tiny, dark, metallic foreign body embedded in the superficial corneal stroma at the 4 o''clock position, outside of the visual axis. The foreign body is surrounded by a distinct, circular, orange-brown halo of **rust ring** diffusing into the stroma. The anterior chamber is deep and quiet (0 cells). No Seidel sign is present.', "order" = 33 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the correct management of this patient''s corneal foreign body and associated rust ring?', '["Remove the metallic foreign body immediately, and remove the rust ring either today or within 24-48 hours using a sterile needle, spud, or rotating ophthalmic burr under slit-lamp visualization", "Flush the eye with systemic chelating agents (EDTA) for 12 hours", "Initiate topical corticosteroid drops hourly to dissolve the iron deposits", "Refer the patient for urgent surgical lamellar keratoplasty in the operating room", "Apply a pressure patch for 1 week and wait for the rust ring to dissolve systemically"]'::jsonb, 0, 'Management requires **removal of both the foreign body and the rust ring**. The metallic foreign body is removed immediately using a sterile needle or spud under slit-lamp magnification. The **rust ring** (oxidized iron that diffuses into the stroma) is toxic and retards healing; it must be removed either at the same time or within 24-48 hours (when it softens) using a **rotating ophthalmic burr (Algerbrush)** or needle.'),
    (v_case_id, 'Within what timeframe does a metallic iron-containing corneal foreign body begin to form a visible rust ring in the stroma?', '["Iron foreign bodies never form rust rings in the eye", "Within 8 to 24 hours of injury", "Exactly 30 days post-injury", "Only after 1 to 2 weeks of neglect", "Immediately upon impact (within seconds)"]'::jsonb, 1, 'A metallic, iron-containing foreign body oxidizes rapidly when exposed to the moist environment of the tear film and corneal stroma. A **visible orange-brown rust ring** of iron deposition begins to form in the surrounding stroma **within 8 to 24 hours** of the injury. Early removal of the foreign body prevents extensive rust ring formation.'),
    (v_case_id, 'Following the removal of a corneal foreign body, which of the following is essential to prevent secondary complications?', '["Dilating the pupil with atropine for 6 months to maintain muscle rest", "Implantation of a soft contact lens directly over the rust ring", "Topical corticosteroid drops every hour for 2 weeks to prevent scarring", "Oral acyclovir to prevent viral activation", "Topical broad-spectrum antibiotics, checking tetanus vaccination status, and avoiding patching if the wound is dirty"]'::jsonb, 4, 'Following foreign body and rust removal, the patient has a corneal epithelial defect (abrasion). Essential care includes **topical broad-spectrum antibiotics** (drops/ointment) to prevent bacterial keratitis, and **updating their tetanus vaccination status** (as corneal wounds can rarely harbor tetanus). The eye is typically **not patched** if there is any suspicion of organic contamination or Pseudomonas risk (e.g. contact lens wearers).');

    ---------------------------------------------------------------------------
    -- CASE 34: The Squash Ball Collision - Case Analysis (V4)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Squash Ball Collision - Case Analysis (V4)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Squash Ball Collision - Case Analysis (V4)', 'A 20-year-old African American male presents to the emergency department after being struck directly in the left eye by a squash ball during a game. He reports sudden, severe pain and a dramatic decrease in vision. He denies any prior eye problems but notes he has sickle cell trait.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 88 bpm | BP: 122/78 mmHg
*   **Visual Acuity:** OS: 20/100; contralateral eye: 20/20
*   **Ocular Examination (OS):** Periorbital ecchymosis. Slit-lamp biomicroscopy reveals a prominent, layered column of red blood cells filling the inferior 30% of the anterior chamber (Grade II hyphema). The pupil is sluggish. The ciliary body is intact, and there is no open globe injury. The intraocular pressure is 24 mmHg (significantly elevated).', 34) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 20-year-old African American male presents to the emergency department after being struck directly in the left eye by a squash ball during a game. He reports sudden, severe pain and a dramatic decrease in vision. He denies any prior eye problems but notes he has sickle cell trait.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 88 bpm | BP: 122/78 mmHg
*   **Visual Acuity:** OS: 20/100; contralateral eye: 20/20
*   **Ocular Examination (OS):** Periorbital ecchymosis. Slit-lamp biomicroscopy reveals a prominent, layered column of red blood cells filling the inferior 30% of the anterior chamber (Grade II hyphema). The pupil is sluggish. The ciliary body is intact, and there is no open globe injury. The intraocular pressure is 24 mmHg (significantly elevated).', "order" = 34 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the primary underlying anatomical source of blood in a traumatic hyphema?', '["Rupture of ciliary body processes due to systemic hypertension", "Rupture of the blood vessels of the ciliary body face or iris root due to blunt contusion forces", "Exudative hemorrhage from damaged corneal endothelial cells", "Rupture of Schlemm''s canal with retrograde venous flow into the chamber", "Bleeding from the retinal arterioles that dissects forward through the vitreous"]'::jsonb, 1, 'A traumatic hyphema (blood in the anterior chamber) is caused by blunt contusion forces that compress the globe along its axial diameter and expand it equatorially. This sudden stretching force tears the anterior segment tissues, resulting in the **rupture of blood vessels of the ciliary body face, iris root, or major arterial circle of the iris**.'),
    (v_case_id, 'Why is a traumatic hyphema particularly dangerous in patients with sickle cell trait or disease, and what is the target IOP management?', '["Sickle cell patients have fragile corneas that melt rapidly when exposed to red blood cells in the anterior chamber", "Sickle cell trait prevents the blood from clotting, causing continuous, unstoppable bleeding that fills the entire eye", "Sickled erythrocytes are rigid and clog the trabecular meshwork, causing rapid, severe IOP elevation; even mild IOP elevation (>24 mmHg) can cause optic nerve ischemia, requiring aggressive control and avoiding systemic acetazolamide", "Sickle cell patients are completely immune to elevated IOP, so no treatment is required", "The blood in the anterior chamber reacts with sickle hemoglobin to cause irreversible iris necrosis within 2 hours"]'::jsonb, 2, 'Hyphema in a **sickle cell** patient is a high-risk situation. In the hypoxic, hyperosmolar anterior chamber, red blood cells sickling occurs. The rigid **sickled erythrocytes clog the trabecular meshwork**, causing rapid, severe IOP spikes. Furthermore, the compromised microcirculation of the optic nerve head in sickle cell patients makes them highly vulnerable to ischemic damage, so **even mild IOP elevations (>24 mmHg for >24 hours) can cause permanent optic nerve atrophy or central retinal artery occlusion**. Systemic **acetazolamide is strictly contraindicated** as it promotes sickling.'),
    (v_case_id, 'What represents the core conservative management recommendations for a patient with an uncomplicated traumatic hyphema?', '["Immediate outpatient surgical anterior chamber washout and trabeculectomy", "Strict flat bed rest, a pressure patch, daily aspirin to prevent clotting, and hourly topical corticosteroids", "Bed rest with head of bed elevated 30-45 degrees, a rigid eye shield, topical cycloplegic drops, and avoiding aspirin/NSAIDs", "Applying a tight pressure patch and scheduling follow-up in 1 month", "Initiation of systemic anticoagulation (warfarin) and vigorous physical exercise to clear the blood"]'::jsonb, 2, 'Conservative management for hyphema includes: (1) **bed rest with the head of the bed elevated 30 to 45 degrees** (allows blood to settle inferiorly, clearing the visual axis and preventing trabecular clogging), (2) a **rigid metal or plastic eye shield** to prevent accidental touch, (3) **topical cycloplegic drops** (e.g. atropine/cyclopentolate) for pupillary rest and pain control, and (4) **avoiding aspirin/NSAIDs** (which increase the risk of re-bleeding, typically occurring on days 3-5).');

    ---------------------------------------------------------------------------
    -- CASE 35: The Fist and Floor - Case Analysis (V4)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Fist and Floor - Case Analysis (V4)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Fist and Floor - Case Analysis (V4)', 'A 33-year-old male presents to the emergency department after being punched in the right eye during a street fight. He complains of pain, severe swelling, bruising, and double vision (diplopia), especially when looking up.  He also notes that his right cheek and upper lip feel numb.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 82 bpm | BP: 120/80 mmHg
*   **Ocular Examination (OD):** Marked periorbital ecchymosis and edema. Subconjunctival hemorrhage is present. There is **vertical diplopia on upgaze**, and testing of extraocular motility reveals a severe **restriction of elevation** in the affected eye. Sensation to light touch is significantly decreased over the ipsilateral cheek, side of the nose, and upper lip. CT scan of the orbits reveals a fracture of the **orbital floor** with herniation of orbital fat and entrapment of the **inferior rectus muscle**.', 35) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 33-year-old male presents to the emergency department after being punched in the right eye during a street fight. He complains of pain, severe swelling, bruising, and double vision (diplopia), especially when looking up.  He also notes that his right cheek and upper lip feel numb.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 82 bpm | BP: 120/80 mmHg
*   **Ocular Examination (OD):** Marked periorbital ecchymosis and edema. Subconjunctival hemorrhage is present. There is **vertical diplopia on upgaze**, and testing of extraocular motility reveals a severe **restriction of elevation** in the affected eye. Sensation to light touch is significantly decreased over the ipsilateral cheek, side of the nose, and upper lip. CT scan of the orbits reveals a fracture of the **orbital floor** with herniation of orbital fat and entrapment of the **inferior rectus muscle**.', "order" = 35 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the diagnosis, and which extraocular muscle is classically entrapped in this condition?', '["Lateral orbital wall fracture; entrapment of the lateral rectus muscle", "Medial orbital wall blowout fracture; entrapment of the medial rectus muscle", "Orbital roof blowout fracture; entrapment of the superior rectus muscle", "Orbital floor blowout fracture; entrapment of the inferior rectus muscle", "Superior orbital fissure syndrome; entrapment of all extraocular muscles"]'::jsonb, 3, 'This patient has an **orbital floor blowout fracture** (the most common type). The classic presentation is **vertical diplopia on upgaze** and **restriction of eye elevation** due to the mechanical **entrapment of the inferior rectus muscle** (and/or surrounding orbital fat/fascia) within the fractured bony fragments of the maxillary bone.'),
    (v_case_id, 'Which cranial nerve is injured, resulting in the numbness of the cheek, side of the nose, and upper lip?', '["Oculomotor nerve (CN III), inferior division", "Facial nerve (CN VII), buccal branch", "Supraorbital nerve, a branch of the ophthalmic division of the trigeminal nerve (CN V1)", "Infraorbital nerve, a branch of the maxillary division of the trigeminal nerve (CN V2)", "Abducens nerve (CN VI)"]'::jsonb, 3, 'The **infraorbital nerve** (a terminal branch of the **maxillary division of the trigeminal nerve, CN V2**) travels along the infraorbital groove and canal in the orbital floor. Fractures of the orbital floor frequently bruise, compress, or lacerate this nerve, resulting in **hypoesthesia/numbness of the ipsilateral cheek, lateral nose, upper lip, and anterior maxillary gingiva**.'),
    (v_case_id, 'Which of the following is a critical instruction that must be given to patients diagnosed with an acute orbital blowout fracture?', '["Avoid sleeping with their head elevated", "Strictly avoid blowing their nose to prevent orbital emphysema and potential optic nerve compression", "Vigorously blow their nose to clear any blood or fluid from the maxillary sinus", "Perform heavy weightlifting to reduce intraorbital venous pressure", "Apply a high-pressure patch over the eye for 72 hours"]'::jsonb, 1, 'Patients with acute orbital fractures must be **strictly instructed not to blow their nose**. Blowing the nose creates high pressure in the paranasal sinuses (maxillary/ethmoid). This pressure forces air and sinus bacteria through the fracture line into the orbit, causing **orbital emphysema** (which can compress the optic nerve and cause blindness) and increasing the risk of **orbital cellulitis**.');

    ---------------------------------------------------------------------------
    -- CASE 36: The Flying Metal Shard - Case Analysis (V4)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Flying Metal Shard - Case Analysis (V4)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Flying Metal Shard - Case Analysis (V4)', 'A 35-year-old construction worker is brought to the emergency department after a metal shard flew off a hammering tool and struck her right eye. He was not wearing safety goggles. He complains of sudden, severe pain and instant, profound loss of vision in that eye. He reports a watery discharge flowing from the eye immediately after the impact.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 90 bpm | BP: 130/80 mmHg
*   **Visual Acuity:** OD: Hand Motion (light projection intact); contralateral eye: 20/20
*   **Ocular Examination (OD):** Diffuse subconjunctival hemorrhage. The anterior chamber is shallow and filled with RBCs (microhyphema). The pupil is peaked and **teardrop-shaped**, pointing towards a 3-mm laceration at the limbus. A small amount of dark, uveal tissue (iris) is prolapsing through the wound. Examination of the wound under cobalt blue light reveals a **positive Seidel sign** (a clear stream of aqueous humor diluting and washing away fluorescein dye).', 36) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 35-year-old construction worker is brought to the emergency department after a metal shard flew off a hammering tool and struck her right eye. He was not wearing safety goggles. He complains of sudden, severe pain and instant, profound loss of vision in that eye. He reports a watery discharge flowing from the eye immediately after the impact.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 90 bpm | BP: 130/80 mmHg
*   **Visual Acuity:** OD: Hand Motion (light projection intact); contralateral eye: 20/20
*   **Ocular Examination (OD):** Diffuse subconjunctival hemorrhage. The anterior chamber is shallow and filled with RBCs (microhyphema). The pupil is peaked and **teardrop-shaped**, pointing towards a 3-mm laceration at the limbus. A small amount of dark, uveal tissue (iris) is prolapsing through the wound. Examination of the wound under cobalt blue light reveals a **positive Seidel sign** (a clear stream of aqueous humor diluting and washing away fluorescein dye).', "order" = 36 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the diagnosis, and what is the significance of the teardrop pupil and positive Seidel test?', '["Traumatic hyphema; teardrop pupil is due to iris sphincter rupture, Seidel test indicates red blood cells clogging the cornea", "Severe corneal abrasion; teardrop pupil is a normal physiological variant, Seidel test is positive in any tear film excess", "Orbital compartment syndrome; teardrop pupil indicates optic nerve compression, Seidel test is negative", "Ruptured globe / open globe injury; teardrop pupil points to the site of wound, positive Seidel test indicates active aqueous leakage from a full-thickness laceration", "Traumatic uveitis; teardrop pupil represents severe ciliary spasm, Seidel test is positive due to high protein exudation"]'::jsonb, 3, 'This is a **ruptured globe (open globe injury)**, a surgical emergency. The **teardrop pupil** is highly characteristic, as intraocular pressure forces the iris to prolapse towards the escape wound, pointing like an arrow to the laceration. The **positive Seidel test** (aqueous fluid stream washing away fluorescein dye under cobalt blue light) confirms a **full-thickness wound** with active external leakage of aqueous humor.'),
    (v_case_id, 'Which of the following is strictly CONTRAINDICATED during the emergency department evaluation of a suspected ruptured globe?', '["Ordering a high-resolution CT scan of the orbits without contrast", "Placing a rigid, non-contact eye shield resting on the orbital bones", "Administering systemic intravenous antibiotics and antiemetics", "Performing applanation tonometry (IOP measurement) or applying any pressure to the globe", "Keeping the patient strictly NPO (nothing by mouth) for surgery"]'::jsonb, 3, 'In a suspected ruptured globe, **any manipulation or pressure on the eye is strictly contraindicated**. This includes performing **tonometry (IOP measurement)**, opening the eyelids forcibly, or performing a dilated fundus exam. Any external pressure can cause **extrusion of the intraocular contents** (iris, lens, vitreous, retina) through the wound, resulting in irreversible blindness.'),
    (v_case_id, 'What are the immediate, first-line management steps for a patient with a confirmed ruptured globe in the emergency department?', '["Perform immediate bedside surgical suturing of the cornea under topical anesthesia", "Place a rigid metal/plastic eye shield, keep NPO, initiate IV broad-spectrum antibiotics, administer IV antiemetics, update tetanus, and schedule urgent surgical repair within 24 hours", "Apply a tight pressure patch, prescribe oral pain medications, and schedule outpatient ophthalmology follow-up in 1 week", "Instill topical corticosteroid and anesthetic drops hourly, and discharge the patient home", "Perform immediate anterior chamber paracentesis to lower the intraocular pressure"]'::jsonb, 1, 'Immediate management of a ruptured globe includes: (1) placing a **rigid eye shield** (e.g. Fox shield) resting on the brow and cheek bones (never place a patch or pad that contacts the eyelids), (2) keeping the patient **strictly NPO** in preparation for urgent surgery, (3) administering **IV broad-spectrum antibiotics** (e.g., cefazolin + levofloxacin) to prevent endophthalmitis, (4) administering **IV antiemetics** (e.g., ondansetron) to prevent vomiting (which raises intraocular pressure), (5) updating **tetanus status**, and (6) securing **urgent surgical closure** in the OR within 24 hours.');

    ---------------------------------------------------------------------------
    -- CASE 37: The Rock-Hard Orbit - Case Analysis (V4)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Rock-Hard Orbit - Case Analysis (V4)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Rock-Hard Orbit - Case Analysis (V4)', 'A 26-year-old male presents to the emergency department immediately after sustaining severe blunt facial trauma from a baseball bat. He reports excruciating pain and rapidly progressive vision loss in the right eye.  He has a history of mild hypertension.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 105 bpm | BP: 142/90 mmHg
*   **Visual Acuity:** OD: 20/400 (no improvement with pinhole); contralateral eye: 20/20
*   **Ocular Examination (OD):** Extreme, tense **proptosis** and massive subconjunctival hemorrhage. The eyelids are extremely swollen, tense, and **rock-hard to palpation**, making it highly difficult to separate them. There is a prominent **relative afferent pupillary defect (RAPD)** in the affected eye. Extraocular movements are completely restricted in all directions (ophthalmoplegia). The intraocular pressure is 51 mmHg.', 37) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 26-year-old male presents to the emergency department immediately after sustaining severe blunt facial trauma from a baseball bat. He reports excruciating pain and rapidly progressive vision loss in the right eye.  He has a history of mild hypertension.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 105 bpm | BP: 142/90 mmHg
*   **Visual Acuity:** OD: 20/400 (no improvement with pinhole); contralateral eye: 20/20
*   **Ocular Examination (OD):** Extreme, tense **proptosis** and massive subconjunctival hemorrhage. The eyelids are extremely swollen, tense, and **rock-hard to palpation**, making it highly difficult to separate them. There is a prominent **relative afferent pupillary defect (RAPD)** in the affected eye. Extraocular movements are completely restricted in all directions (ophthalmoplegia). The intraocular pressure is 51 mmHg.', "order" = 37 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the diagnosis, and what is the most urgent, vision-saving intervention for this patient?', '["Blowout fracture; order an urgent facial CT scan and administer oral prednisone", "Ruptured globe; immediate surgical exploration in the operating room", "Optic neuritis; initiate high-dose intravenous methylprednisolone within 1 hour", "Carotid-cavernous fistula; urgent carotid artery angiography and embolization", "Orbital Compartment Syndrome (OCS) due to retrobulbar hemorrhage; immediate bedside lateral canthotomy and cantholysis"]'::jsonb, 4, 'This patient has **Orbital Compartment Syndrome (OCS)** secondary to a **retrobulbar hemorrhage** (bleeding behind the eye). This is a vision-threatening emergency. The most urgent intervention is **immediate bedside lateral canthotomy and cantholysis (LCC)**. LCC must be performed **immediately at the bedside without waiting for CT scans or ophthalmology arrival**, as irreversible ischemic blindness occurs within 90-120 minutes.'),
    (v_case_id, 'What is the primary pathophysiological mechanism by which OCS leads to rapid, irreversible blindness?', '["Chronic bacterial infection spreads from the retrobulbar space to the brain", "The compression forces the crystalline lens backward, crushing the vitreous", "The blood in the orbit triggers a rapid, autoimmune destruction of the contralateral retina", "High intraorbital pressure compromises perfusion to the optic nerve and retina, causing central retinal artery occlusion or ischemic optic neuropathy", "The retrobulbar blood directly dissects into the optic nerve sheath and destroys axons"]'::jsonb, 3, 'Because the orbit is a closed, rigid bony compartment bounded anteriorly by the stiff orbital septum and eyelids, a **retrobulbar hemorrhage** causes a rapid rise in intraorbital pressure. When the orbital pressure exceeds the perfusion pressure of the microvasculature, it **compromises blood flow to the optic nerve and retina**, resulting in **central retinal artery occlusion (CRAO)** or **anterior/posterior ischemic optic neuropathy**.'),
    (v_case_id, 'How does performing a lateral canthotomy and cantholysis relieve the elevated intraorbital pressure?', '["It paralyzes the extraocular muscles, reducing metabolic demand", "It releases the lateral palpebral ligament, allowing the eyelids and orbital contents to expand forward, rapidly reducing intraorbital pressure", "It allows the retrobulbar blood to drain completely out of the lateral wound", "It directly decompresses the maxillary sinus to relieve pressure", "It allows the surgeon to physically push the globe back into the orbit"]'::jsonb, 1, 'Performing a **lateral canthotomy** (cutting the lateral canthal tendon) and **cantholysis** (specifically cutting the superior and inferior crus of the lateral palpebral ligament) **releases the attachment of the eyelids to the lateral orbital rim**. This allows the **eyelids and globe to expand forward (increasing proptosis)**, which rapidly decompresses the closed orbital compartment, lowering the pressure from dangerous levels (>40-50 mmHg) to safe levels almost instantly.');

    ---------------------------------------------------------------------------
    -- CASE 38: The Numb RAPD - Case Analysis (V4)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Numb RAPD - Case Analysis (V4)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Numb RAPD - Case Analysis (V4)', 'A 31-year-old male is brought to the emergency department after falling off a bicycle and striking the right side of his forehead against the concrete curb. He did not lose consciousness but complains of profound, painless vision loss in his right eye. He has no other injuries.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 76 bpm | BP: 120/80 mmHg
*   **Visual Acuity:** OD: 20/400; contralateral eye: 20/20
*   **Ocular Examination (OD):** Mild bruising over the forehead and brow. The globe is completely intact, eyelids are soft, and anterior chamber is quiet. IOP is 14 mmHg OU. However, there is a **prominent relative afferent pupillary defect (RAPD)** in the affected eye. Dilated fundus examination reveals a **completely normal optic nerve head** with healthy color and sharp margins. Contralateral eye is normal.', 38) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 31-year-old male is brought to the emergency department after falling off a bicycle and striking the right side of his forehead against the concrete curb. He did not lose consciousness but complains of profound, painless vision loss in his right eye. He has no other injuries.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 76 bpm | BP: 120/80 mmHg
*   **Visual Acuity:** OD: 20/400; contralateral eye: 20/20
*   **Ocular Examination (OD):** Mild bruising over the forehead and brow. The globe is completely intact, eyelids are soft, and anterior chamber is quiet. IOP is 14 mmHg OU. However, there is a **prominent relative afferent pupillary defect (RAPD)** in the affected eye. Dilated fundus examination reveals a **completely normal optic nerve head** with healthy color and sharp margins. Contralateral eye is normal.', "order" = 38 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the most likely diagnosis?', '["Retinal detachment", "Central retinal artery occlusion (CRAO)", "Traumatic Optic Neuropathy (TON)", "Acute optic neuritis", "Malingering or functional vision loss"]'::jsonb, 2, 'This patient has **Traumatic Optic Neuropathy (TON)**, which classically presents as **profound vision loss** following blunt head or orbital trauma, accompanied by a **relative afferent pupillary defect (RAPD)**, in the setting of a **completely normal-appearing optic nerve head** acutely. The nerve is damaged retrobulbar (often inside the optic canal).'),
    (v_case_id, 'Why does the optic nerve head appear completely normal during the acute phase of Traumatic Optic Neuropathy?', '["The nerve is temporarily stunned (neuropraxia) and does not undergo physical changes", "The visual loss is purely psychological and there is no real nerve damage", "The injury is retrobulbar (within the optic canal), and retrograde degeneration of the axons takes 4 to 6 weeks to manifest as disc pallor", "The contralateral eye is compensating by sending blood flow to the damaged disc", "The swollen optic nerve is hidden by the vitreous gel"]'::jsonb, 2, 'Acutely, the optic disc appears **completely normal** because the site of injury in TON is typically **retrobulbar** (most commonly within the bony **optic canal**, where the nerve is sheared or compressed by bone fragments or microvascular ischemia). It takes **4 to 6 weeks for retrograde axoplasmic degeneration** to travel from the site of injury back to the optic nerve head, at which point the disc will develop permanent **optic atrophy and pallor**.'),
    (v_case_id, 'Which of the following is the diagnostic test of choice to evaluate a patient with suspected Traumatic Optic Neuropathy?', '["Fluorescein angiography of the retina", "High-resolution CT scan of the brain and orbits with thin cuts through the optic canal", "Electroretinography (ERG)", "Ocular B-scan ultrasound of the posterior segment", "Lumbar puncture to measure cerebrospinal fluid opening pressure"]'::jsonb, 1, 'The diagnostic test of choice is a **high-resolution CT scan of the brain and orbits with thin cuts (1 mm) through the optic canal**. This is essential to evaluate for **optic canal fractures**, bony spicules compressing the nerve, or hematomas within the canal that might warrant surgical decompression.');

    ---------------------------------------------------------------------------
    -- CASE 39: The Torn Tear Duct - Case Analysis (V4)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Torn Tear Duct - Case Analysis (V4)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Torn Tear Duct - Case Analysis (V4)', 'An 10-year-old child is brought to the emergency department by her parents after being scratched in the face by a dog. The child is crying but has no systemic symptoms. The parents note a deep cut in the child''s left lower eyelid.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 85 bpm | BP: 110/70 mmHg
*   **Visual Acuity:** Bilateral 20/20 (corrected)
*   **Ocular Examination:** The left globe is completely intact, with no conjunctival injection, clear cornea, and quiet anterior chamber. However, there is a deep, full-thickness **laceration of the left lower eyelid medial to the punctum**, completely transecting the medial canthal angle and the **lower lacrimal canaliculus**. The laceration extends down to the orbicularis oculi muscle.', 39) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'An 10-year-old child is brought to the emergency department by her parents after being scratched in the face by a dog. The child is crying but has no systemic symptoms. The parents note a deep cut in the child''s left lower eyelid.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 85 bpm | BP: 110/70 mmHg
*   **Visual Acuity:** Bilateral 20/20 (corrected)
*   **Ocular Examination:** The left globe is completely intact, with no conjunctival injection, clear cornea, and quiet anterior chamber. However, there is a deep, full-thickness **laceration of the left lower eyelid medial to the punctum**, completely transecting the medial canthal angle and the **lower lacrimal canaliculus**. The laceration extends down to the orbicularis oculi muscle.', "order" = 39 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the management, and where should this repair ideally be performed?', '["Applying a tight pressure patch for 2 weeks and letting the tear duct heal spontaneously", "Surgical repair in the operating room under microscopic visualization, involving canalicular stenting (e.g. Crawford or monocanalicular stent) and meticulous suturing", "Performing immediate surgical excision of the entire lacrimal gland", "Simple bedside closure of the skin laceration using steri-strips or skin glue", "Prescribing oral antibiotics and sending the child home without closure"]'::jsonb, 1, 'A lid laceration medial to the punctum that **transects the lacrimal canaliculus** requires specialized **surgical repair in the operating room**. Under microscopic magnification, the cut ends of the canaliculus must be identified, **stented with a silicone tube** (e.g., Crawford stent or Monoka) to maintain the patency of the lumen during healing, and the surrounding tissues repaired meticulously. Simple skin suturing is a failure of care.'),
    (v_case_id, 'What is the primary long-term complication if a canalicular laceration is not repaired or is repaired poorly?', '["Severe, progressive orbital blowout fracture and diplopia", "Chronic, intractable dry eye syndrome due to lacrimal hypersecretion", "Autoimmune sympathetic ophthalmia in the contralateral eye", "Permanent loss of central visual acuity and macular edema", "Chronic, debilitating epiphora (overflow of tears) due to disruption of the tear drainage system"]'::jsonb, 4, 'The lower canaliculus carries approximately 70% of the tear drainage from the ocular surface to the lacrimal sac. If the canaliculus is not repaired or heals with scarring/occlusion, the patient will develop **chronic, debilitating epiphora (persistent tearing and overflow of tears)**. This causes significant visual blurring and skin irritation.'),
    (v_case_id, 'Which critical muscle and tendon structures are located in the medial canthus and must be carefully reanchored during repair to prevent eyelid deformity?', '["Medial canthal tendon and orbicularis oculi muscle", "Inferior rectus muscle and lockwood''s ligament", "Corrugator supercilii and frontalis muscle", "Superior oblique muscle and Tenon''s capsule", "Lateral palpebral ligament and levator palpebrae superioris"]'::jsonb, 0, 'The **medial canthal tendon** and the **pars lacrimalis of the orbicularis oculi muscle (Horner''s muscle)** are located medially and are responsible for anchoring the eyelid to the lacrimal bone and driving the ''lacrimal pump'' that sucks tears into the drainage system. Failure to carefully reanchor these structures leads to **ectropion** (eyelid turning outward), medial canthal rounding, and permanent tearing dysfunction.');

    ---------------------------------------------------------------------------
    -- CASE 40: The Hammer and Siderosis - Case Analysis (V4)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'The Hammer and Siderosis - Case Analysis (V4)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'The Hammer and Siderosis - Case Analysis (V4)', 'A 33-year-old carpenter presents with mild discomfort and slightly blurry vision in his right eye.  He reports that he was hammering steel-on-steel 2 days ago without safety goggles when he felt a tiny ''tweak'' or splash of water in his eye, but did not think much of it until the vision became slightly fuzzy today.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 72 bpm | BP: 120/80 mmHg
*   **Visual Acuity:** OD: 20/40; contralateral eye: 20/20
*   **Ocular Examination (OD):** A tiny, self-sealing 1-mm corneal wound is visible at the 9 o''clock position. Directly behind it, there is a small **iris transillumination defect (hole)**. The lens reveals a tiny, localized **focal cataract** in the path of the injury. Dilated fundus examination reveals a small, shiny, metallic **foreign body** lodged in the vitreous cavity inferiorly, surrounded by a localized vitreous hemorrhage. No retinal detachment is seen. IOP is 12 mmHg.', 40) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 33-year-old carpenter presents with mild discomfort and slightly blurry vision in his right eye.  He reports that he was hammering steel-on-steel 2 days ago without safety goggles when he felt a tiny ''tweak'' or splash of water in his eye, but did not think much of it until the vision became slightly fuzzy today.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 72 bpm | BP: 120/80 mmHg
*   **Visual Acuity:** OD: 20/40; contralateral eye: 20/20
*   **Ocular Examination (OD):** A tiny, self-sealing 1-mm corneal wound is visible at the 9 o''clock position. Directly behind it, there is a small **iris transillumination defect (hole)**. The lens reveals a tiny, localized **focal cataract** in the path of the injury. Dilated fundus examination reveals a small, shiny, metallic **foreign body** lodged in the vitreous cavity inferiorly, surrounded by a localized vitreous hemorrhage. No retinal detachment is seen. IOP is 12 mmHg.', "order" = 40 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the diagnosis, and what is the definitive management for this patient?', '["Traumatic uveitis; initiate topical corticosteroid drops and monitor closely as an outpatient", "Ruptured globe; apply a tight pressure patch and perform daily outpatient visual acuity checks", "Corneal foreign body; perform bedside removal using a sterile needle under topical anesthesia", "Dry AMD; prescribe high-dose AREDS2 vitamins and reassure", "Penetrating Intraocular Foreign Body (IOFB); urgent surgical pars plana vitrectomy with removal of the foreign body"]'::jsonb, 4, 'This is a **Penetrating Intraocular Foreign Body (IOFB)**. Even if the entry wound is self-sealing and the eye is quiet, a foreign body lodged inside the vitreous cavity is a high risk for endophthalmitis and chronic toxicity. Definitive management is **urgent surgical pars plana vitrectomy (PPV)** to remove the foreign body, repair any retinal tears, and administer intravitreal antibiotics.'),
    (v_case_id, 'Which diagnostic imaging modality is strictly CONTRAINDICATED if a metallic intraocular foreign body is suspected?', '["Fluorescein angiography of the retina", "B-scan ultrasound of the globe", "Magnetic Resonance Imaging (MRI) of the brain and orbits", "High-resolution CT scan of the orbits without contrast", "Standard orbital X-ray (Caldwell and Waters views)"]'::jsonb, 2, 'If a metallic (ferrous) intraocular foreign body is suspected, **MRI is strictly contraindicated**. The powerful magnetic field of the MRI will cause the metallic foreign body to **move, rotate, or migrate** within the eye, leading to catastrophic shearing of the retina, vitreous hemorrhage, or lens rupture. **High-resolution CT scan** is the gold standard imaging modality of choice.'),
    (v_case_id, 'What is the chronic, blinding toxicity condition that occurs if a ferrous (iron-containing) intraocular foreign body is left inside the eye for months or years?', '["Phacolytic glaucoma, caused by lens protein leaking through the capsule", "Chalcosis bulbi, caused by copper deposition in Descemet''s membrane", "Sympathetic ophthalmia, a granulomatous uveitis in the contralateral eye", "Siderosis bulbi, caused by iron toxicity leading to degeneration of the retina and trabecular meshwork", "Neovascular glaucoma, driven by chronic iris ischemia"]'::jsonb, 3, 'If a ferrous (iron) IOFB is left in the eye, the iron slowly oxidizes and dissolves, releasing toxic iron ions that deposit in and destroy intracellular structures. This is known as **Siderosis bulbi**. It leads to **degeneration of the retina** (manifesting as profound night blindness and pigmentary changes), **damage to the trabecular meshwork** (causing secondary open-angle glaucoma), and **cataract formation with iris heterochromia (turning the iris rusty brown)**.');

    ---------------------------------------------------------------------------
    -- CASE 41: Vignette: The Lime Splattered Eye (V5)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Vignette: The Lime Splattered Eye (V5)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Vignette: The Lime Splattered Eye (V5)', 'A 48-year-old construction worker presents to the emergency department immediately after a bag of wet concrete mix (calcium hydroxide/alkali) burst and splashed into his right eye 30 minutes ago. He reports intense, burning pain, severe tearing, and an inability to open the eye. He rinsed the eye for about 2 minutes at the site before coming in.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 95 bpm | BP: 135/85 mmHg
*   **Visual Acuity:** OD: 20/200; contralateral eye: 20/20
*   **Ocular Examination (OD):** Severe blepharospasm. After instilling topical anesthetic, slit-lamp exam reveals a moderately hazy cornea with a large epithelial defect. There is a prominent area of **limbal blanching and ischemia** (porcelain sclera) involving 180 degrees of the limbus. The conjunctiva is pale and necrotic in the blanched areas. The initial paper pH test of the conjunctival sac shows a pH of 11.0.', 41) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 48-year-old construction worker presents to the emergency department immediately after a bag of wet concrete mix (calcium hydroxide/alkali) burst and splashed into his right eye 30 minutes ago. He reports intense, burning pain, severe tearing, and an inability to open the eye. He rinsed the eye for about 2 minutes at the site before coming in.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 95 bpm | BP: 135/85 mmHg
*   **Visual Acuity:** OD: 20/200; contralateral eye: 20/20
*   **Ocular Examination (OD):** Severe blepharospasm. After instilling topical anesthetic, slit-lamp exam reveals a moderately hazy cornea with a large epithelial defect. There is a prominent area of **limbal blanching and ischemia** (porcelain sclera) involving 180 degrees of the limbus. The conjunctiva is pale and necrotic in the blanched areas. The initial paper pH test of the conjunctival sac shows a pH of 11.0.', "order" = 41 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the most immediate, critical next step in the management of this patient?', '["Prepare the patient for urgent surgical corneal transplant (penetrating keratoplasty)", "Administer systemic high-dose intravenous corticosteroids immediately", "Order an urgent CT scan of the brain and orbits to rule out foreign bodies", "Perform copious irrigation with sterile saline or water using a Morgan lens until the ocular surface pH is neutralized to 7.0 - 7.2", "Instill topical broad-spectrum antibiotic drops and apply a tight pressure patch"]'::jsonb, 3, 'An ocular chemical burn is a true emergency. The **most critical immediate step is copious irrigation** with sterile saline, balanced salt solution, or tap water (often using a Morgan lens) to flush the chemical. Irrigation must be continued continuously until the ocular surface pH is **fully neutralized (pH 7.0 - 7.2)**, measured 5-10 minutes after stopping irrigation. No other diagnostic test or treatment should delay this.'),
    (v_case_id, 'Why are alkali burns generally considered far more destructive and dangerous to the eye than acid burns?', '["Alkalies selectively crystallize within the lens, causing immediate explosive cataract", "Alkalies directly coagulate corneal proteins, forming a barrier that limits deep tissue penetration", "Alkalies trigger immediate, severe bacterial keratitis within minutes of contact", "Alkalies induce a rapid, autoimmune destruction of the contralateral eye", "Alkalies cause saponification of cell membrane lipids and rapidly penetrate deep into the cornea and anterior chamber"]'::jsonb, 4, '**Alkali substances** (like ammonia, lye, and lime/wet concrete) are highly lipophilic and cause **saponification of cell membrane lipids**. This allows them to **rapidly penetrate** through the corneal epithelium, stroma, and into the anterior chamber within minutes, causing extensive internal damage. In contrast, **acids** cause **coagulation of corneal proteins**, which forms a physical barrier that limits further deep penetration of the acid.'),
    (v_case_id, 'What is the clinical significance of ''limbal blanching and ischemia'' in a chemical burn?', '["It indicates that the intraocular pressure has dropped to 0 mmHg", "It indicates destruction of the limbal stem cells, which are essential for regenerating the corneal epithelium, signifying a poor prognosis", "It represents a localized type I hypersensitivity reaction to concrete proteins", "It is a benign finding that represents temporary vasospasm and resolves spontaneously within 24 hours", "It signifies that a metallic foreign body is embedded in the sclera"]'::jsonb, 1, '**Limbal blanching and ischemia** (appearing as a white, bloodless ''porcelain'' ring at the cornea-sclera junction) is a severe prognostic sign. The limbus houses the **limbal epithelial stem cells**, which are responsible for the continuous regeneration and maintenance of the corneal epithelium. Destruction of these stem cells leads to chronic epithelial defects, corneal scarring, visual degradation, and conjunctivalization.');

    ---------------------------------------------------------------------------
    -- CASE 42: Vignette: The Fingernail Scratch (V5)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Vignette: The Fingernail Scratch (V5)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Vignette: The Fingernail Scratch (V5)', 'A 33-year-old male presents to the clinic with intense pain, a severe foreign body sensation, constant tearing, and photophobia in his left eye. He reports that his 8-month-old infant accidentally scratched his eye with a fingernail while playing this morning.

**Physical Examination:**
*   **Vitals:** Temp: 98.8°F | HR: 68 bpm | BP: 135/84 mmHg
*   **Visual Acuity:** OS: 20/30 (improved with pinhole); contralateral eye: 20/20
*   **Ocular Examination (OS):** Marked conjunctival injection. Instillation of fluorescein dye and examination under cobalt blue light reveals a sharply demarcated, linear, bright green glowing area of epithelial loss measuring 3 mm x 2 mm in the central cornea. There is no white corneal infiltrate, no corneal thinning, and the anterior chamber is quiet. Pupil is reactive and normal.', 42) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 33-year-old male presents to the clinic with intense pain, a severe foreign body sensation, constant tearing, and photophobia in his left eye. He reports that his 8-month-old infant accidentally scratched his eye with a fingernail while playing this morning.

**Physical Examination:**
*   **Vitals:** Temp: 98.8°F | HR: 68 bpm | BP: 135/84 mmHg
*   **Visual Acuity:** OS: 20/30 (improved with pinhole); contralateral eye: 20/20
*   **Ocular Examination (OS):** Marked conjunctival injection. Instillation of fluorescein dye and examination under cobalt blue light reveals a sharply demarcated, linear, bright green glowing area of epithelial loss measuring 3 mm x 2 mm in the central cornea. There is no white corneal infiltrate, no corneal thinning, and the anterior chamber is quiet. Pupil is reactive and normal.', "order" = 42 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the most likely diagnosis, and what is the first-line pharmacotherapy?', '["Herpes simplex dendritic keratitis; topical acyclovir gel and oral valacyclovir", "Corneal abrasion; topical broad-spectrum antibiotic drops or ointment (e.g. erythromycin or polymyxin/trimethoprim)", "Dry eye syndrome; lifetime preservative-free artificial tears only", "Corneal ulcer; immediate outpatient surgical superficial keratectomy", "Infectious bacterial keratitis; topical fortified vancomycin and tobramycin every 30 minutes"]'::jsonb, 1, 'This is a simple **corneal abrasion** (epithelial defect without underlying stromal infection). First-line therapy consists of **topical broad-spectrum antibiotic drops or ointment** to prevent secondary bacterial infection while the epithelium heals, along with oral analgesics for pain control. Ointment (e.g., erythromycin) provides lubrication and comfort.'),
    (v_case_id, 'Why is the prescription of topical anesthetic drops (e.g. proparacaine) for home pain control strictly CONTRAINDICATED in patients with corneal abrasions?', '["Topical anesthetics neutralize the efficacy of topical antibiotics", "Topical anesthetics are directly toxic to the corneal epithelium, inhibit healing, and block the protective blink reflex, leading to severe corneal melting", "Topical anesthetics cause systemic cardiovascular toxicity and bradycardia through lacrimal absorption", "Topical anesthetics promote the rapid growth of fungal spores in the stroma", "Topical anesthetics cause permanent pupillary dilation and acute angle closure"]'::jsonb, 1, 'Prescribing **topical anesthetics (like proparacaine or tetracaine) for home use is strictly contraindicated**. These drugs are **highly toxic to the corneal epithelium** (epitheliotoxic), severely retard epithelial migration and wound healing, and **abolish the protective corneal blink reflex**. Abuse of these drops leads to progressive, painless **corneal stromal melting, ulceration, and permanent scarring**.'),
    (v_case_id, 'What is the most common long-term complication of a corneal abrasion caused by organic trauma (e.g., a fingernail or tree branch)?', '["Autoimmune uveitis associated with HLA-B27", "Late-onset ectopia lentis and lens subluxation", "Recurrent corneal erosion syndrome, due to poor basement membrane adhesion", "Secondary open-angle pigmentary glaucoma", "Sympathetic ophthalmia in the contralateral eye"]'::jsonb, 2, 'A classic complication of organic abrasions (fingernails, paper cuts, tree branches) is **Recurrent Corneal Erosion (RCE) syndrome**. The regenerated corneal epithelial cells fail to form proper hemidesmosomes and adhere securely to the underlying **Bowman''s membrane and basement membrane**. Weeks or months later, typically upon opening the eyes in the morning, the dry eyelid adheres to the loose epithelium and rips it off, causing a recurrence of severe pain and abrasion.');

    ---------------------------------------------------------------------------
    -- CASE 43: Vignette: The Machinist's Rust (V5)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Vignette: The Machinist''s Rust (V5)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Vignette: The Machinist''s Rust (V5)', 'A 40-year-old machinist presents with a 24-hour history of redness, gritty pain, and tearing in his left eye.  He reports that he was grinding steel yesterday afternoon without safety goggles and felt something fly into  his eye.

**Physical Examination:**
*   **Vitals:** Temp: 98.4°F | HR: 74 bpm | BP: 122/76 mmHg
*   **Visual Acuity:** OS: 20/30; contralateral eye: 20/20
*   **Ocular Examination (OS):** Slit-lamp biomicroscopy reveals a tiny, dark, metallic foreign body embedded in the superficial corneal stroma at the 4 o''clock position, outside of the visual axis. The foreign body is surrounded by a distinct, circular, orange-brown halo of **rust ring** diffusing into the stroma. The anterior chamber is deep and quiet (0 cells). No Seidel sign is present.', 43) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 40-year-old machinist presents with a 24-hour history of redness, gritty pain, and tearing in his left eye.  He reports that he was grinding steel yesterday afternoon without safety goggles and felt something fly into  his eye.

**Physical Examination:**
*   **Vitals:** Temp: 98.4°F | HR: 74 bpm | BP: 122/76 mmHg
*   **Visual Acuity:** OS: 20/30; contralateral eye: 20/20
*   **Ocular Examination (OS):** Slit-lamp biomicroscopy reveals a tiny, dark, metallic foreign body embedded in the superficial corneal stroma at the 4 o''clock position, outside of the visual axis. The foreign body is surrounded by a distinct, circular, orange-brown halo of **rust ring** diffusing into the stroma. The anterior chamber is deep and quiet (0 cells). No Seidel sign is present.', "order" = 43 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the correct management of this patient''s corneal foreign body and associated rust ring?', '["Flush the eye with systemic chelating agents (EDTA) for 12 hours", "Refer the patient for urgent surgical lamellar keratoplasty in the operating room", "Apply a pressure patch for 1 week and wait for the rust ring to dissolve systemically", "Initiate topical corticosteroid drops hourly to dissolve the iron deposits", "Remove the metallic foreign body immediately, and remove the rust ring either today or within 24-48 hours using a sterile needle, spud, or rotating ophthalmic burr under slit-lamp visualization"]'::jsonb, 4, 'Management requires **removal of both the foreign body and the rust ring**. The metallic foreign body is removed immediately using a sterile needle or spud under slit-lamp magnification. The **rust ring** (oxidized iron that diffuses into the stroma) is toxic and retards healing; it must be removed either at the same time or within 24-48 hours (when it softens) using a **rotating ophthalmic burr (Algerbrush)** or needle.'),
    (v_case_id, 'Within what timeframe does a metallic iron-containing corneal foreign body begin to form a visible rust ring in the stroma?', '["Immediately upon impact (within seconds)", "Only after 1 to 2 weeks of neglect", "Iron foreign bodies never form rust rings in the eye", "Within 8 to 24 hours of injury", "Exactly 30 days post-injury"]'::jsonb, 3, 'A metallic, iron-containing foreign body oxidizes rapidly when exposed to the moist environment of the tear film and corneal stroma. A **visible orange-brown rust ring** of iron deposition begins to form in the surrounding stroma **within 8 to 24 hours** of the injury. Early removal of the foreign body prevents extensive rust ring formation.'),
    (v_case_id, 'Following the removal of a corneal foreign body, which of the following is essential to prevent secondary complications?', '["Dilating the pupil with atropine for 6 months to maintain muscle rest", "Implantation of a soft contact lens directly over the rust ring", "Topical broad-spectrum antibiotics, checking tetanus vaccination status, and avoiding patching if the wound is dirty", "Topical corticosteroid drops every hour for 2 weeks to prevent scarring", "Oral acyclovir to prevent viral activation"]'::jsonb, 2, 'Following foreign body and rust removal, the patient has a corneal epithelial defect (abrasion). Essential care includes **topical broad-spectrum antibiotics** (drops/ointment) to prevent bacterial keratitis, and **updating their tetanus vaccination status** (as corneal wounds can rarely harbor tetanus). The eye is typically **not patched** if there is any suspicion of organic contamination or Pseudomonas risk (e.g. contact lens wearers).');

    ---------------------------------------------------------------------------
    -- CASE 44: Vignette: The Squash Ball Collision (V5)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Vignette: The Squash Ball Collision (V5)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Vignette: The Squash Ball Collision (V5)', 'A 20-year-old African American female presents to the emergency department after being struck directly in the left eye by a squash ball during a game. She reports sudden, severe pain and a dramatic decrease in vision. She denies any prior eye problems but notes she has sickle cell trait.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 88 bpm | BP: 122/78 mmHg
*   **Visual Acuity:** OS: 20/100; contralateral eye: 20/20
*   **Ocular Examination (OS):** Periorbital ecchymosis. Slit-lamp biomicroscopy reveals a prominent, layered column of red blood cells filling the inferior 30% of the anterior chamber (Grade II hyphema). The pupil is sluggish. The ciliary body is intact, and there is no open globe injury. The intraocular pressure is 34 mmHg (significantly elevated).', 44) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 20-year-old African American female presents to the emergency department after being struck directly in the left eye by a squash ball during a game. She reports sudden, severe pain and a dramatic decrease in vision. She denies any prior eye problems but notes she has sickle cell trait.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 88 bpm | BP: 122/78 mmHg
*   **Visual Acuity:** OS: 20/100; contralateral eye: 20/20
*   **Ocular Examination (OS):** Periorbital ecchymosis. Slit-lamp biomicroscopy reveals a prominent, layered column of red blood cells filling the inferior 30% of the anterior chamber (Grade II hyphema). The pupil is sluggish. The ciliary body is intact, and there is no open globe injury. The intraocular pressure is 34 mmHg (significantly elevated).', "order" = 44 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the primary underlying anatomical source of blood in a traumatic hyphema?', '["Bleeding from the retinal arterioles that dissects forward through the vitreous", "Exudative hemorrhage from damaged corneal endothelial cells", "Rupture of the blood vessels of the ciliary body face or iris root due to blunt contusion forces", "Rupture of ciliary body processes due to systemic hypertension", "Rupture of Schlemm''s canal with retrograde venous flow into the chamber"]'::jsonb, 2, 'A traumatic hyphema (blood in the anterior chamber) is caused by blunt contusion forces that compress the globe along its axial diameter and expand it equatorially. This sudden stretching force tears the anterior segment tissues, resulting in the **rupture of blood vessels of the ciliary body face, iris root, or major arterial circle of the iris**.'),
    (v_case_id, 'Why is a traumatic hyphema particularly dangerous in patients with sickle cell trait or disease, and what is the target IOP management?', '["Sickle cell patients are completely immune to elevated IOP, so no treatment is required", "Sickle cell trait prevents the blood from clotting, causing continuous, unstoppable bleeding that fills the entire eye", "Sickled erythrocytes are rigid and clog the trabecular meshwork, causing rapid, severe IOP elevation; even mild IOP elevation (>24 mmHg) can cause optic nerve ischemia, requiring aggressive control and avoiding systemic acetazolamide", "Sickle cell patients have fragile corneas that melt rapidly when exposed to red blood cells in the anterior chamber", "The blood in the anterior chamber reacts with sickle hemoglobin to cause irreversible iris necrosis within 2 hours"]'::jsonb, 2, 'Hyphema in a **sickle cell** patient is a high-risk situation. In the hypoxic, hyperosmolar anterior chamber, red blood cells sickling occurs. The rigid **sickled erythrocytes clog the trabecular meshwork**, causing rapid, severe IOP spikes. Furthermore, the compromised microcirculation of the optic nerve head in sickle cell patients makes them highly vulnerable to ischemic damage, so **even mild IOP elevations (>24 mmHg for >24 hours) can cause permanent optic nerve atrophy or central retinal artery occlusion**. Systemic **acetazolamide is strictly contraindicated** as it promotes sickling.'),
    (v_case_id, 'What represents the core conservative management recommendations for a patient with an uncomplicated traumatic hyphema?', '["Applying a tight pressure patch and scheduling follow-up in 1 month", "Immediate outpatient surgical anterior chamber washout and trabeculectomy", "Bed rest with head of bed elevated 30-45 degrees, a rigid eye shield, topical cycloplegic drops, and avoiding aspirin/NSAIDs", "Strict flat bed rest, a pressure patch, daily aspirin to prevent clotting, and hourly topical corticosteroids", "Initiation of systemic anticoagulation (warfarin) and vigorous physical exercise to clear the blood"]'::jsonb, 2, 'Conservative management for hyphema includes: (1) **bed rest with the head of the bed elevated 30 to 45 degrees** (allows blood to settle inferiorly, clearing the visual axis and preventing trabecular clogging), (2) a **rigid metal or plastic eye shield** to prevent accidental touch, (3) **topical cycloplegic drops** (e.g. atropine/cyclopentolate) for pupillary rest and pain control, and (4) **avoiding aspirin/NSAIDs** (which increase the risk of re-bleeding, typically occurring on days 3-5).');

    ---------------------------------------------------------------------------
    -- CASE 45: Vignette: The Fist and Floor (V5)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Vignette: The Fist and Floor (V5)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Vignette: The Fist and Floor (V5)', 'A 20-year-old female presents to the emergency department after being punched in the left eye during a street fight. She complains of pain, severe swelling, bruising, and double vision (diplopia), especially when looking up.  She also notes that her left cheek and upper lip feel numb.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 82 bpm | BP: 120/80 mmHg
*   **Ocular Examination (OS):** Marked periorbital ecchymosis and edema. Subconjunctival hemorrhage is present. There is **vertical diplopia on upgaze**, and testing of extraocular motility reveals a severe **restriction of elevation** in the affected eye. Sensation to light touch is significantly decreased over the ipsilateral cheek, side of the nose, and upper lip. CT scan of the orbits reveals a fracture of the **orbital floor** with herniation of orbital fat and entrapment of the **inferior rectus muscle**.', 45) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 20-year-old female presents to the emergency department after being punched in the left eye during a street fight. She complains of pain, severe swelling, bruising, and double vision (diplopia), especially when looking up.  She also notes that her left cheek and upper lip feel numb.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 82 bpm | BP: 120/80 mmHg
*   **Ocular Examination (OS):** Marked periorbital ecchymosis and edema. Subconjunctival hemorrhage is present. There is **vertical diplopia on upgaze**, and testing of extraocular motility reveals a severe **restriction of elevation** in the affected eye. Sensation to light touch is significantly decreased over the ipsilateral cheek, side of the nose, and upper lip. CT scan of the orbits reveals a fracture of the **orbital floor** with herniation of orbital fat and entrapment of the **inferior rectus muscle**.', "order" = 45 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the diagnosis, and which extraocular muscle is classically entrapped in this condition?', '["Medial orbital wall blowout fracture; entrapment of the medial rectus muscle", "Orbital roof blowout fracture; entrapment of the superior rectus muscle", "Orbital floor blowout fracture; entrapment of the inferior rectus muscle", "Superior orbital fissure syndrome; entrapment of all extraocular muscles", "Lateral orbital wall fracture; entrapment of the lateral rectus muscle"]'::jsonb, 2, 'This patient has an **orbital floor blowout fracture** (the most common type). The classic presentation is **vertical diplopia on upgaze** and **restriction of eye elevation** due to the mechanical **entrapment of the inferior rectus muscle** (and/or surrounding orbital fat/fascia) within the fractured bony fragments of the maxillary bone.'),
    (v_case_id, 'Which cranial nerve is injured, resulting in the numbness of the cheek, side of the nose, and upper lip?', '["Infraorbital nerve, a branch of the maxillary division of the trigeminal nerve (CN V2)", "Facial nerve (CN VII), buccal branch", "Abducens nerve (CN VI)", "Oculomotor nerve (CN III), inferior division", "Supraorbital nerve, a branch of the ophthalmic division of the trigeminal nerve (CN V1)"]'::jsonb, 0, 'The **infraorbital nerve** (a terminal branch of the **maxillary division of the trigeminal nerve, CN V2**) travels along the infraorbital groove and canal in the orbital floor. Fractures of the orbital floor frequently bruise, compress, or lacerate this nerve, resulting in **hypoesthesia/numbness of the ipsilateral cheek, lateral nose, upper lip, and anterior maxillary gingiva**.'),
    (v_case_id, 'Which of the following is a critical instruction that must be given to patients diagnosed with an acute orbital blowout fracture?', '["Apply a high-pressure patch over the eye for 72 hours", "Vigorously blow their nose to clear any blood or fluid from the maxillary sinus", "Strictly avoid blowing their nose to prevent orbital emphysema and potential optic nerve compression", "Avoid sleeping with their head elevated", "Perform heavy weightlifting to reduce intraorbital venous pressure"]'::jsonb, 2, 'Patients with acute orbital fractures must be **strictly instructed not to blow their nose**. Blowing the nose creates high pressure in the paranasal sinuses (maxillary/ethmoid). This pressure forces air and sinus bacteria through the fracture line into the orbit, causing **orbital emphysema** (which can compress the optic nerve and cause blindness) and increasing the risk of **orbital cellulitis**.');

    ---------------------------------------------------------------------------
    -- CASE 46: Vignette: The Flying Metal Shard (V5)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Vignette: The Flying Metal Shard (V5)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Vignette: The Flying Metal Shard (V5)', 'A 33-year-old construction worker is brought to the emergency department after a metal shard flew off a hammering tool and struck her left eye. He was not wearing safety goggles. He complains of sudden, severe pain and instant, profound loss of vision in that eye. He reports a watery discharge flowing from the eye immediately after the impact.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 90 bpm | BP: 130/80 mmHg
*   **Visual Acuity:** OS: Hand Motion (light projection intact); contralateral eye: 20/20
*   **Ocular Examination (OS):** Diffuse subconjunctival hemorrhage. The anterior chamber is shallow and filled with RBCs (microhyphema). The pupil is peaked and **teardrop-shaped**, pointing towards a 3-mm laceration at the limbus. A small amount of dark, uveal tissue (iris) is prolapsing through the wound. Examination of the wound under cobalt blue light reveals a **positive Seidel sign** (a clear stream of aqueous humor diluting and washing away fluorescein dye).', 46) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 33-year-old construction worker is brought to the emergency department after a metal shard flew off a hammering tool and struck her left eye. He was not wearing safety goggles. He complains of sudden, severe pain and instant, profound loss of vision in that eye. He reports a watery discharge flowing from the eye immediately after the impact.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 90 bpm | BP: 130/80 mmHg
*   **Visual Acuity:** OS: Hand Motion (light projection intact); contralateral eye: 20/20
*   **Ocular Examination (OS):** Diffuse subconjunctival hemorrhage. The anterior chamber is shallow and filled with RBCs (microhyphema). The pupil is peaked and **teardrop-shaped**, pointing towards a 3-mm laceration at the limbus. A small amount of dark, uveal tissue (iris) is prolapsing through the wound. Examination of the wound under cobalt blue light reveals a **positive Seidel sign** (a clear stream of aqueous humor diluting and washing away fluorescein dye).', "order" = 46 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the diagnosis, and what is the significance of the teardrop pupil and positive Seidel test?', '["Traumatic uveitis; teardrop pupil represents severe ciliary spasm, Seidel test is positive due to high protein exudation", "Severe corneal abrasion; teardrop pupil is a normal physiological variant, Seidel test is positive in any tear film excess", "Orbital compartment syndrome; teardrop pupil indicates optic nerve compression, Seidel test is negative", "Traumatic hyphema; teardrop pupil is due to iris sphincter rupture, Seidel test indicates red blood cells clogging the cornea", "Ruptured globe / open globe injury; teardrop pupil points to the site of wound, positive Seidel test indicates active aqueous leakage from a full-thickness laceration"]'::jsonb, 4, 'This is a **ruptured globe (open globe injury)**, a surgical emergency. The **teardrop pupil** is highly characteristic, as intraocular pressure forces the iris to prolapse towards the escape wound, pointing like an arrow to the laceration. The **positive Seidel test** (aqueous fluid stream washing away fluorescein dye under cobalt blue light) confirms a **full-thickness wound** with active external leakage of aqueous humor.'),
    (v_case_id, 'Which of the following is strictly CONTRAINDICATED during the emergency department evaluation of a suspected ruptured globe?', '["Performing applanation tonometry (IOP measurement) or applying any pressure to the globe", "Keeping the patient strictly NPO (nothing by mouth) for surgery", "Placing a rigid, non-contact eye shield resting on the orbital bones", "Administering systemic intravenous antibiotics and antiemetics", "Ordering a high-resolution CT scan of the orbits without contrast"]'::jsonb, 0, 'In a suspected ruptured globe, **any manipulation or pressure on the eye is strictly contraindicated**. This includes performing **tonometry (IOP measurement)**, opening the eyelids forcibly, or performing a dilated fundus exam. Any external pressure can cause **extrusion of the intraocular contents** (iris, lens, vitreous, retina) through the wound, resulting in irreversible blindness.'),
    (v_case_id, 'What are the immediate, first-line management steps for a patient with a confirmed ruptured globe in the emergency department?', '["Apply a tight pressure patch, prescribe oral pain medications, and schedule outpatient ophthalmology follow-up in 1 week", "Perform immediate anterior chamber paracentesis to lower the intraocular pressure", "Place a rigid metal/plastic eye shield, keep NPO, initiate IV broad-spectrum antibiotics, administer IV antiemetics, update tetanus, and schedule urgent surgical repair within 24 hours", "Perform immediate bedside surgical suturing of the cornea under topical anesthesia", "Instill topical corticosteroid and anesthetic drops hourly, and discharge the patient home"]'::jsonb, 2, 'Immediate management of a ruptured globe includes: (1) placing a **rigid eye shield** (e.g. Fox shield) resting on the brow and cheek bones (never place a patch or pad that contacts the eyelids), (2) keeping the patient **strictly NPO** in preparation for urgent surgery, (3) administering **IV broad-spectrum antibiotics** (e.g., cefazolin + levofloxacin) to prevent endophthalmitis, (4) administering **IV antiemetics** (e.g., ondansetron) to prevent vomiting (which raises intraocular pressure), (5) updating **tetanus status**, and (6) securing **urgent surgical closure** in the OR within 24 hours.');

    ---------------------------------------------------------------------------
    -- CASE 47: Vignette: The Rock-Hard Orbit (V5)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Vignette: The Rock-Hard Orbit (V5)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Vignette: The Rock-Hard Orbit (V5)', 'A 23-year-old female presents to the emergency department immediately after sustaining severe blunt facial trauma from a baseball bat. She reports excruciating pain and rapidly progressive vision loss in the left eye.  She has a history of mild hypertension.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 105 bpm | BP: 142/90 mmHg
*   **Visual Acuity:** OS: 20/400 (no improvement with pinhole); contralateral eye: 20/20
*   **Ocular Examination (OS):** Extreme, tense **proptosis** and massive subconjunctival hemorrhage. The eyelids are extremely swollen, tense, and **rock-hard to palpation**, making it highly difficult to separate them. There is a prominent **relative afferent pupillary defect (RAPD)** in the affected eye. Extraocular movements are completely restricted in all directions (ophthalmoplegia). The intraocular pressure is 53 mmHg.', 47) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 23-year-old female presents to the emergency department immediately after sustaining severe blunt facial trauma from a baseball bat. She reports excruciating pain and rapidly progressive vision loss in the left eye.  She has a history of mild hypertension.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 105 bpm | BP: 142/90 mmHg
*   **Visual Acuity:** OS: 20/400 (no improvement with pinhole); contralateral eye: 20/20
*   **Ocular Examination (OS):** Extreme, tense **proptosis** and massive subconjunctival hemorrhage. The eyelids are extremely swollen, tense, and **rock-hard to palpation**, making it highly difficult to separate them. There is a prominent **relative afferent pupillary defect (RAPD)** in the affected eye. Extraocular movements are completely restricted in all directions (ophthalmoplegia). The intraocular pressure is 53 mmHg.', "order" = 47 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the diagnosis, and what is the most urgent, vision-saving intervention for this patient?', '["Orbital Compartment Syndrome (OCS) due to retrobulbar hemorrhage; immediate bedside lateral canthotomy and cantholysis", "Optic neuritis; initiate high-dose intravenous methylprednisolone within 1 hour", "Blowout fracture; order an urgent facial CT scan and administer oral prednisone", "Ruptured globe; immediate surgical exploration in the operating room", "Carotid-cavernous fistula; urgent carotid artery angiography and embolization"]'::jsonb, 0, 'This patient has **Orbital Compartment Syndrome (OCS)** secondary to a **retrobulbar hemorrhage** (bleeding behind the eye). This is a vision-threatening emergency. The most urgent intervention is **immediate bedside lateral canthotomy and cantholysis (LCC)**. LCC must be performed **immediately at the bedside without waiting for CT scans or ophthalmology arrival**, as irreversible ischemic blindness occurs within 90-120 minutes.'),
    (v_case_id, 'What is the primary pathophysiological mechanism by which OCS leads to rapid, irreversible blindness?', '["The retrobulbar blood directly dissects into the optic nerve sheath and destroys axons", "Chronic bacterial infection spreads from the retrobulbar space to the brain", "High intraorbital pressure compromises perfusion to the optic nerve and retina, causing central retinal artery occlusion or ischemic optic neuropathy", "The compression forces the crystalline lens backward, crushing the vitreous", "The blood in the orbit triggers a rapid, autoimmune destruction of the contralateral retina"]'::jsonb, 2, 'Because the orbit is a closed, rigid bony compartment bounded anteriorly by the stiff orbital septum and eyelids, a **retrobulbar hemorrhage** causes a rapid rise in intraorbital pressure. When the orbital pressure exceeds the perfusion pressure of the microvasculature, it **compromises blood flow to the optic nerve and retina**, resulting in **central retinal artery occlusion (CRAO)** or **anterior/posterior ischemic optic neuropathy**.'),
    (v_case_id, 'How does performing a lateral canthotomy and cantholysis relieve the elevated intraorbital pressure?', '["It allows the surgeon to physically push the globe back into the orbit", "It allows the retrobulbar blood to drain completely out of the lateral wound", "It releases the lateral palpebral ligament, allowing the eyelids and orbital contents to expand forward, rapidly reducing intraorbital pressure", "It paralyzes the extraocular muscles, reducing metabolic demand", "It directly decompresses the maxillary sinus to relieve pressure"]'::jsonb, 2, 'Performing a **lateral canthotomy** (cutting the lateral canthal tendon) and **cantholysis** (specifically cutting the superior and inferior crus of the lateral palpebral ligament) **releases the attachment of the eyelids to the lateral orbital rim**. This allows the **eyelids and globe to expand forward (increasing proptosis)**, which rapidly decompresses the closed orbital compartment, lowering the pressure from dangerous levels (>40-50 mmHg) to safe levels almost instantly.');

    ---------------------------------------------------------------------------
    -- CASE 48: Vignette: The Numb RAPD (V5)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Vignette: The Numb RAPD (V5)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Vignette: The Numb RAPD (V5)', 'A 28-year-old female is brought to the emergency department after falling off a bicycle and striking the right side of her forehead against the concrete curb. She did not lose consciousness but complains of profound, painless vision loss in her right eye. She has no other injuries.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 76 bpm | BP: 120/80 mmHg
*   **Visual Acuity:** OD: 20/400; contralateral eye: 20/20
*   **Ocular Examination (OD):** Mild bruising over the forehead and brow. The globe is completely intact, eyelids are soft, and anterior chamber is quiet. IOP is 14 mmHg OU. However, there is a **prominent relative afferent pupillary defect (RAPD)** in the affected eye. Dilated fundus examination reveals a **completely normal optic nerve head** with healthy color and sharp margins. Contralateral eye is normal.', 48) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 28-year-old female is brought to the emergency department after falling off a bicycle and striking the right side of her forehead against the concrete curb. She did not lose consciousness but complains of profound, painless vision loss in her right eye. She has no other injuries.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 76 bpm | BP: 120/80 mmHg
*   **Visual Acuity:** OD: 20/400; contralateral eye: 20/20
*   **Ocular Examination (OD):** Mild bruising over the forehead and brow. The globe is completely intact, eyelids are soft, and anterior chamber is quiet. IOP is 14 mmHg OU. However, there is a **prominent relative afferent pupillary defect (RAPD)** in the affected eye. Dilated fundus examination reveals a **completely normal optic nerve head** with healthy color and sharp margins. Contralateral eye is normal.', "order" = 48 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the most likely diagnosis?', '["Malingering or functional vision loss", "Central retinal artery occlusion (CRAO)", "Traumatic Optic Neuropathy (TON)", "Retinal detachment", "Acute optic neuritis"]'::jsonb, 2, 'This patient has **Traumatic Optic Neuropathy (TON)**, which classically presents as **profound vision loss** following blunt head or orbital trauma, accompanied by a **relative afferent pupillary defect (RAPD)**, in the setting of a **completely normal-appearing optic nerve head** acutely. The nerve is damaged retrobulbar (often inside the optic canal).'),
    (v_case_id, 'Why does the optic nerve head appear completely normal during the acute phase of Traumatic Optic Neuropathy?', '["The swollen optic nerve is hidden by the vitreous gel", "The nerve is temporarily stunned (neuropraxia) and does not undergo physical changes", "The contralateral eye is compensating by sending blood flow to the damaged disc", "The injury is retrobulbar (within the optic canal), and retrograde degeneration of the axons takes 4 to 6 weeks to manifest as disc pallor", "The visual loss is purely psychological and there is no real nerve damage"]'::jsonb, 3, 'Acutely, the optic disc appears **completely normal** because the site of injury in TON is typically **retrobulbar** (most commonly within the bony **optic canal**, where the nerve is sheared or compressed by bone fragments or microvascular ischemia). It takes **4 to 6 weeks for retrograde axoplasmic degeneration** to travel from the site of injury back to the optic nerve head, at which point the disc will develop permanent **optic atrophy and pallor**.'),
    (v_case_id, 'Which of the following is the diagnostic test of choice to evaluate a patient with suspected Traumatic Optic Neuropathy?', '["Lumbar puncture to measure cerebrospinal fluid opening pressure", "Electroretinography (ERG)", "Fluorescein angiography of the retina", "Ocular B-scan ultrasound of the posterior segment", "High-resolution CT scan of the brain and orbits with thin cuts through the optic canal"]'::jsonb, 4, 'The diagnostic test of choice is a **high-resolution CT scan of the brain and orbits with thin cuts (1 mm) through the optic canal**. This is essential to evaluate for **optic canal fractures**, bony spicules compressing the nerve, or hematomas within the canal that might warrant surgical decompression.');

    ---------------------------------------------------------------------------
    -- CASE 49: Vignette: The Torn Tear Duct (V5)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Vignette: The Torn Tear Duct (V5)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Vignette: The Torn Tear Duct (V5)', 'An 11-year-old child is brought to the emergency department by his parents after being scratched in the face by a dog. The child is crying but has no systemic symptoms. The parents note a deep cut in the child''s left lower eyelid.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 85 bpm | BP: 110/70 mmHg
*   **Visual Acuity:** Bilateral 20/20 (corrected)
*   **Ocular Examination:** The left globe is completely intact, with no conjunctival injection, clear cornea, and quiet anterior chamber. However, there is a deep, full-thickness **laceration of the left lower eyelid medial to the punctum**, completely transecting the medial canthal angle and the **lower lacrimal canaliculus**. The laceration extends down to the orbicularis oculi muscle.', 49) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'An 11-year-old child is brought to the emergency department by his parents after being scratched in the face by a dog. The child is crying but has no systemic symptoms. The parents note a deep cut in the child''s left lower eyelid.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 85 bpm | BP: 110/70 mmHg
*   **Visual Acuity:** Bilateral 20/20 (corrected)
*   **Ocular Examination:** The left globe is completely intact, with no conjunctival injection, clear cornea, and quiet anterior chamber. However, there is a deep, full-thickness **laceration of the left lower eyelid medial to the punctum**, completely transecting the medial canthal angle and the **lower lacrimal canaliculus**. The laceration extends down to the orbicularis oculi muscle.', "order" = 49 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the management, and where should this repair ideally be performed?', '["Performing immediate surgical excision of the entire lacrimal gland", "Surgical repair in the operating room under microscopic visualization, involving canalicular stenting (e.g. Crawford or monocanalicular stent) and meticulous suturing", "Prescribing oral antibiotics and sending the child home without closure", "Simple bedside closure of the skin laceration using steri-strips or skin glue", "Applying a tight pressure patch for 2 weeks and letting the tear duct heal spontaneously"]'::jsonb, 1, 'A lid laceration medial to the punctum that **transects the lacrimal canaliculus** requires specialized **surgical repair in the operating room**. Under microscopic magnification, the cut ends of the canaliculus must be identified, **stented with a silicone tube** (e.g., Crawford stent or Monoka) to maintain the patency of the lumen during healing, and the surrounding tissues repaired meticulously. Simple skin suturing is a failure of care.'),
    (v_case_id, 'What is the primary long-term complication if a canalicular laceration is not repaired or is repaired poorly?', '["Chronic, intractable dry eye syndrome due to lacrimal hypersecretion", "Chronic, debilitating epiphora (overflow of tears) due to disruption of the tear drainage system", "Severe, progressive orbital blowout fracture and diplopia", "Permanent loss of central visual acuity and macular edema", "Autoimmune sympathetic ophthalmia in the contralateral eye"]'::jsonb, 1, 'The lower canaliculus carries approximately 70% of the tear drainage from the ocular surface to the lacrimal sac. If the canaliculus is not repaired or heals with scarring/occlusion, the patient will develop **chronic, debilitating epiphora (persistent tearing and overflow of tears)**. This causes significant visual blurring and skin irritation.'),
    (v_case_id, 'Which critical muscle and tendon structures are located in the medial canthus and must be carefully reanchored during repair to prevent eyelid deformity?', '["Corrugator supercilii and frontalis muscle", "Medial canthal tendon and orbicularis oculi muscle", "Superior oblique muscle and Tenon''s capsule", "Inferior rectus muscle and lockwood''s ligament", "Lateral palpebral ligament and levator palpebrae superioris"]'::jsonb, 1, 'The **medial canthal tendon** and the **pars lacrimalis of the orbicularis oculi muscle (Horner''s muscle)** are located medially and are responsible for anchoring the eyelid to the lacrimal bone and driving the ''lacrimal pump'' that sucks tears into the drainage system. Failure to carefully reanchor these structures leads to **ectropion** (eyelid turning outward), medial canthal rounding, and permanent tearing dysfunction.');

    ---------------------------------------------------------------------------
    -- CASE 50: Vignette: The Hammer and Siderosis (V5)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Vignette: The Hammer and Siderosis (V5)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Vignette: The Hammer and Siderosis (V5)', 'A 20-year-old carpenter presents with mild discomfort and slightly blurry vision in his left eye.  He reports that he was hammering steel-on-steel 2 days ago without safety goggles when he felt a tiny ''tweak'' or splash of water in his eye, but did not think much of it until the vision became slightly fuzzy today.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 72 bpm | BP: 120/80 mmHg
*   **Visual Acuity:** OS: 20/40; contralateral eye: 20/20
*   **Ocular Examination (OS):** A tiny, self-sealing 1-mm corneal wound is visible at the 9 o''clock position. Directly behind it, there is a small **iris transillumination defect (hole)**. The lens reveals a tiny, localized **focal cataract** in the path of the injury. Dilated fundus examination reveals a small, shiny, metallic **foreign body** lodged in the vitreous cavity inferiorly, surrounded by a localized vitreous hemorrhage. No retinal detachment is seen. IOP is 12 mmHg.', 50) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 20-year-old carpenter presents with mild discomfort and slightly blurry vision in his left eye.  He reports that he was hammering steel-on-steel 2 days ago without safety goggles when he felt a tiny ''tweak'' or splash of water in his eye, but did not think much of it until the vision became slightly fuzzy today.

**Physical Examination:**
*   **Vitals:** Temp: 98.6°F | HR: 72 bpm | BP: 120/80 mmHg
*   **Visual Acuity:** OS: 20/40; contralateral eye: 20/20
*   **Ocular Examination (OS):** A tiny, self-sealing 1-mm corneal wound is visible at the 9 o''clock position. Directly behind it, there is a small **iris transillumination defect (hole)**. The lens reveals a tiny, localized **focal cataract** in the path of the injury. Dilated fundus examination reveals a small, shiny, metallic **foreign body** lodged in the vitreous cavity inferiorly, surrounded by a localized vitreous hemorrhage. No retinal detachment is seen. IOP is 12 mmHg.', "order" = 50 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the diagnosis, and what is the definitive management for this patient?', '["Traumatic uveitis; initiate topical corticosteroid drops and monitor closely as an outpatient", "Dry AMD; prescribe high-dose AREDS2 vitamins and reassure", "Corneal foreign body; perform bedside removal using a sterile needle under topical anesthesia", "Penetrating Intraocular Foreign Body (IOFB); urgent surgical pars plana vitrectomy with removal of the foreign body", "Ruptured globe; apply a tight pressure patch and perform daily outpatient visual acuity checks"]'::jsonb, 3, 'This is a **Penetrating Intraocular Foreign Body (IOFB)**. Even if the entry wound is self-sealing and the eye is quiet, a foreign body lodged inside the vitreous cavity is a high risk for endophthalmitis and chronic toxicity. Definitive management is **urgent surgical pars plana vitrectomy (PPV)** to remove the foreign body, repair any retinal tears, and administer intravitreal antibiotics.'),
    (v_case_id, 'Which diagnostic imaging modality is strictly CONTRAINDICATED if a metallic intraocular foreign body is suspected?', '["B-scan ultrasound of the globe", "Magnetic Resonance Imaging (MRI) of the brain and orbits", "High-resolution CT scan of the orbits without contrast", "Standard orbital X-ray (Caldwell and Waters views)", "Fluorescein angiography of the retina"]'::jsonb, 1, 'If a metallic (ferrous) intraocular foreign body is suspected, **MRI is strictly contraindicated**. The powerful magnetic field of the MRI will cause the metallic foreign body to **move, rotate, or migrate** within the eye, leading to catastrophic shearing of the retina, vitreous hemorrhage, or lens rupture. **High-resolution CT scan** is the gold standard imaging modality of choice.'),
    (v_case_id, 'What is the chronic, blinding toxicity condition that occurs if a ferrous (iron-containing) intraocular foreign body is left inside the eye for months or years?', '["Phacolytic glaucoma, caused by lens protein leaking through the capsule", "Neovascular glaucoma, driven by chronic iris ischemia", "Sympathetic ophthalmia, a granulomatous uveitis in the contralateral eye", "Siderosis bulbi, caused by iron toxicity leading to degeneration of the retina and trabecular meshwork", "Chalcosis bulbi, caused by copper deposition in Descemet''s membrane"]'::jsonb, 3, 'If a ferrous (iron) IOFB is left in the eye, the iron slowly oxidizes and dissolves, releasing toxic iron ions that deposit in and destroy intracellular structures. This is known as **Siderosis bulbi**. It leads to **degeneration of the retina** (manifesting as profound night blindness and pigmentary changes), **damage to the trabecular meshwork** (causing secondary open-angle glaucoma), and **cataract formation with iris heterochromia (turning the iris rusty brown)**.');

END $$;
